catalogue/arithmetic::flushed.text:
/// A product or quotient as Excel publishes it: +0 below the normal range (see the module
/// documentation).
fn flushed(x: f64) -> f64 {
    if x.is_subnormal() { 0.0 } else { x }
}

catalogue/arithmetic::binary.text:
fn binary<'m>(
    id: FunctionId,
    arguments: &[CalcValue],
    services: &EvalServices<'m>,
    operation: fn(&Site<'m>, f64, f64) -> Step<f64>,
) -> Result<CalcValue, FunctionFault> {
    let site = Site::new(id, services);
    Site::finish(operands(&site, arguments).and_then(|(a, b)| {
        let result = operation(&site, a, b)?;
        if id == PLUS || id == MINUS {
            super::kit::out_with_subnormal(&site, Ok(result))
        } else {
            site.number(result)
        }
    }))
}

catalogue/arithmetic::operands.text:
fn operands(site: &Site<'_>, arguments: &[CalcValue]) -> Step<(f64, f64)> {
    site.scalar_operands(arguments)?;
    let a = super::kit::num_with_subnormal(site, arguments, 0)?;
    let b = super::kit::num_with_subnormal(site, arguments, 1)?;
    Ok((a, b))
}

catalogue/arithmetic::percent.text:
/// `x%` is `x / 100`.
fn percent(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    let site = Site::new(PERCENT, services);
    Site::finish(
        site.scalar_operands(arguments)
            .and_then(|()| site.number_argument(0, &arguments[0]))
            .and_then(|x| site.divide(x, 100.0))
            .and_then(|x| site.number(flushed(x))),
    )
}

catalogue/kit::num_with_subnormal.text:
/// Number coercion for a kernel that implements its own measured subnormal input policy.
/// Keep the ordinary coercions and refusals for every other kind of value.
pub(super) fn num_with_subnormal(
    site: &Site<'_>,
    arguments: &[CalcValue],
    index: usize,
) -> Step<f64> {
    match arguments[index].core_ref() {
        CoreRef::Number(n) if n.is_subnormal() => Ok(n),
        _ => num(site, arguments, index),
    }
}

catalogue/kit::out_with_subnormal.text:
/// Publish a kernel's measured subnormal result as a number; other outcomes use `out`.
/// The caller still runs the family's numeric-mode check before calculating.
pub(super) fn out_with_subnormal(
    site: &Site<'_>,
    result: Result<f64, WorksheetErrorCode>,
) -> Step<CalcValue> {
    match result {
        Ok(n) if n.is_subnormal() => Ok(CalcValue::number(n)),
        other => out(site, other),
    }
}

catalogue/text::concatenate.text:
fn concatenate(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
