catalogue/comparison::Operand::kind.text:
/// The order of kinds: numbers, then text, then logicals.
fn kind(self) -> u8 {
    match self {
        Operand::Number(_) | Operand::Overflow(_) | Operand::Blank => 0,
        Operand::Text(_) => 1,
        Operand::Logical(_) => 2,
    }
}

catalogue/comparison::Operand::blank.text:
/// The empty value of this operand's kind, which a blank compares as.
fn blank(self) -> Self {
    match self {
        Operand::Number(_) | Operand::Overflow(_) => Operand::Number(0.0),
        Operand::Text(_) => Operand::Text(&[]),
        Operand::Logical(_) => Operand::Logical(false),
        Operand::Blank => Operand::Blank,
    }
}

catalogue/comparison::order.text:
pub(super) fn order(site: &Site<'_>, arguments: &[CalcValue], want: Want) -> Step<Ordering> {
    site.scalar_operands(arguments)?;
    // Two pictures are equal when their source and alt text are; they have no order.
    if let [left, right] = arguments
        && let (Some(left), Some(right)) = (left.image_value(), right.image_value())
    {
        return match want {
            Want::Equality if left.source == right.source && left.alt_text == right.alt_text => {
                Ok(Ordering::Equal)
            }
            Want::Equality => Ok(Ordering::Less),
            Want::Order => Err(Exit::Error(crate::value::WorksheetErrorCode::Value)),
        };
    }
    let mut operands = [Operand::Blank; 2];
    for (index, argument) in arguments.iter().enumerate() {
        operands[index] = match argument.core_ref() {
            CoreRef::Number(n) if argument.is_excel_overflow() => Operand::Overflow(n),
            CoreRef::Number(n) => Operand::Number(site.argument(index, coerce::operand(n))?),
            CoreRef::Text(text) => Operand::Text(text.utf16_code_units()),
            CoreRef::Logical(b) => Operand::Logical(b),
            CoreRef::Empty | CoreRef::Missing => Operand::Blank,
            CoreRef::Error(code) => return Err(Exit::Error(code)),
            CoreRef::Array(_) | CoreRef::Reference(_) => {
                return Err(site.not_modelled(Some(index)));
            }
        };
    }
    let (left, right) = match (operands[0], operands[1]) {
        (Operand::Blank, Operand::Blank) => return Ok(Ordering::Equal),
        (Operand::Blank, other) => (other.blank(), other),
        (other, Operand::Blank) => (other, other.blank()),
        pair => pair,
    };
    match (left, right) {
        (Operand::Number(a), Operand::Number(b)) => numbers(site, a, b),
        (Operand::Overflow(a), Operand::Number(b))
        | (Operand::Number(a), Operand::Overflow(b))
        | (Operand::Overflow(a), Operand::Overflow(b)) => overflow_numbers(site, a, b),
        (Operand::Text(a), Operand::Text(b)) => {
            texts(a, b, want).map_err(|beyond| site.not_modelled(Some(beyond.operand)))
        }
        (Operand::Logical(a), Operand::Logical(b)) => Ok(a.cmp(&b)),
        (a, b) => Ok(a.kind().cmp(&b.kind())),
    }
}

catalogue/comparison::overflow_numbers.text:
/// The order of qualified overflow encodings and already-validated numeric operands.
/// Callers must retain the CalcValue qualification; arbitrary NaNs are not admitted.
pub(super) fn overflow_numbers(site: &Site<'_>, a: f64, b: f64) -> Step<Ordering> {
    if !(a.is_nan() || b.is_nan()) {
        return numbers(site, a, b);
    }
    if a.to_bits() == b.to_bits() {
        return Ok(Ordering::Equal);
    }
    if a.is_sign_negative() != b.is_sign_negative() {
        return Ok(a.total_cmp(&b));
    }
    let half = |number: f64| {
        if number.is_nan() {
            f64::from_bits(number.to_bits() - (1_u64 << 52))
        } else {
            number * 0.5
        }
    };
    numbers(site, half(a), half(b))
}

catalogue/comparison::numbers.text:
/// The order of two ordinary finite numbers. Equal numbers need no rounding. For different numbers the
/// nearness test computes their difference and [`APART`] of the larger magnitude at the call's
/// arithmetic sites, which round under its numeric mode. Numbers farther apart order by value;
/// nearer ones by their 15-digit roundings, refused ([`in_band`]) where Excel's rounding may
/// depart from the exact one and the departure could decide the comparison.
pub(super) fn numbers(site: &Site<'_>, a: f64, b: f64) -> Step<Ordering> {
    if !a.is_finite() || !b.is_finite() {
        return Err(site.not_modelled(None));
    }
    if a == b {
        return Ok(Ordering::Equal);
    }
    let difference = site.subtract(a, b)?.abs();
    let apart = site.multiply(a.abs().max(b.abs()), APART)?;
    if difference > apart || a.is_sign_negative() != b.is_sign_negative() {
        return Ok(a.total_cmp(&b));
    }
    let (Some(x), Some(y)) = (Roundings::of(a.abs()), Roundings::of(b.abs())) else {
        return Err(in_band(site));
    };
    match (x.other, y.other) {
        (None, None) if x.nearest == y.nearest => Ok(Ordering::Equal),
        (None, None) => Ok(a.total_cmp(&b)),
        _ if x.disjoint(&y) => Ok(a.total_cmp(&b)),
        _ => Err(in_band(site)),
    }
}

catalogue/comparison::in_band.text:
/// The refusal of two nearly equal numbers in a band where Excel's rounding departs from the
/// exact one (a near tie of [`NEAR_TIE_BITS`], [`TOP_BINADE`], [`FINER`]): not modelled, naming no
/// argument, since the pair decides it. Bead dc-j9k owns Excel's rule in these bands.
fn in_band(site: &Site<'_>) -> Exit {
    site.not_modelled(None)
}

catalogue/comparison::Rounded::up.text:
/// The next rounding up: one more in the last digit, carrying into a new leading digit.
fn up(self) -> Rounded {
    let digits = self.digits + 1;
    if digits == 1_000_000_000_000_000 {
        Rounded {
            digits: 100_000_000_000_000,
            exponent: self.exponent + 1,
        }
    } else {
        Rounded { digits, ..self }
    }
}

catalogue/comparison::Roundings::of.text:
/// The roundings of a finite magnitude, or `None` where Excel rounds it one digit finer
/// ([`FINER`]) or by a rule not modelled ([`TOP_BINADE`]).
fn of(magnitude: f64) -> Option<Roundings> {
    if magnitude >= TOP_BINADE
        || FINER
            .iter()
            .any(|&(low, high)| (low..=high).contains(&magnitude))
    {
        return None;
    }
    if magnitude == 0.0 {
        let zero = Rounded {
            digits: 0,
            exponent: 0,
        };
        return Some(Roundings {
            nearest: zero,
            other: None,
        });
    }
    let exact = ExactDecimal::binary(magnitude);
    let all = exact.coefficient.digits();
    let length = all.len();
    let exponent = i32::try_from(length).expect("a digit count") - 1 + exact.exponent;
    let kept = &all[..length.min(DIGITS)];
    let digits = kept.parse::<u64>().expect("decimal digits")
        * 10u64.pow(u32::try_from(DIGITS - kept.len()).expect("a digit count"));
    let down = Rounded { digits, exponent };
    if length <= DIGITS {
        return Some(Roundings {
            nearest: down,
            other: None,
        });
    }
    // With r the dropped part of the m dropped digits, the tie is at r = 10^m / 2: the number
    // rounds up from it, and is near it when |2r - 10^m| * 2^(NEAR_TIE_BITS - 1) is below the
    // coefficient.
    let dropped = u32::try_from(length - DIGITS).expect("a digit count");
    let power = Natural::pow10(dropped);
    let (_, remainder) = exact.coefficient.div_rem(&power);
    let mut twice = remainder.clone();
    twice.add(&remainder);
    let up = twice >= power;
    let distance = if up {
        twice.subtract(&power);
        twice
    } else {
        let mut gap = power.clone();
        gap.subtract(&twice);
        gap
    };
    let near = !distance.is_zero()
        && distance.times(&Natural::from_u64(1u64 << (NEAR_TIE_BITS - 1))) < exact.coefficient;
    let (nearest, other) = if up {
        (down.up(), down)
    } else {
        (down, down.up())
    };
    Some(Roundings {
        nearest,
        other: near.then_some(other),
    })
}

catalogue/comparison::Roundings::disjoin.text:
/// Whether no rounding of `self` is a rounding of `other`.
fn disjoint(&self, other: &Roundings) -> bool {
    let of = |r: &Roundings| [Some(r.nearest), r.other];
    of(self)
        .iter()
        .flatten()
        .all(|x| !of(other).iter().flatten().any(|y| x == y))
}

catalogue/comparison::texts.text:
/// The order of two texts as the comparison operators give it, or [`Beyond`] when either holds a
/// character beyond the collation's repertoire and they are not the same. For [`Want::Equality`]
/// any unequal pair is `Less`.
pub(super) fn texts(a: &[u16], b: &[u16], want: Want) -> Result<Ordering, Beyond> {
    if a == b {
        return Ok(Ordering::Equal);
    }
    let ordering = collation::compare(a, b)?;
    Ok(match want {
        Want::Equality if ordering.is_ne() => Ordering::Less,
        Want::Equality | Want::Order => ordering,
    })
}

catalogue/comparison/collation::compare.text:
/// The order of two texts as the comparison operators give it, or [`Beyond`] naming the first of
/// them whose weights are not built here.
pub(super) fn compare(a: &[u16], b: &[u16]) -> Result<Ordering, Beyond> {
    // NUL is outside the measured comparison domain, including an ASCII
    // prefix that the first pass would otherwise skip or decide by length.
    if let Some(operand) = [a, b].iter().position(|text| text.contains(&0)) {
        return Err(Beyond { operand });
    }
    let fold = |code: u16| {
        if (0x0061..=FIRST_PASS_LAST).contains(&code) {
            code - 0x20
        } else {
            code
        }
    };
    for (at, (&x, &y)) in a.iter().zip(b).enumerate() {
        if x > FIRST_PASS_LAST || y > FIRST_PASS_LAST || fold(x) != fold(y) {
            // The second pass reads the texts from there on, not from their starts.
            return weighed(&a[at..], &b[at..]);
        }
    }
    Ok(a.len().cmp(&b.len()))
}

catalogue/comparison/collation::weighed.text:
/// The second pass: the two texts' primary weights, then their diacritics as `CompareStringEx`
/// walks them ([`diacritic_order`]), then the rest of their sort keys (case, kana, specials).
fn weighed(a: &[u16], b: &[u16]) -> Result<Ordering, Beyond> {
    let left = parts(a);
    let right = parts(b);
    if left.is_err() || right.is_err() {
        return leading_order(&left, &right)
            .or_else(|| match (left.is_ok(), right.is_ok()) {
                (true, false) if measured_iteration_extension(a, b) => Some(Ordering::Less),
                (false, true) if measured_iteration_extension(b, a) => Some(Ordering::Greater),
                _ => None,
            })
            .ok_or(Beyond {
                operand: usize::from(left.is_ok()),
            });
    }
    let left = left.map_err(|_| Beyond { operand: 0 })?;
    let right = right.map_err(|_| Beyond { operand: 1 })?;
    Ok(primary_order(&left, &right)
        .then_with(|| diacritic_order(a, &left, b, &right))
        .then_with(|| left.rest.cmp(&right.rest)))
}

catalogue/comparison/collation::measured.text:
/// Fn3 records a strict order against the exact bare prefix for these three marks immediately
/// after these three specials. This does not assign a primary weight, or compare different
/// prefixes with equal primaries. The two-unit suffix follows by transitivity: a completed
/// prefix precedes that prefix plus its known special, which precedes the measured mark.
/// A combining unit, another mark/special, or a tail beyond this suffix remains unmodelled.
fn measured_iteration_extension(shorter: &[u16], longer: &[u16]) -> bool {
    let Some(suffix) = longer.strip_prefix(shorter) else {
        return false;
    };
    let special = |unit: u16| matches!(unit, 0x002D | 0x0027 | 0x2010);
    let mark = |unit: u16| matches!(unit, 0x309D | 0x3005 | 0x30FC);
    match suffix {
        &[iteration] => mark(iteration) && shorter.last().is_some_and(|&unit| special(unit)),
        &[punctuation, iteration] => special(punctuation) && mark(iteration),
        _ => false,
    }
}

catalogue/comparison/sort_key::table.text:
fn table() -> &'static Table {
    static TABLE: OnceLock<Table> = OnceLock::new();
    TABLE.get_or_init(build)
}

catalogue/comparison/sort_key::decode64.text:
/// The bytes of a base64 text (the generated tables' encoding).
fn decode64(text: &str) -> Vec<u8> {
    let mut data = Vec::with_capacity(text.len() / 4 * 3);
    let (mut bits, mut count) = (0u32, 0);
    for byte in text.bytes() {
        let value = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            _ => continue,
        };
        bits = (bits << 6) | u32::from(value);
        count += 6;
        if count >= 8 {
            count -= 8;
            data.push((bits >> count) as u8);
        }
    }
    data
}

catalogue/comparison/sort_key::Reader::b.text:
fn byte(&mut self) -> u8 {
    let byte = self.data[self.at];
    self.at += 1;
    byte
}

catalogue/comparison/sort_key::Reader::v.text:
fn varint(&mut self) -> u64 {
    let (mut value, mut shift) = (0u64, 0);
    loop {
        let byte = self.byte();
        value |= u64::from(byte & 0x7F) << shift;
        if byte & 0x80 == 0 {
            return value;
        }
        shift += 7;
    }
}

catalogue/comparison/sort_key::in_ranges.text:
fn in_ranges(code: u16, ranges: &[(u16, u16)]) -> bool {
    ranges.iter().any(|&(a, b)| (a..=b).contains(&code))
}

catalogue/comparison/sort_key::build.text:
fn build() -> Table {
    // The Unicode data.
    let mut roots: HashMap<u16, Root> = HashMap::new();
    let mut reader = Reader {
        data: decode64(UNITS),
        at: 0,
    };
    let mut code = 0u16;
    while !reader.done() {
        code += reader.varint() as u16;
        let flags = reader.byte();
        let count = reader.varint() as usize;
        let primaries: Vec<u64> = (0..count).map(|_| reader.varint()).collect();
        let secondaries: Vec<Vec<u32>> = (0..=count)
            .map(|_| {
                let n = reader.varint() as usize;
                (0..n).map(|_| reader.varint() as u32).collect()
            })
            .collect();
        roots.insert(
            code,
            Root {
                flags,
                primaries,
                secondaries,
            },
        );
    }
    // The measured exceptions.
    let mut exceptions: HashMap<u16, Exception> = HashMap::new();
    let mut reader = Reader {
        data: decode64(EXCEPTIONS),
        at: 0,
    };
    let mut code = 0u16;
    while !reader.done() {
        code += reader.varint() as u16;
        let exception = match reader.byte() {
            0 => Exception::Ignorable,
            1 => Exception::Refused,
            2 => Exception::Mark(reader.byte()),
            3 => Exception::Special([reader.byte(), reader.byte()]),
            5 => {
                let whole = reader.byte() == 1;
                let n = reader.varint() as usize;
                Exception::Expansion((0..n).map(|_| reader.varint() as u16).collect(), whole)
            }
            6 => Exception::Iteration(Iteration {
                vowel: reader.byte() == 1,
                diacritic: reader.byte(),
                iteration: reader.byte(),
                width: match reader.byte() {
                    0 => None,
                    _ => Some(reader.byte()),
                },
            }),
            _ => {
                let n = reader.varint() as usize;
                let primaries = (0..n).map(|_| reader.varint()).collect();
                let n = reader.varint() as usize;
                let diacritic = (0..n).map(|_| reader.byte()).collect();
                let n = reader.varint() as usize;
                let case = (0..n).map(|_| reader.byte()).collect();
                let kana = match reader.byte() {
                    0 => None,
                    _ => Some([reader.byte(), reader.byte(), reader.byte()]),
                };
                Exception::Weighted {
                    primaries,
                    diacritic,
                    case,
                    kana,
                }
            }
        };
        exceptions.insert(code, exception);
    }
    let placed: HashMap<u64, (u64, u8)> = PLACED.iter().map(|&(t, a, s)| (t, (a, s))).collect();
    let secondary: HashMap<u32, u8> = SECONDARY.iter().copied().collect();
    let special: HashMap<u16, [u8; 2]> = SPECIAL.iter().copied().collect();
    let compat: HashMap<u16, (u16, u8)> = COMPAT.iter().map(|&(c, p, w)| (c, (p, w))).collect();

    // A primary's ten key bytes and its length in Windows' keys.
    let slot = |token: u64| -> Slot {
        let (group, anchor, sub) = if token >= EXTRA_KIND {
            let (group, anchor, sub) = EXTRA[(token - EXTRA_KIND) as usize];
            (group, anchor, sub)
        } else {
            let at = GROUPS.partition_point(|&(start, _)| start <= token);
            let group = GROUPS[at.max(1) - 1].1;
            let (anchor, sub) = placed.get(&token).copied().unwrap_or((token, 0));
            (group, anchor, sub)
        };
        let mut bytes = [0u8; PRIMARY_BYTES];
        bytes[0] = group;
        bytes[1..9].copy_from_slice(&anchor.to_be_bytes());
        bytes[9] = sub;
        let length = match group {
            0xFD => 4,
            0xA9 => 3,
            _ => 2,
        };
        (bytes, length)
    };

    let mut table = Table {
        weights: Vec::with_capacity(0x10000),
        primary: Vec::new(),
        diacritic: Vec::new(),
        case: Vec::new(),
        expansions: Vec::new(),
        repeat: REPEAT.iter().map(|&(a, b, t)| (a, b, slot(t))).collect(),
        vowel: VOWEL.iter().map(|&(c, t)| (c, slot(t))).collect(),
        no_repeat: slot(NO_REPEAT),
    };
    let weighted = |table: &mut Table,
                    primaries: &[u64],
                    diacritic: &[u8],
                    case: &[u8],
                    kana: Option<[u8; 3]>|
     -> Weight {
        let primary = table.primary.len() as u32;
        let diacritic_at = table.diacritic.len() as u32;
        let case_at = table.case.len() as u32;
        let mut windows_length = 0u8;
        for &token in primaries {
            let (bytes, length) = slot(token);
            table.primary.extend_from_slice(&bytes);
            windows_length += length;
        }
        table.diacritic.extend_from_slice(diacritic);
        table.case.extend_from_slice(case);
        Weight::Weighted {
            primary,
            primaries: primaries.len() as u8,
            windows_length,
            diacritic: diacritic_at,
            diacritics: diacritic.len() as u8,
            case: case_at,
            cases: case.len() as u8,
            kana,
        }
    };
    for point in 0u32..=0xFFFF {
        let code = point as u16;
        let covered = code != 0 && (in_ranges(code, &COVERED) || special.contains_key(&code));
        let weight = if jamo_class(code).is_some() {
            Weight::Jamo
        } else if let Some(&(primary, case)) = compat.get(&code) {
            // A compatibility jamo is one primary among the Hangul syllables' and the conjoining
            // jamo's (measured, hangul_collation.rs), with its own case weight.
            weighted(
                &mut table,
                &[HANGUL | u64::from(primary)],
                &[2],
                &[case],
                None,
            )
        } else if !covered {
            Weight::Refused
        } else if let Some(exception) = exceptions.get(&code) {
            match exception {
                Exception::Ignorable => Weight::Ignorable,
                Exception::Refused => Weight::Refused,
                Exception::Mark(w) => Weight::Mark(*w),
                Exception::Special(w) => Weight::Special(*w),
                // An isolated form of marks compared as the marks (its decomposition without the
                // leading space): the walk's runs into it are not modelled.
                Exception::Expansion(_, false) => Weight::Refused,
                Exception::Expansion(units, whole) => {
                    let at = table.expansions.len() as u32;
                    table.expansions.extend_from_slice(units);
                    Weight::Expansion {
                        at,
                        len: units.len() as u8,
                        whole: *whole,
                    }
                }
                Exception::Iteration(rule) => Weight::Iteration(*rule),
                Exception::Weighted {
                    primaries,
                    diacritic,
                    case,
                    kana,
                } => {
                    // A syllable's token is its code unit; its primary is measured.
                    let primaries: Vec<u64> = primaries
                        .iter()
                        .map(|&token| match token.checked_sub(HANGUL) {
                            Some(point @ 0xAC00..=0xD7A3) => {
                                HANGUL | u64::from(syllable_primary(point as u32 - 0xAC00))
                            }
                            _ => token,
                        })
                        .collect();
                    weighted(&mut table, &primaries, diacritic, case, *kana)
                }
            }
        } else if (0xD800..=0xDFFF).contains(&code) {
            match SURROGATES
                .iter()
                .find(|&&(a, b, _)| (a..=b).contains(&code))
            {
                Some((_, _, Some((d, c)))) => {
                    weighted(&mut table, &[SURROGATE | point as u64], &[*d], &[*c], None)
                }
                Some((_, _, None)) => Weight::Ignorable,
                None => Weight::Refused,
            }
        } else if let Some(w) = special.get(&code) {
            Weight::Special(*w)
        } else if (0xAC00..=0xD7A3).contains(&code) {
            let index = point - 0xAC00;
            weighted(
                &mut table,
                &[HANGUL | u64::from(syllable_primary(index))],
                &[2],
                &[2],
                None,
            )
        } else if let Some(base) = han_base(code) {
            if in_ranges(code, &NEW) {
                Weight::Ignorable
            } else {
                weighted(
                    &mut table,
                    &[HAN | (base << 32) | point as u64],
                    &[2],
                    &[2],
                    None,
                )
            }
        } else if let Some(root) = roots.get(&code) {
            derive(root, &secondary).map_or(Weight::Refused, |derived| match derived {
                Derived::Ignorable => Weight::Ignorable,
                Derived::Mark(w) => Weight::Mark(w),
                Derived::Weighted {
                    diacritic,
                    case,
                    kana,
                } => weighted(&mut table, &root.primaries, &diacritic, &case, kana),
            })
        } else {
            Weight::Refused
        };
        table.weights.push(weight);
    }
    table
}

catalogue/comparison/sort_key::han_base.text:
/// The UCA's implicit weight base of a Han character (0 for the URO and the unified
/// compatibility ideographs, 1 for Extension A), each ordered by code point.
fn han_base(code: u16) -> Option<u64> {
    match code {
        0x4E00..=0x9FFF
        | 0xFA0E
        | 0xFA0F
        | 0xFA11
        | 0xFA13
        | 0xFA14
        | 0xFA1F
        | 0xFA21
        | 0xFA23
        | 0xFA24
        | 0xFA27..=0xFA29 => Some(0),
        0x3400..=0x4DBF => Some(1),
        _ => None,
    }
}

catalogue/comparison/sort_key::derive.text:
fn derive(root: &Root, secondary: &HashMap<u32, u8>) -> Option<Derived> {
    if root.flags & NEW_FLAG != 0 {
        return Some(Derived::Ignorable);
    }
    if root.primaries.is_empty() {
        return Some(match root.secondaries.as_slice() {
            [list] if list.len() == 1 => match secondary.get(&list[0]) {
                Some(&w) => Derived::Mark(w),
                None => Derived::Ignorable,
            },
            _ => Derived::Ignorable,
        });
    }
    if !root.secondaries[0].is_empty() {
        return None;
    }
    let mut diacritic = Vec::with_capacity(root.primaries.len());
    for list in &root.secondaries[1..] {
        let mut sum = 2u32;
        for s in list {
            sum += u32::from(*secondary.get(s)?);
        }
        diacritic.push((sum % 256) as u8);
    }
    let case = vec![if root.flags & WIDE != 0 { 3 } else { 2 }; root.primaries.len()];
    let kana = (root.flags & KANA != 0).then(|| {
        [
            if root.flags & SMALL != 0 { 0xC4 } else { 0xC6 },
            if root.flags & KATAKANA != 0 {
                0xC4
            } else {
                0xE4
            },
            if root.flags & NARROW != 0 { 0xC4 } else { 0xC5 },
        ]
    });
    Some(Derived::Weighted {
        diacritic,
        case,
        kana,
    })
}

catalogue/comparison/sort_key::jamo_clas.text:
fn jamo_class(code: u16) -> Option<JamoClass> {
    Some(match code {
        0x1100..=0x1112 => JamoClass::LeadModern,
        0x1113..=0x115E | 0xA960..=0xA97C => JamoClass::LeadArchaic,
        0x115F => JamoClass::LeadFiller,
        0x1160 => JamoClass::VowelFiller,
        0x1161..=0x1175 => JamoClass::VowelModern,
        0x1176..=0x11A7 | 0xD7B0..=0xD7C6 => JamoClass::VowelArchaic,
        0x11A8..=0x11C2 => JamoClass::TrailModern,
        0x11C3..=0x11FF | 0xD7CB..=0xD7FB => JamoClass::TrailArchaic,
        _ => return None,
    })
}

catalogue/comparison/sort_key::jamo_entr.text:
/// The measured weights of a conjoining jamo: primary and the leading, vowel and trailing
/// extension bytes of its key.
fn jamo_entry(code: u16) -> (u16, u8, u8, u8) {
    let at = JAMO
        .binary_search_by_key(&code, |e| e.0)
        .expect("a measured jamo");
    let (_, p, l, v, t) = JAMO[at];
    (p, l, v, t)
}

catalogue/comparison/sort_key::syllable_.text:
/// The primary Windows gives the syllable at `index` from U+AC00: the runs of consecutive
/// primaries are measured, the gaps between them hold compatibility and archaic jamo.
fn syllable_primary(index: u32) -> u16 {
    let at = SYLLABLE_RUNS.partition_point(|&(first, _)| u32::from(first) <= index);
    let (first, p) = SYLLABLE_RUNS[at - 1];
    p + (index - u32::from(first)) as u16
}

catalogue/comparison/sort_key::trailing_.text:
/// How many modern trailing consonants weigh at most `t` (the position a trailing consonant
/// takes among the syllables' final consonants).
fn trailing_rank(t: u8) -> u32 {
    JAMO.iter()
        .filter(|e| (0x11A8..=0x11C2).contains(&e.0) && e.4 <= t)
        .count() as u32
}

catalogue/comparison/sort_key::vowel_ran.text:
/// The index among the modern vowels of the last one weighing at most `v`.
fn vowel_rank(v: u8) -> u32 {
    JAMO.iter()
        .filter(|e| (0x1161..=0x1175).contains(&e.0) && e.3 <= v)
        .count() as u32
        - 1
}

catalogue/comparison/sort_key::jamo_clus.text:
/// The first weight Windows' key holds for the conjoining jamo at the start of `units`, and
/// how many units it takes. Windows' keys write each jamo as a primary and three extension
/// bytes (leading, vowel, trailing weights), and run some neighbours together (measured over
/// every leading consonant and vowel and the trailing consonants):
/// - a vowel filler after a leading consonant adds nothing, once;
/// - a vowel after the leading filler replaces it;
/// - an archaic vowel after a modern leading consonant, or any vowel after an archaic one, makes
///   one weight, placed where the syllable the pair would spell sorts;
/// - a trailing consonant after a leading consonant, a vowel or such a pair sets its trailing
///   byte, and after a modern leading consonant (alone, or with a vowel filler) moves its primary
///   to the syllable with that trailing consonant; after a modern consonant and a modern vowel it
///   joins all three when it is archaic (U+D7DD excepted).
///
/// Anything between two jamo, an ignorable unit or a mark too, ends the run.
fn jamo_cluster(units: &[u16]) -> (Triple, usize) {
    use JamoClass::*;
    let first = units[0];
    let mut class = jamo_class(first).expect("a conjoining jamo");
    let (p, l, v, t) = jamo_entry(first);
    let mut triple = Triple { p, l, v, t };
    let lead_index = u32::from(first.wrapping_sub(0x1100));
    let mut used = 1;
    let mut filled = false;
    let mut trailing_open = !matches!(class, TrailModern | TrailArchaic);
    while let Some(&next) = units.get(used) {
        let Some(next_class) = jamo_class(next) else {
            break;
        };
        let (_, _, nv, nt) = jamo_entry(next);
        let leading = matches!(class, LeadModern | LeadArchaic | LeadFiller);
        match next_class {
            VowelFiller if leading && !filled => filled = true,
            VowelFiller | VowelModern | VowelArchaic if filled => break,
            VowelModern | VowelArchaic if class == LeadFiller => {
                let (np, nl, nv, nt) = jamo_entry(next);
                triple = Triple {
                    p: np,
                    l: nl,
                    v: nv,
                    t: nt,
                };
                class = next_class;
            }
            VowelArchaic if class == LeadModern => {
                let syllable = lead_index * 588 + vowel_rank(nv) * 28 + 27;
                triple = Triple {
                    p: syllable_primary(syllable),
                    l: triple.l - 0x80,
                    v: nv,
                    t: 2,
                };
                class = TrailModern;
                trailing_open = true;
            }
            VowelModern | VowelArchaic if class == LeadArchaic => {
                triple = Triple {
                    p: triple.p + 1,
                    l: triple.l - 0x80,
                    v: nv,
                    t: 2,
                };
                class = TrailModern;
                trailing_open = true;
            }
            VowelModern
                if class == LeadModern
                    && matches!(units.get(used + 1), Some(&t3) if jamo_class(t3) == Some(TrailArchaic) && t3 != 0xD7DD) =>
            {
                let (_, _, _, t3) = jamo_entry(units[used + 1]);
                let syllable = lead_index * 588 + vowel_rank(nv) * 28 + trailing_rank(t3);
                triple = Triple {
                    p: syllable_primary(syllable),
                    l: triple.l - 0x80,
                    v: nv,
                    t: t3,
                };
                used += 2;
                break;
            }
            TrailModern | TrailArchaic if trailing_open && triple.t == 2 => {
                if class == LeadModern {
                    triple.p = syllable_primary(lead_index * 588 + trailing_rank(nt) - 1);
                }
                triple.t = nt;
                used += 1;
                break;
            }
            _ => break,
        }
        used += 1;
    }
    (triple, used)
}

catalogue/comparison/sort_key::hangul_sl.text:
/// A Hangul primary's key bytes: the syllables' group and the primary.
fn hangul_slot(p: u16) -> [u8; PRIMARY_BYTES] {
    let mut bytes = [0u8; PRIMARY_BYTES];
    bytes[0] = 0xC0;
    bytes[1..9].copy_from_slice(&(HANGUL | u64::from(p)).to_be_bytes());
    bytes
}

catalogue/comparison/sort_key::leading_o.text:
/// An order decided entirely before either unknown primary, or by a completed primary prefix.
/// No diacritic, case or special level can reverse a strict primary order.
pub(super) fn leading_order(
    left: &Result<Parts, Unfinished>,
    right: &Result<Parts, Unfinished>,
) -> Option<Ordering> {
    fn prefix(parts: &Result<Parts, Unfinished>) -> Option<(&[u8], bool, bool)> {
        match parts {
            Ok(parts) => Some((parts.primary.as_slice(), true, false)),
            Err(rest) => match rest.continuation {
                Continuation::More => Some((rest.primary.as_slice(), false, true)),
                Continuation::Unknown => None,
            },
        }
    }
    let (a, a_complete, a_continues) = prefix(left)?;
    let (b, b_complete, b_continues) = prefix(right)?;
    let common = a.len().min(b.len());
    let earlier = a[..common].cmp(&b[..common]);
    if !earlier.is_eq() {
        return Some(earlier);
    }
    if a_complete && (a.len() < b.len() || (a.len() == b.len() && b_continues)) {
        Some(Ordering::Less)
    } else if b_complete && (b.len() < a.len() || (a.len() == b.len() && a_continues)) {
        Some(Ordering::Greater)
    } else {
        None
    }
}

