ported/excel_numeric::binary_with.text:
/// One x87 operation on two binary64 operands at PC=64, then the binary64 store.
fn binary_with<F: Fpu>(op: fn(&Ext80, &Ext80, u16) -> Ext80, a: f64, b: f64) -> f64 {
    F::store(&op(&load(a), &load(b), CW), CW)
}

ported/excel_numeric::excel_x87_mul.text:
/// `RN53(RN64(a * b))` — the x87 double-rounded product as a `pub(crate)`
/// spill-loop helper (the same op `POWER` uses internally via [`x87::mul`]).
pub(crate) fn excel_x87_mul(a: f64, b: f64) -> f64 {
    #[cfg(all(target_arch = "x86_64", not(feature = "soft-x87")))]
    {
        x87::mul(a, b)
    }
    #[cfg(not(all(target_arch = "x86_64", not(feature = "soft-x87"))))]
    {
        binary_with::<Soft>(Soft::mul, a, b)
    }
}

ported/excel_numeric/x87::mul.text:
/// `RN53(RN64(a * b))` — one x87 `FMUL` at PC=64 then a `binary64` store: the
/// **double-rounded** product. Excel forms `POWER`'s `|y|·ln x` this way; a plain
/// SSE multiply is single-rounded and differs on double-rounding-window inputs.
pub(super) fn mul(a: f64, b: f64) -> f64 {
    let mut result: f64 = 0.0;
    let cw_core: u16 = CW_CORE;
    let mut cw_save: u16 = 0;
    // SAFETY: balanced x87 stack (2 push; `fmulp` and `fstp` pop both), pointer
    // I/O only, control word saved and restored.
    unsafe {
        asm!(
            "fnstcw word ptr [{save}]",
            "fldcw word ptr [{core}]",
            "fld qword ptr [{a}]",     // st0 = a
            "fld qword ptr [{b}]",     // st0 = b, st1 = a
            "fmulp st(1), st",         // st0 = RN64(a*b)
            "fstp qword ptr [{res}]",  // RN53 store
            "fldcw word ptr [{save}]",
            a = in(reg) &a,
            b = in(reg) &b,
            res = in(reg) &mut result,
            core = in(reg) &cw_core,
            save = in(reg) &mut cw_save,
        );
    }
    result
}

