coerce::logical.text:
/// The value as a logical: a number is TRUE unless it is 0, a logical as it is, Empty and
/// Missing as FALSE, the text TRUE or FALSE in any ASCII case as that logical, an error as
/// itself. Other text is #VALUE!, digit text included: Excel reads no number from text in a
/// logical position (NOT("1") and IF("1",1,2) are #VALUE! in the captures of dc_fwpz and
/// cfunc_m1_2, and IF over the date label 2020/01/02 in dc_e00t's; OxFunc's
/// `parse_excel_logical_text` records the same rule).
pub(crate) fn logical(value: &CalcValue) -> Result<bool, Stop> {
    match value.core_ref() {
        CoreRef::Number(n) => operand(n).map(|n| n != 0.0),
        CoreRef::Logical(b) => Ok(b),
        CoreRef::Text(text) => match spelled_logical(text) {
            Some(logical) => Ok(logical),
            None => Err(Stop::Error(WorksheetErrorCode::Value)),
        },
        CoreRef::Empty | CoreRef::Missing => Ok(false),
        CoreRef::Error(code) => Err(Stop::Error(code)),
        CoreRef::Array(_) | CoreRef::Reference(_) => Err(Stop::NotModelled),
    }
}

catalogue/aggregate::reader.text:
/// The services' cell reader, which a kernel needs to read the reference at argument `index`.
pub(super) fn reader<'a, 's>(
    site: &Site<'_>,
    services: &'a mut EvalServices<'s>,
    index: usize,
) -> Step<&'a mut (dyn CellReader + 's)> {
    services
        .cells()
        .ok_or(Exit::Fault(FunctionFault::ReferenceUnreadable {
            id: site.id(),
            index,
        }))
}

catalogue/aggregate::read_reference.text:
/// Reads the held cells of every area of `reference`, the argument at `index`, in its order:
/// `visit` receives each cell's area, key and value. A reader that refuses an area, or visits a
/// cell outside it, cannot supply the area, and the call ends in ReferenceUnreadable.
pub(super) fn read_reference(
    site: &Site<'_>,
    cells: &mut dyn CellReader,
    reference: &ReferenceLike,
    index: usize,
    visit: &mut dyn FnMut(GridArea, CellKey, &CalcValue) -> Step<()>,
) -> Step<()> {
    let unreadable = || {
        Exit::Fault(FunctionFault::ReferenceUnreadable {
            id: site.id(),
            index,
        })
    };
    for &area in reference.areas() {
        let mut stopped = Ok(());
        let read = cells.read_area(area, &mut |key, value| {
            let step = if area.contains(key) {
                visit(area, key, value)
            } else {
                Err(unreadable())
            };
            match step {
                Ok(()) => ControlFlow::Continue(()),
                Err(exit) => {
                    stopped = Err(exit);
                    ControlFlow::Break(())
                }
            }
        });
        read.map_err(|Unreadable| unreadable())?;
        stopped?;
    }
    Ok(())
}

catalogue/subtotal::held_values.text:
/// The values of the reference arguments `from..`, with the cells `rule` leaves out removed.
fn held_values(
    site: &Site<'_>,
    a: &[CalcValue],
    from: usize,
    sv: &mut EvalServices<'_>,
    rule: Rule,
) -> Step<Vec<CalcValue>> {
    let mut found = Vec::new();
    for (index, argument) in a.iter().enumerate().skip(from) {
        match argument.core_ref() {
            CoreRef::Reference(reference) => {
                let needs_knowledge = rule.nested || rule.hidden || rule.filtered;
                let mut excluded_cells = BTreeSet::new();
                let mut excluded_rows = BTreeSet::new();
                if needs_knowledge {
                    let reader = aggregate::reader(site, sv, index)?;
                    for &area in reference.areas() {
                        let Some(SubtotalExclusions {
                            nested_subtotals,
                            hidden_rows,
                            filtered_rows,
                        }) = reader.subtotal_exclusions(area)
                        else {
                            return Err(site.not_modelled(Some(index)));
                        };
                        if rule.nested {
                            excluded_cells.extend(nested_subtotals.iter().map(|k| (k.row(), k.column())));
                        }
                        if rule.hidden {
                            excluded_rows.extend(hidden_rows);
                        }
                        if rule.filtered {
                            excluded_rows.extend(filtered_rows);
                        }
                    }
                }
                let reader = aggregate::reader(site, sv, index)?;
                read_reference(site, reader, reference, index, &mut |_, key, value| {
                    if excluded_rows.contains(&key.row())
                        || excluded_cells.contains(&(key.row(), key.column()))
                    {
                        return Ok(());
                    }
                    if rule.errors && matches!(value.core_ref(), CoreRef::Error(_)) {
                        return Ok(());
                    }
                    found.push(value.clone());
                    Ok(())
                })?;
            }
            CoreRef::Array(_) => {
                return Err(Exit::Error(WorksheetErrorCode::Value));
            }
            _ => {
                if rule.errors && matches!(argument.core_ref(), CoreRef::Error(_)) {
                    // Ignored error under rule.errors
                } else {
                    found.push(argument.clone());
                }
            }
        }
    }
    Ok(found)
}

catalogue/subtotal::numbers_of.text:
/// The numbers among held values; the first error is the result.
fn numbers_of(values: &[CalcValue]) -> Step<Vec<f64>> {
    let mut found = Vec::new();
    for value in values {
        match value.core_ref() {
            CoreRef::Number(n) => found.push(n),
            CoreRef::Error(code) => return fail(code),
            _ => {}
        }
    }
    Ok(found)
}

catalogue/subtotal::compute.text:
/// Function `number` (1 to 13, SUBTOTAL's numbering for 1 to 11) over the held values.
fn compute(site: &Site<'_>, number: i64, values: &[CalcValue]) -> Step<CalcValue> {
    if number == 3 {
        let counted = values
            .iter()
            .filter(|v| !matches!(v.core_ref(), CoreRef::Empty | CoreRef::Missing))
            .count();
        return site.number(counted as f64);
    }
    if number == 2 {
        let counted = values
            .iter()
            .filter(|v| matches!(v.core_ref(), CoreRef::Number(_)))
            .count();
        return site.number(counted as f64);
    }
    let numbers = numbers_of(values)?;
    let result = match number {
        1 => {
            let mut total = 0.0;
            for n in &numbers {
                total = site.add(total, *n)?;
            }
            site.divide(total, numbers.len() as f64)?
        }
        4 => numbers
            .iter()
            .copied()
            .fold(None, |m: Option<f64>, n| Some(m.map_or(n, |m| m.max(n))))
            .unwrap_or(0.0),
        5 => numbers
            .iter()
            .copied()
            .fold(None, |m: Option<f64>, n| Some(m.map_or(n, |m| m.min(n))))
            .unwrap_or(0.0),
        6 => {
            if numbers.is_empty() {
                0.0
            } else {
                let mut product = 1.0;
                for n in &numbers {
                    product = site.multiply(product, *n)?;
                }
                product
            }
        }
        7 => stdev_from_values(&numbers, VarianceDivisor::Sample).map_err(Exit::Error)?,
        8 => stdev_from_values(&numbers, VarianceDivisor::Population).map_err(Exit::Error)?,
        9 => {
            let mut total = 0.0;
            for n in &numbers {
                total = site.add(total, *n)?;
            }
            total
        }
        10 => variance_from_values(&numbers, VarianceDivisor::Sample).map_err(Exit::Error)?,
        11 => variance_from_values(&numbers, VarianceDivisor::Population).map_err(Exit::Error)?,
        12 => {
            let mut sorted = numbers.clone();
            sorted.sort_by(f64::total_cmp);
            if sorted.is_empty() {
                return fail(WorksheetErrorCode::Num);
            }
            let mid = sorted.len() / 2;
            if sorted.len() % 2 == 1 {
                sorted[mid]
            } else {
                sorted[mid - 1] + (sorted[mid] - sorted[mid - 1]) / 2.0
            }
        }
        13 => {
            // MODE.SNGL: the first most frequent number, in reading order.
            let mut best: Option<(usize, f64)> = None;
            for (i, n) in numbers.iter().enumerate() {
                let count = numbers.iter().filter(|m| *m == n).count();
                if count >= 2
                    && best.is_none_or(|(c, _)| count > c)
                    && numbers[..i].iter().all(|m| m != n)
                {
                    best = Some((count, *n));
                }
            }
            match best {
                Some((_, n)) => n,
                None => return fail(WorksheetErrorCode::NA),
            }
        }
        _ => return fail(WorksheetErrorCode::Value),
    };
    site.number(result)
}

catalogue/subtotal::entry::AGGREGATE.text:
2 aggregate_fn |s, a, sv| {
    // Excel 20527 uses the same tolerant integer boundary for both selectors.
    let function = crate::ported::text_kernels::date_integer_floor(num(s, a, 0)?) as i64;
    let options = if a[1].is_missing() { 0 } else {
        crate::ported::text_kernels::date_integer_floor(num(s, a, 1)?) as i64
    };
    if !(0..=7).contains(&options) || !(1..=19).contains(&function) {
        return fail(WorksheetErrorCode::Value);
    }
    let rule = Rule {
        nested: options <= 3,
        hidden: matches!(options, 1 | 3 | 5 | 7),
        filtered: matches!(options, 1 | 3 | 5 | 7),
        errors: matches!(options, 2 | 3 | 6 | 7),
    };
    if function <= 13 {
        // The reference form reads references only: a value there (a number, an array) is
        // #VALUE! (Excel 16.0.20430, 2026-10-25, dc-6au: `=AGGREGATE(1,1,{1,2})`,
        // `=AGGREGATE(9,0,1)` and `=AGGREGATE(1,1,A1:A3*1)` are #VALUE!). An error value
        // there is not measured and stays refused. Option 4 ignores nothing and accepts
        // scalar inputs in the legacy test corpus (dc-jnt).
        if options != 4
            && a[2..].iter().any(|argument| {
                !matches!(argument.core_ref(), CoreRef::Reference(_) | CoreRef::Error(_))
                    && !argument.is_missing()
            })
        {
            return fail(WorksheetErrorCode::Value);
        }
        let values = held_values(s, a, 2, sv, rule)?;
        return compute(s, function, &values);
    }
    // The array form: AGGREGATE(function_num, options, array, k).
    if a.len() != 4 {
        return fail(WorksheetErrorCode::Value);
    }
    let k = num(s, a, 3)?;
    let values = match a[2].core_ref() {
        CoreRef::Reference(_) => held_values(s, &a[..3], 2, sv, rule)?,
        CoreRef::Array(array) => array
            .iter_row_major()
            .filter(|v| !(rule.errors && matches!(v.core_ref(), CoreRef::Error(_))))
            .cloned()
            .collect(),
        _ => vec![a[2].clone()],
    };
    let mut numbers = numbers_of(&values)?;
    let result = match function {
        14 | 15 => {
            let k = k.trunc();
            if k < 1.0 || k > numbers.len() as f64 {
                return fail(WorksheetErrorCode::Num);
            }
            numbers.sort_by(f64::total_cmp);
            if function == 14 {
                numbers.reverse();
            }
            Ok(numbers[k as usize - 1])
        }
        16 => percentile_inc_kernel(&mut numbers, k),
        17 => {
            let q = k.trunc();
            if !(0.0..=4.0).contains(&q) { Err(WorksheetErrorCode::Num) }
            else { percentile_inc_kernel(&mut numbers, q / 4.0) }
        }
        18 => percentile_exc_kernel(&mut numbers, k),
        _ => {
            let q = k.trunc();
            if !(1.0..=3.0).contains(&q) { Err(WorksheetErrorCode::Num) }
            else { percentile_exc_kernel(&mut numbers, q / 4.0) }
        }
    };
    super::kit::out(s, result)
}

ported/percentile_common::percentile_inc.text:
pub fn percentile_inc_kernel(values: &mut [f64], k: f64) -> Result<f64, WorksheetErrorCode> {
    if values.is_empty() {
        return Err(WorksheetErrorCode::Num);
    }
    if !(0.0..=1.0).contains(&k) {
        return Err(WorksheetErrorCode::Num);
    }
    values.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    if values.len() == 1 {
        return Ok(values[0]);
    }
    let rank = 1.0 + k * (values.len() as f64 - 1.0);
    interpolate_sorted(values, rank)
}

ported/percentile_common::percentile_exc.text:
pub fn percentile_exc_kernel(values: &mut [f64], k: f64) -> Result<f64, WorksheetErrorCode> {
    if values.is_empty() {
        return Err(WorksheetErrorCode::Num);
    }
    values.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let rank = k * (values.len() as f64 + 1.0);
    if rank < 1.0 || rank > values.len() as f64 {
        return Err(WorksheetErrorCode::Num);
    }
    interpolate_sorted(values, rank)
}

ported/percentile_common::interpolate_so.text:
fn interpolate_sorted(values: &[f64], rank: f64) -> Result<f64, WorksheetErrorCode> {
    let lower_index = rank.floor() as usize;
    let upper_index = rank.ceil() as usize;
    if lower_index == 0
        || upper_index == 0
        || lower_index > values.len()
        || upper_index > values.len()
    {
        return Err(WorksheetErrorCode::Num);
    }
    if lower_index == upper_index {
        return Ok(values[lower_index - 1]);
    }
    let lower = values[lower_index - 1];
    let upper = values[upper_index - 1];
    Ok(lower + (rank - lower_index as f64) * (upper - lower))
}

