fn roman_value(ch: char) -> Option<i64> {
    match ch {
        'I' => Some(1),
        'V' => Some(5),
        'X' => Some(10),
        'L' => Some(50),
        'C' => Some(100),
        'D' => Some(500),
        'M' => Some(1000),
        _ => None,
    }
}

ported/arabic_fn::arabic_kernel.text:
pub fn arabic_kernel(text: &ExcelText) -> Result<f64, WorksheetErrorCode> {
    let s = String::from_utf16_lossy(text.utf16_code_units()).to_uppercase();
    if s.is_empty() {
        return Ok(0.0);
    }
    let mut total = 0i64;
    let mut prev = 0i64;
    for ch in s.chars().rev() {
        let value = roman_value(ch).ok_or(WorksheetErrorCode::Value)?;
        if value < prev {
            total -= value;
        } else {
            total += value;
            prev = value;
        }
    }
    Ok(total as f64)
}

