number_text::decimal.text:
/// The shared first15 significant digits. The unresolved near-tie departures
/// documented above apply to formatting as well as concatenation (dc-b1l.25).
pub(crate) fn decimal(x: f64) -> ExactDecimal {
    if x == 0.0 || x.is_subnormal() {
        return ExactDecimal::read(0.0);
    }
    let (digits, exponent) = first_precision(x.abs());
    ExactDecimal {
        negative: x < 0.0,
        coefficient: Natural::from_u64(ascii(&digits).parse().expect("at most15 digits")),
        exponent: exponent - digits.len() as i32 + 1,
    }
}

number_text::first_precision.text:
fn first_precision(x: f64) -> (Vec<u8>, i32) {
    let exact = ExactDecimal::binary(x);
    let all = exact.coefficient.digits();
    let length = i32::try_from(all.len()).expect("a digit count");
    let exponent = length - 1 + exact.exponent;
    let up = !near_tie(&exact.coefficient, &all)
        && all
            .as_bytes()
            .get(SIGNIFICANT_DIGITS)
            .is_some_and(|&d| d >= b'5');
    first_rounding(all.as_bytes(), exponent, up)
}

number_text::near_tie.text:
/// Whether the exact value `coefficient` (whose decimal digits are `digits`) lies within a
/// relative 2^-NEAR_TIE_BITS of a tie at its 16th significant digit, or on it.
fn near_tie(coefficient: &Natural, digits: &str) -> bool {
    let dropped = digits.len().saturating_sub(SIGNIFICANT_DIGITS);
    if dropped == 0 {
        return false;
    }
    // The band is narrower than 2^-60 * 10^15 < 0.001 of the last kept digit, so a number near a
    // tie has dropped digits that begin 49 or 50 (a single dropped 5 is the tie itself).
    let tail = &digits.as_bytes()[SIGNIFICANT_DIGITS..];
    let lead = (tail[0], tail.get(1).copied().unwrap_or(b'0'));
    if lead != (b'4', b'9') && lead != (b'5', b'0') {
        return false;
    }
    // With the dropped part r of the m dropped digits, the distance to the tie is |r - 10^m / 2|
    // in units of the last digit, and the number is near it when
    // |2r - 10^m| * 2^NEAR_TIE_BITS < 2 * coefficient.
    let power = Natural::pow10(u32::try_from(dropped).expect("a digit count"));
    let (_, remainder) = coefficient.div_rem(&power);
    let mut twice = remainder.clone();
    twice.add(&remainder);
    let distance = if twice >= power {
        twice.subtract(&power);
        twice
    } else {
        let mut gap = power.clone();
        gap.subtract(&twice);
        gap
    };
    let scaled = distance.times(&Natural::from_u64(1u64 << (NEAR_TIE_BITS - 1)));
    scaled < *coefficient
}

number_text::first_rounding.text:
/// The first SIGNIFICANT_DIGITS of `digits` (ASCII, the first not zero; the value
/// d1.d2d3... * 10^exponent), one added to the last when `up`, with trailing zeros dropped, and the
/// exponent of the result's leading digit.
fn first_rounding(digits: &[u8], exponent: i32, up: bool) -> (Vec<u8>, i32) {
    let dropped = digits.len() > SIGNIFICANT_DIGITS;
    rounded(digits, exponent, SIGNIFICANT_DIGITS, dropped && up)
}

number_text::rounded.text:
/// `digits` (ASCII, the first not zero; the value d1.d2d3... * 10^exponent) cut to `kept`
/// significant digits, one added to the last when `up`, with trailing zeros dropped, and the
/// exponent of the result's leading digit, one more than `exponent` when adding carries into a new
/// leading digit.
fn rounded(digits: &[u8], exponent: i32, kept: usize, up: bool) -> (Vec<u8>, i32) {
    let mut exponent = exponent;
    let mut result = digits[..digits.len().min(kept)].to_vec();
    if up && !increment(&mut result) {
        // Every kept digit was 9: the result is 1 followed by zeros.
        result = vec![b'1'];
        exponent += 1;
    }
    while result.len() > 1 && result.last() == Some(&b'0') {
        result.pop();
    }
    (result, exponent)
}

number_text::increment.text:
/// Adds one to the last digit of `digits` in place; false when every digit was 9 (and is now 0).
fn increment(digits: &mut [u8]) -> bool {
    for digit in digits.iter_mut().rev() {
        if *digit == b'9' {
            *digit = b'0';
        } else {
            *digit += 1;
            return true;
        }
    }
    false
}

ported/date_kernels::days_from_civil.text:
fn days_from_civil(year: i64, month: i64, day: i64) -> i64 {
    let year = year - i64::from(month <= 2);
    let era = if year >= 0 { year } else { year - 399 } / 400;
    let yoe = year - era * 400;
    let mp = month + if month > 2 { -3 } else { 9 };
    let doy = (153 * mp + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

ported/date_kernels::civil_from_days.text:
fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = mp + if mp < 10 { 3 } else { -9 };
    (y + i64::from(m <= 2), m, d)
}

ported/date_kernels::serial_unbounded_19.text:
/// The 1900 serial of a date, with Excel's 29 February 1900 and day 0 of January 1900, for any
/// day of the month (a day past the month's end runs into the next month).
pub(crate) fn serial_unbounded_1900(year: i64, month: i64, day: i64) -> i64 {
    let base = days_from_civil(1899, 12, 31);
    let month_start = days_from_civil(year, month, 1) - base;
    let month_start = if month_start >= 60 {
        month_start + 1
    } else {
        month_start
    };
    month_start + day - 1
}

ported/date_kernels::ymd_1900.text:
/// The year, month and day of a whole 1900 serial (0 is 0 January 1900, 60 is 29 February 1900).
pub(crate) fn ymd_1900(serial: i64) -> (i64, i64, i64) {
    if serial == 0 {
        return (1900, 1, 0);
    }
    if serial == 60 {
        return (1900, 2, 29);
    }
    let adjusted = if serial > 60 { serial - 1 } else { serial };
    civil_from_days(days_from_civil(1899, 12, 31) + adjusted)
}

ported/date_kernels::is_leap.text:
pub(crate) fn is_leap(year: i64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

ported/date_kernels::days_in_month.text:
pub(crate) fn days_in_month(year: i64, month: i64) -> i64 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(year) {
                29
            } else {
                28
            }
        }
        _ => 30,
    }
}

ported/date_kernels::whole_serial.text:
fn whole_serial(n: f64) -> Result<i64, W> {
    if !(0.0..(MAX_SERIAL_1900 + 1) as f64).contains(&n) {
        return Err(W::Num);
    }
    Ok(n.trunc() as i64)
}

ported/date_kernels::whole.text:
fn whole(n: f64) -> Result<i64, W> {
    if !n.is_finite() {
        return Err(W::Num);
    }
    Ok(n.trunc() as i64)
}

ported/date_kernels::remap_weekday.text:
fn remap_weekday(sunday_one_based: i64, return_type: i64) -> Option<f64> {
    match return_type {
        1 => Some(sunday_one_based as f64),
        2 | 11 => Some(((sunday_one_based + 5) % 7 + 1) as f64),
        3 => Some(((sunday_one_based + 5) % 7) as f64),
        12..=17 => {
            let start_day = (return_type - 10).rem_euclid(7) + 1;
            Some(((sunday_one_based - start_day).rem_euclid(7) + 1) as f64)
        }
        _ => None,
    }
}

ported/date_kernels::weekday_of.text:
fn weekday_of(serial: i64, return_type: i64) -> Result<f64, W> {
    remap_weekday(weekday_sunday_one_based(serial), return_type).ok_or(W::Num)
}

ported/date_kernels::weekday.text:
pub(crate) fn weekday(serial: f64, return_type: Option<f64>) -> Result<f64, W> {
    if serial < 0.0 {
        return Err(W::Num);
    }
    let serial = whole_serial(serial + 0.5 / 86_400.0)?;
    let return_type = whole(date_integer_floor(return_type.unwrap_or(1.0)))?;
    weekday_of(serial, return_type)
}

value_text::measured_host_reader.text:
/// The numeric-text host grammar measured by the fn8 scalar questions.
pub(crate) fn measured_host_reader(profile: &FormatProfile) -> bool {
    matches!(profile.id, LocaleId::EnZa | LocaleId::CurrentExcelHost)
        && profile.decimal_separator == "."
        && profile.thousands_separator == " "
        && profile.currency_symbol == "R"
}

value_text::measured_space.text:
/// Spaces with retained negative numeric-text controls. A configured positive
/// separator remains subject to the existing not-modelled treatment below.
pub(crate) fn measured_space(ch: char, profile: &FormatProfile) -> bool {
    matches!(ch, '\u{00a0}' | '\u{2003}' | '\u{202f}' | '\u{3000}')
        || (ch == '\u{2009}' && measured_host_reader(profile))
}

value_text::rejected_comma_number.text:
/// A numeric-only comma followed by a three-digit number of at least 100 is neither a
/// valid number under the recorded dot/NBSP separators nor a month, day, or Excel year.
/// Excel 20527 controls cover several such forms; other punctuation stays undecided.
pub(crate) fn rejected_comma_number(units: &[u16], decimal: &str, group: &str) -> bool {
    if decimal != "." || group != "\u{00a0}" {
        return false;
    }
    let Some(comma) = units.iter().position(|&u| u == u16::from(b',')) else {
        return false;
    };
    comma > 0
        && units.len() == comma + 4
        && (u16::from(b'1')..=u16::from(b'9')).contains(&units[comma + 1])
        && units[..comma].iter().chain(&units[comma + 1..]).all(|&u| (u16::from(b'0')..=u16::from(b'9')).contains(&u))
}

value_text::rejected_comparison_number.text:
/// Comparison syntax followed by a plain ASCII number is not numeric text.
/// Excel 20527 controls cover these operators with the recorded dot/NBSP separators.
pub(crate) fn rejected_comparison_number(units: &[u16], decimal: &str, group: &str) -> bool {
    if decimal != "." || group != "\u{00a0}" {
        return false;
    }
    let mut chars = units
        .iter()
        .copied()
        .skip_while(|&u| u == u16::from(b' '))
        .peekable();
    if !matches!(chars.next(), Some(0x3c | 0x3d | 0x3e)) {
        return false;
    }
    if matches!(chars.peek(), Some(0x3c | 0x3d | 0x3e)) {
        chars.next();
    }
    let mut digit = false;
    for u in chars {
        if (u16::from(b'0')..=u16::from(b'9')).contains(&u) {
            digit = true;
        } else if !matches!(u, 0x20 | 0x2b | 0x2d | 0x2e | 0x45 | 0x65) {
            return false;
        }
    }
    digit
}

value_text::read.text:
/// Reads `text` (UTF-16 code units).
pub(crate) fn read(units: &[u16], context: &ReadContext<'_>) -> Result<Reading, Unread> {
    let mut text = String::with_capacity(units.len());
    let ascii_profile = [
        context.profile.decimal_separator,
        context.profile.thousands_separator,
        context.profile.currency_symbol,
    ]
    .iter()
    .all(|s| s.is_ascii());
    let measured_digits = ascii_profile
        && matches!(
            context.profile.id,
            LocaleId::EnZa | LocaleId::CurrentExcelHost
        );
    let mut translated_digits = false;
    let mut beyond = false;
    let mut has_measured_space = false;
    for decoded in char::decode_utf16(units.iter().copied()) {
        match decoded {
            Ok(c) if c.is_ascii() => text.push(c),
            Ok('€') if measured_host_reader(context.profile) => text.push('€'),
            Ok(c) if measured_space(c, context.profile) => {
                text.push(c);
                has_measured_space = true;
            }
            // Fn4 qt031..qt096 accepts these four digit scripts in the measured profiles.
            // Fn7 live SQRT/DATEVALUE controls also confirm mixed-script numbers, exponent
            // digits and three-component dates; unmeasured fraction/time forms stay refused.
            Ok(
                c @ ('\u{0660}'..='\u{0669}'
                | '\u{06f0}'..='\u{06f9}'
                | '\u{0966}'..='\u{096f}'
                | '\u{0e50}'..='\u{0e59}'),
            ) if measured_digits => {
                translated_digits = true;
                let zero = match c {
                    '\u{0660}'..='\u{0669}' => 0x0660,
                    '\u{06f0}'..='\u{06f9}' => 0x06f0,
                    '\u{0966}'..='\u{096f}' => 0x0966,
                    _ => 0x0e50,
                };
                text.push(char::from_u32(u32::from('0') + u32::from(c) - zero).unwrap());
            }
            Ok('\u{ff10}'..='\u{ff19}') if measured_digits => return Err(Unread::Rejected),
            // A digit of another script, a space other than ASCII's, or a profile whose
            // separators or currency lie beyond ASCII: what Excel reads is not modelled.
            Ok(c) if c.is_numeric() || c.is_whitespace() || !ascii_profile => {
                return Err(Unread::NotModelled);
            }
            // Any other character beyond ASCII is in no number, date or time form.
            Ok(_) => beyond = true,
            Err(_) => return Err(Unread::NotModelled),
        }
    }
    if beyond {
        return Err(Unread::Rejected);
    }
    let text = text.trim_matches(' ');
    if text.is_empty() {
        return Err(Unread::Rejected);
    }
    if let Some(n) = number(text, context.profile)? {
        if has_measured_space {
            return Err(Unread::NotModelled);
        }
        return Ok(Reading::Number(n));
    }
    // Only ASCII spaces belong to the measured fraction/date/time grammar. The numeric
    // parser above can consume a configured separator; none of these spaces is trimming.
    if has_measured_space {
        return Err(Unread::Rejected);
    }
    if let Some(n) = fraction(text) {
        if translated_digits {
            return Err(Unread::NotModelled);
        }
        return n.map(Reading::Number);
    }
    date_time(text, context, !translated_digits).map(Reading::DateTime)
}

value_text::number.text:
/// Number text, `None` when the text is not in the number form (it may be a date or a fraction).
fn number(text: &str, profile: &FormatProfile) -> Result<Option<f64>, Unread> {
    let bytes = text.as_bytes();
    let currency = profile.currency_symbol.as_bytes();
    let euro = "€".as_bytes();
    let currency_length = |at: usize| {
        if !currency.is_empty() && bytes[at..].starts_with(currency) {
            currency.len()
        } else if measured_host_reader(profile) && bytes[at..].starts_with(euro) {
            euro.len()
        } else {
            0
        }
    };
    let group = profile.thousands_separator.as_bytes();
    let point = profile.decimal_separator.as_bytes();
    let mut at = 0;
    let (mut signed, mut negative, mut paren, mut has_currency, mut percent) =
        (false, false, false, false, false);
    let skip = |at: &mut usize| {
        while bytes.get(*at) == Some(&b' ') {
            *at += 1;
        }
    };
    loop {
        skip(&mut at);
        match bytes.get(at) {
            Some(b'+' | b'-') if !signed && !paren => {
                signed = true;
                negative = bytes[at] == b'-';
                at += 1;
            }
            Some(b'(') if !signed && !paren => {
                paren = true;
                at += 1;
            }
            Some(b'%') if !percent => {
                percent = true;
                at += 1;
            }
            _ if !has_currency && currency_length(at) > 0 => {
                has_currency = true;
                at += currency_length(at);
            }
            _ => break,
        }
    }
    // The mantissa: digits with group separators, then a decimal point and digits.
    let mut digits = String::new();
    let mut fraction_digits = 0i64;
    let mut any = false;
    let mut group_run: Option<usize> = None;
    loop {
        match bytes.get(at) {
            Some(d) if d.is_ascii_digit() => {
                digits.push(char::from(*d));
                any = true;
                if let Some(run) = group_run.as_mut() {
                    *run += 1;
                }
                at += 1;
            }
            _ if any
                && !group.is_empty()
                && bytes[at..].starts_with(group)
                && bytes.get(at + group.len()).is_some_and(u8::is_ascii_digit) =>
            {
                if group_run.is_some_and(|run| run < 3) {
                    return Ok(None);
                }
                group_run = Some(0);
                at += group.len();
            }
            _ => break,
        }
    }
    if group_run.is_some_and(|run| run < 3) {
        return Ok(None);
    }
    if bytes[at..].starts_with(point) {
        at += point.len();
        while let Some(d) = bytes.get(at).filter(|d| d.is_ascii_digit()) {
            digits.push(char::from(*d));
            fraction_digits += 1;
            any = true;
            at += 1;
        }
    }
    if !any {
        return Ok(None);
    }
    let mut exponent = 0i64;
    if matches!(bytes.get(at), Some(b'e' | b'E')) {
        let mut cursor = at + 1;
        let exp_negative = match bytes.get(cursor) {
            Some(b'-') => {
                cursor += 1;
                true
            }
            Some(b'+') => {
                cursor += 1;
                false
            }
            _ => false,
        };
        let start = cursor;
        while bytes.get(cursor).is_some_and(u8::is_ascii_digit) {
            exponent = (exponent * 10 + i64::from(bytes[cursor] - b'0')).min(1_000_000);
            cursor += 1;
        }
        if cursor == start {
            return Ok(None);
        }
        if exp_negative {
            exponent = -exponent;
        }
        at = cursor;
    }
    // Euro may also follow the amount, inside or outside parentheses;
    // the configured Rand remains prefix-only (fn8 paired currency controls).
    let take_euro = |at: &mut usize, has_currency: &mut bool| {
        if !*has_currency && measured_host_reader(profile) && bytes[*at..].starts_with(euro) {
            *has_currency = true;
            *at += euro.len();
            skip(at);
        }
    };
    skip(&mut at);
    take_euro(&mut at, &mut has_currency);
    if bytes.get(at) == Some(&b'%') && !percent {
        percent = true;
        at += 1;
        skip(&mut at);
    }
    if paren {
        if bytes.get(at) != Some(&b')') {
            return Ok(None);
        }
        at += 1;
        negative = true;
        skip(&mut at);
    }
    take_euro(&mut at, &mut has_currency);
    // W111 numeric-text-core-heldout: the percent may follow the complete parenthesized
    // amount, with ASCII spaces between. The same flag rejects a second percent.
    if bytes.get(at) == Some(&b'%') && !percent {
        percent = true;
        at += 1;
        skip(&mut at);
    }
    if at != bytes.len() {
        return Ok(None);
    }
    if has_currency && percent && measured_host_reader(profile) {
        return Err(Unread::Rejected);
    }
    let scale = exponent - fraction_digits - if percent { 2 } else { 0 };
    // W111 percent-bounds: a zero coefficient still validates the percent-adjusted
    // exponent. decimal()'s zero fast return otherwise bypasses this admission rule.
    if percent && digits.bytes().all(|digit| digit == b'0') && !(-308..=308).contains(&scale) {
        return Err(Unread::Rejected);
    }
    decimal(&digits, scale)
        .map(|n| Some(if negative && n != 0.0 { -n } else { n }))
        .ok_or(Unread::Rejected)
}

value_text::decimal.text:
/// The binary64 nearest `digits` (ASCII decimal digits) times 10^scale, its significant digits
/// cut to 15; `None` when the value's decimal point lies outside -308..=308, as Excel's number
/// text reading rejects it.
pub(crate) fn decimal(digits: &str, scale: i64) -> Option<f64> {
    let trimmed = digits.trim_start_matches('0');
    if trimmed.is_empty() {
        return Some(0.0);
    }
    let kept = &trimmed[..trimmed.len().min(15)];
    let dropped = (trimmed.len() - kept.len()) as i64;
    let position = scale + trimmed.len() as i64;
    if !(-308..=308).contains(&position) {
        return None;
    }
    let n: f64 = format!("{kept}e{}", scale + dropped).parse().ok()?;
    Some(if n.is_subnormal() { 0.0 } else { n })
}

value_text::fraction.text:
/// A whole number and a fraction: `[sign] int spaces num/den`. `None` when the text is not in
/// this form; #VALUE! for a zero denominator.
fn fraction(text: &str) -> Option<Result<f64, Unread>> {
    let (negative, body) = match text.as_bytes().first() {
        Some(b'-') => (true, text[1..].trim_start_matches(' ')),
        Some(b'+') => (false, text[1..].trim_start_matches(' ')),
        _ => (false, text),
    };
    let (whole, rest) = body.split_once(' ')?;
    let rest = rest.trim_start_matches(' ');
    let (numerator, denominator) = rest.split_once('/')?;
    let all_digits =
        |s: &str| !s.is_empty() && s.bytes().all(|b| b.is_ascii_digit()) && s.len() <= 15;
    if !all_digits(whole) || !all_digits(numerator) || !all_digits(denominator) {
        return None;
    }
    let (w, n, d): (f64, f64, f64) = (
        whole.parse().ok()?,
        numerator.parse().ok()?,
        denominator.parse().ok()?,
    );
    if d == 0.0 {
        return Some(Err(Unread::Rejected));
    }
    let value = w + n / d;
    Some(Ok(if negative { -value } else { value }))
}

value_text::tokens.text:
fn tokens(text: &str) -> Result<Vec<Token>, Unread> {
    let bytes = text.as_bytes();
    let mut out = Vec::new();
    let mut at = 0;
    while at < bytes.len() {
        let b = bytes[at];
        if b.is_ascii_digit() {
            let start = at;
            while at < bytes.len() && bytes[at].is_ascii_digit() {
                at += 1;
            }
            let run = &text[start..at];
            if run.len() > 9 {
                return Err(Unread::Rejected);
            }
            out.push(Token::Number(run.parse().expect("digits"), run.len()));
        } else if b.is_ascii_alphabetic() {
            let start = at;
            while at < bytes.len() && bytes[at].is_ascii_alphabetic() {
                at += 1;
            }
            out.push(Token::Word(text[start..at].to_ascii_lowercase()));
        } else if b == b' ' {
            while at < bytes.len() && bytes[at] == b' ' {
                at += 1;
            }
            out.push(Token::Sep(' '));
        } else if matches!(b, b'/' | b'-' | b':' | b'.' | b',') {
            out.push(Token::Sep(char::from(b)));
            at += 1;
        } else {
            return Err(Unread::Rejected);
        }
    }
    Ok(out)
}

value_text::month_named.text:
fn month_named(word: &str) -> Option<i64> {
    const NAMES: [&str; 12] = [
        "january",
        "february",
        "march",
        "april",
        "may",
        "june",
        "july",
        "august",
        "september",
        "october",
        "november",
        "december",
    ];
    if word == "sept" {
        return Some(9);
    }
    NAMES
        .iter()
        .position(|name| *name == word || (word.len() == 3 && name.starts_with(word)))
        .map(|at| at as i64 + 1)
}

value_text::time_at.text:
/// The time at the start of `tokens[from..]`, its fraction of a day and the tokens it took.
fn time_at(tokens: &[Token], from: usize) -> Option<(f64, usize)> {
    let mut at = from;
    let Token::Number(hour, hour_len) = tokens.get(at)? else {
        return None;
    };
    let (mut hour, hour_len) = (*hour, *hour_len);
    at += 1;
    let mut minute = 0i64;
    let mut second = 0f64;
    let mut colon = false;
    if tokens.get(at) == Some(&Token::Sep(':')) {
        colon = true;
        at += 1;
        if let Some(Token::Number(m, len)) = tokens.get(at) {
            if *len > 2 {
                return None;
            }
            minute = *m;
            at += 1;
            if tokens.get(at) == Some(&Token::Sep(':')) {
                at += 1;
                if let Some(Token::Number(s, len)) = tokens.get(at) {
                    if *len > 2 {
                        return None;
                    }
                    second = *s as f64;
                    at += 1;
                    if tokens.get(at) == Some(&Token::Sep('.'))
                        && let Some(Token::Number(f, len)) = tokens.get(at + 1)
                    {
                        second += *f as f64 / 10f64.powi(*len as i32);
                        at += 2;
                    }
                }
            }
        }
    }
    if hour_len > 4 {
        return None;
    }
    // An AM/PM marker after a space.
    let mut marked = false;
    if tokens.get(at) == Some(&Token::Sep(' '))
        && let Some(Token::Word(word)) = tokens.get(at + 1)
        && matches!(word.as_str(), "a" | "am" | "p" | "pm")
    {
        if hour > 12 {
            return None;
        }
        let pm = word.starts_with('p');
        if hour == 12 {
            hour = 0;
        }
        if pm {
            hour += 12;
        }
        marked = true;
        at += 2;
    }
    if !colon && !marked {
        return None;
    }
    let seconds = (hour * 3600 + minute * 60) as f64 + second;
    Some((seconds / 86_400.0, at - from))
}

value_text::full_year.text:
/// A two-digit year as Excel reads it: below 30 in the 2000s, else in the 1900s.
fn full_year(year: i64, len: usize) -> i64 {
    if len <= 2 {
        if year < 30 { 2000 + year } else { 1900 + year }
    } else {
        year
    }
}

value_text::valid_day.text:
fn valid_day(year: i64, month: i64, day: i64) -> bool {
    (1..=12).contains(&month)
        && day >= 1
        && (day <= days_in_month(year, month) || (year == 1900 && month == 2 && day == 29))
}

value_text::this_year.text:
/// The calculation's year, from its clock.
fn this_year(context: &ReadContext<'_>) -> Result<i64, Unread> {
    let now = context.now.ok_or(Unread::NotModelled)?;
    if !(0.0..2_958_466.0).contains(&now) {
        return Err(Unread::NotModelled);
    }
    Ok(ymd_1900(now.trunc() as i64).0)
}

value_text::serial_1900.text:
/// The 1900 serial of a date, or #VALUE! outside 1900..=9999.
fn serial_1900(year: i64, month: i64, day: i64) -> Result<i64, Unread> {
    if !(1900..=9999).contains(&year) || !valid_day(year, month, day) {
        return Err(Unread::Rejected);
    }
    Ok(crate::ported::date_kernels::serial_unbounded_1900(
        year, month, day,
    ))
}

value_text::date_of.text:
/// The date that `tokens` (without a time) name, as a 1900 serial.
fn date_of(tokens: &[Token], context: &ReadContext<'_>) -> Result<i64, Unread> {
    // The elements and the separators between them.
    let mut elements: Vec<&Token> = Vec::new();
    let mut separators: Vec<Option<char>> = Vec::new();
    let mut pending: Option<char> = None;
    let mut had_separator = false;
    for token in tokens {
        match token {
            Token::Sep(c) => {
                if had_separator && !(pending == Some(',') && *c == ' ') {
                    return Err(Unread::Rejected);
                }
                if elements.is_empty() {
                    return Err(Unread::Rejected);
                }
                pending = Some(match (pending, *c) {
                    (Some(','), ' ') => ',',
                    (_, c) => c,
                });
                had_separator = true;
            }
            _ => {
                if !elements.is_empty() {
                    separators.push(pending.take());
                }
                elements.push(token);
                had_separator = false;
                pending = None;
            }
        }
    }
    if had_separator || elements.is_empty() {
        return Err(Unread::Rejected);
    }
    let months: Vec<usize> = elements
        .iter()
        .enumerate()
        .filter(|(_, t)| matches!(t, Token::Word(_)))
        .map(|(i, _)| i)
        .collect();
    let number = |t: &Token| match t {
        Token::Number(n, len) => Some((*n, *len)),
        _ => None,
    };
    match months.as_slice() {
        [] => {
            // Numbers only, separated by / or -.
            if separators.iter().any(|s| !matches!(s, Some('/' | '-'))) {
                return Err(Unread::Rejected);
            }
            let nums: Vec<(i64, usize)> = elements.iter().filter_map(|t| number(t)).collect();
            match nums.as_slice() {
                [a, b, c] => {
                    let (y, m, d) = match context.profile.short_date_order {
                        DateComponentOrder::Ymd => (a, b, c),
                        DateComponentOrder::Mdy | DateComponentOrder::Dmy => {
                            return Err(Unread::NotModelled);
                        }
                    };
                    // Fn4 list-controls ql041..ql085: month/day tokens have one or two
                    // digits. A three/four-digit final token is not a day with leading zeros.
                    if matches!(
                        context.profile.id,
                        LocaleId::EnZa | LocaleId::CurrentExcelHost
                    ) && (m.1 > 2 || d.1 > 2)
                    {
                        return Err(Unread::Rejected);
                    }
                    serial_1900(full_year(y.0, y.1), m.0, d.0)
                }
                [a, b] => {
                    if context.profile.short_date_order != DateComponentOrder::Ymd {
                        return Err(Unread::NotModelled);
                    }
                    // Month and day, or day and month, of the clock's year (2024, a leap year,
                    // stands in to test them when there is no clock); else year and month.
                    let year = this_year(context);
                    let test_year = *year.as_ref().unwrap_or(&2024);
                    if valid_day(test_year, a.0, b.0) {
                        serial_1900(year?, a.0, b.0)
                    } else if valid_day(test_year, b.0, a.0) {
                        serial_1900(year?, b.0, a.0)
                    } else if (1..=12).contains(&b.0) {
                        serial_1900(full_year(a.0, a.1), b.0, 1)
                    } else {
                        Err(Unread::Rejected)
                    }
                }
                _ => Err(Unread::Rejected),
            }
        }
        [at] => {
            let Token::Word(word) = elements[*at] else {
                unreachable!()
            };
            let month = month_named(word).ok_or(Unread::Rejected)?;
            // A comma may follow the month name only.
            for (i, s) in separators.iter().enumerate() {
                if *s == Some(',') && i != *at {
                    return Err(Unread::Rejected);
                }
                if matches!(s, Some('/' | ':' | '.')) {
                    return Err(Unread::Rejected);
                }
            }
            let nums: Vec<(i64, usize)> = elements.iter().filter_map(|t| number(t)).collect();
            match (*at, nums.as_slice()) {
                // day month year
                (1, [d, y]) if elements.len() == 3 => serial_1900(full_year(y.0, y.1), month, d.0),
                // day month
                (1, [d]) if elements.len() == 2 => {
                    let year = this_year(context)?;
                    serial_1900(year, month, d.0)
                }
                // month day-or-year
                (0, [n]) if elements.len() == 2 => {
                    if separators[0] == Some(',') {
                        return Err(Unread::Rejected);
                    }
                    let year = this_year(context);
                    let test_year = *year.as_ref().unwrap_or(&2024);
                    if n.1 <= 2 && valid_day(test_year, month, n.0) {
                        serial_1900(year?, month, n.0)
                    } else {
                        serial_1900(full_year(n.0, n.1), month, 1)
                    }
                }
                _ => Err(Unread::Rejected),
            }
        }
        _ => Err(Unread::Rejected),
    }
}

value_text::date_time.text:
fn date_time(text: &str, context: &ReadContext<'_>, allow_time: bool) -> Result<f64, Unread> {
    let tokens = tokens(text)?;
    // A time at the start, or after the last space.
    let mut time = None;
    let mut date_tokens: &[Token] = &tokens;
    if let Some((fraction, taken)) = time_at(&tokens, 0) {
        let rest = &tokens[taken..];
        let rest = match rest.first() {
            None => rest,
            Some(Token::Sep(' ')) => &rest[1..],
            _ => return Err(Unread::Rejected),
        };
        time = Some(fraction);
        date_tokens = rest;
    } else {
        for start in (1..tokens.len()).rev() {
            if tokens[start - 1] != Token::Sep(' ') {
                continue;
            }
            if let Some((fraction, taken)) = time_at(&tokens, start)
                && start + taken == tokens.len()
            {
                time = Some(fraction);
                date_tokens = &tokens[..start - 1];
                break;
            }
        }
    }
    // A trailing colon after the time ("12:" and "1:30:").
    if time.is_none()
        && let Some(Token::Sep(':')) = tokens.last()
        && let Some((fraction, taken)) = time_at(&tokens[..tokens.len() - 1], 0)
        && taken == tokens.len() - 1
    {
        time = Some(fraction);
        date_tokens = &[];
    }
    if time.is_none() && tokens.len() >= 2 {
        let trimmed = &tokens[..tokens.len() - 1];
        if tokens.last() == Some(&Token::Sep(':'))
            && let Some((fraction, taken)) = time_at(trimmed, 0)
            && taken == trimmed.len()
        {
            time = Some(fraction);
            date_tokens = &[];
        }
    }
    if time.is_some() && !allow_time {
        return Err(Unread::NotModelled);
    }
    let date = if date_tokens.is_empty() {
        None
    } else {
        Some(date_of(date_tokens, context)?)
    };
    if date.is_none() && time.is_none() {
        return Err(Unread::Rejected);
    }
    let serial = match (date, context.date_system) {
        (None, _) => 0.0,
        (Some(serial), DateSystem::System1900) => serial as f64,
        (Some(serial), DateSystem::System1904) => {
            let serial = serial as f64 - OFFSET_1904;
            if serial < 0.0 {
                return Err(Unread::Rejected);
            }
            serial
        }
    };
    Ok(match time {
        Some(fraction) if date.is_some() => serial + fraction,
        Some(fraction) => fraction,
        None => serial,
    })
}

catalogue/kit::grid.text:
pub(super) fn grid(
    site: &Site<'_>,
    arguments: &[CalcValue],
    index: usize,
    services: &mut EvalServices<'_>,
) -> Step<Grid> {
    let argument = &arguments[index];
    match argument.core_ref() {
        CoreRef::Reference(reference) => {
            let [area] = reference.areas() else {
                return Err(site.not_modelled(Some(index)));
            };
            if area.cell_count() > GRID_LIMIT {
                return Err(site.not_modelled(Some(index)));
            }
            let (rows, cols) = (area.row_count() as usize, area.column_count() as usize);
            let first = area.first();
            let mut cells = vec![CalcValue::empty(); rows * cols];
            let cells_reader = aggregate::reader(site, services, index)?;
            aggregate::read_reference(
                site,
                cells_reader,
                reference,
                index,
                &mut |_, key, value| {
                    let at = (key.row() - first.row()) as usize * cols
                        + (key.column() - first.column()) as usize;
                    cells[at] = value.clone();
                    Ok(())
                },
            )?;
            Ok(Grid {
                rows,
                cols,
                cells,
                held: true,
            })
        }
        CoreRef::Array(array) => {
            let shape = array.shape();
            Ok(Grid {
                rows: shape.rows,
                cols: shape.cols,
                cells: array.iter_row_major().cloned().collect(),
                held: true,
            })
        }
        _ => Ok(Grid {
            rows: 1,
            cols: 1,
            cells: vec![argument.clone()],
            held: false,
        }),
    }
}

