catalogue/statistics::entry::AVEDEV.text:
1 avedev |s, a, sv| {
    let values = all(s, a, sv, Held::Numbers)?;
    if values.is_empty() {
        return fail(WorksheetErrorCode::Num);
    }
    let mean = values.iter().sum::<f64>() / values.len() as f64;
    let avedev = values.iter().map(|v| (v - mean).abs()).sum::<f64>() / values.len() as f64;
    s.number(avedev)
}

catalogue/kit::numbers.text:
/// The numbers the arguments `from..` give an aggregate that reads held values by `held`, in the
/// reading order: a direct argument through number coercion, a held value as the aggregate rule
/// says (see the aggregate family). The first error is the result.
pub(super) fn numbers(
    site: &Site<'_>,
    arguments: &[CalcValue],
    from: usize,
    to: usize,
    services: &mut EvalServices<'_>,
    held: Held,
) -> Step<Vec<f64>> {
    let mut found = Vec::new();
    aggregate::each_number(site, &arguments[from..to], services, held, &mut |n| {
        found.push(n);
        Ok(())
    })?;
    Ok(found)
}

catalogue/kit::values.text:
/// Every value of the arguments `from..to` in the reading order, with whether it is held (a cell
/// of a reference or an element of an array) or direct.
pub(super) fn values(
    site: &Site<'_>,
    arguments: &[CalcValue],
    from: usize,
    to: usize,
    services: &mut EvalServices<'_>,
    visit: &mut dyn FnMut(bool, &CalcValue) -> Step<()>,
) -> Step<()> {
    aggregate::each_value(
        site,
        &arguments[from..to],
        services,
        &mut |_, origin, value| visit(origin != Origin::Direct, value),
    )
}

catalogue/aggregate::average.text:
/// AVERAGE: the numbers added from 0, the final addition adjusted as in SUM,
/// and divided by how many there are; #DIV/0! when there is none.
fn average(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    mean(AVERAGE, Held::Numbers, arguments, services)
}

catalogue/aggregate::mean.text:
fn mean(
    id: FunctionId,
    held: Held,
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    let site = Site::new(id, services);
    if holds_held_arrays(arguments) {
        return Site::finish(Err(Exit::Error(WorksheetErrorCode::NA)));
    }
    let held_references = if id == AVERAGE {
        match read_held_references(&site, services, arguments, HeldReference::FirstCell) {
            Ok(held) => held,
            Err(exit) => return Site::finish(Err(exit)),
        }
    } else {
        None
    };
    let arguments: &[CalcValue] = held_references.as_deref().unwrap_or(arguments);
    let (mut total, mut counted) = (0.0, 0u64);
    let mut last_left = 0.0;
    let read = each_number(&site, arguments, services, held, &mut |n| {
        last_left = total;
        total = site.add(total, n)?;
        counted += 1;
        Ok(())
    });
    // A count is below 2^53, so it converts to binary64 exactly.
    Site::finish(read.and_then(|()| {
        site.number(site.divide(crate::adjust_final_sum(last_left, total), counted as f64)?)
    }))
}

catalogue/aggregate::holds_held_arrays.text:
/// Whether an array argument holds an array in a cell (dc-h9u).
fn holds_held_arrays(arguments: &[CalcValue]) -> bool {
    arguments.iter().any(|argument| {
        argument.callable_value().is_none()
            && argument
                .as_array()
                .is_some_and(|array| array.holds_arrays())
    })
}

catalogue/aggregate::read_held_reference.text:
/// The arguments with each reference an array argument holds read by `how`; `None`, allocating
/// nothing, when no array argument holds one.
fn read_held_references(
    site: &Site<'_>,
    services: &mut EvalServices<'_>,
    arguments: &[CalcValue],
    how: HeldReference,
) -> Step<Option<Vec<CalcValue>>> {
    let holds = |argument: &CalcValue| {
        argument.callable_value().is_none()
            && argument.as_array().is_some_and(|array| {
                array
                    .iter_row_major()
                    .any(|element| matches!(element.core_ref(), CoreRef::Reference(_)))
            })
    };
    if !arguments.iter().any(holds) {
        return Ok(None);
    }
    let mut read = Vec::with_capacity(arguments.len());
    for (index, argument) in arguments.iter().enumerate() {
        let Some(array) = argument.as_array().filter(|_| holds(argument)) else {
            read.push(argument.clone());
            continue;
        };
        let mut cells = Vec::with_capacity(array.cell_count());
        for element in array.iter_row_major() {
            let CoreRef::Reference(reference) = element.core_ref() else {
                cells.push(element.clone());
                continue;
            };
            cells.push(match how {
                HeldReference::NoNumber => {
                    CalcValue::text(crate::value::ExcelText::from_utf16_code_units(Vec::new()))
                }
                HeldReference::Counted => CalcValue::logical(true),
                HeldReference::FirstCell => {
                    let first = reference.areas()[0].first();
                    let mut value = CalcValue::empty();
                    let cells_reader = reader(site, services, index)?;
                    cells_reader
                        .read_area(GridArea::cell(first), &mut |_, held| {
                            value = held.clone();
                            ControlFlow::Break(())
                        })
                        .map_err(|Unreadable| {
                            Exit::Fault(FunctionFault::ReferenceUnreadable {
                                id: site.id(),
                                index,
                            })
                        })?;
                    value
                }
            });
        }
        read.push(CalcValue::array(
            CalcArray::new(array.shape(), cells).expect("the array's own shape"),
        ));
    }
    Ok(Some(read))
}

catalogue/aggregate::number_of.text:
/// The number that `value`, of argument `index`, gives an aggregate that reads held values by
/// `held`, or `None` when the value is skipped. A direct argument goes through worksheet number
/// coercion, which converts text that reads as a number at an arithmetic site.
pub(super) fn number_of(
    site: &Site<'_>,
    held: Held,
    index: usize,
    origin: Origin,
    value: &CalcValue,
) -> Step<Option<f64>> {
    if matches!(held, Held::ModeNumbers)
        && matches!(value.core_ref(), CoreRef::Text(_) | CoreRef::Logical(_))
    {
        return Ok(None);
    }
    if origin == Origin::Direct {
        if matches!(held, Held::ModeNumbers)
            && matches!(value.core_ref(), CoreRef::Empty | CoreRef::Missing)
        {
            return Err(Exit::Error(WorksheetErrorCode::Value));
        }
        return site.number_argument(index, value).map(Some);
    }
    match (held, value.core_ref()) {
        (_, CoreRef::Number(_)) if value.is_excel_overflow() => {
            Err(Exit::Error(WorksheetErrorCode::Num))
        }
        (_, CoreRef::Number(n)) => site.argument(index, coerce::operand(n)).map(Some),
        (_, CoreRef::Error(code)) => Err(Exit::Error(code)),
        (Held::AverageValues, CoreRef::Text(_)) => Ok(Some(0.0)),
        (Held::Values, CoreRef::Text(_)) if origin == Origin::Held => Ok(Some(0.0)),
        (Held::Values | Held::AverageValues, CoreRef::Logical(b)) if origin == Origin::Held => {
            Ok(Some(if b { 1.0 } else { 0.0 }))
        }
        (Held::Values | Held::AverageValues, CoreRef::Text(_) | CoreRef::Logical(_)) => Ok(None),
        (Held::Numbers | Held::ModeNumbers, CoreRef::Text(_) | CoreRef::Logical(_))
        | (_, CoreRef::Empty | CoreRef::Missing) => Ok(None),
        (_, CoreRef::Array(_) | CoreRef::Reference(_)) => Err(site.not_modelled(Some(index))),
    }
}

catalogue/aggregate::each_number.text:
/// Calls `take` with every number the arguments give, in the reading order.
pub(super) fn each_number(
    site: &Site<'_>,
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
    held: Held,
    take: &mut dyn FnMut(f64) -> Step<()>,
) -> Step<()> {
    read_values(
        site,
        arguments,
        services,
        matches!(held, Held::ModeNumbers),
        &mut |index, origin, value| match number_of(site, held, index, origin, value)? {
            Some(n) => take(n),
            None => Ok(()),
        },
    )
}

catalogue/aggregate::read_values.text:
/// MODE's scalar-cell rule uses the same reader and argument order. A sparse
/// reader need not visit a blank cell, so retain Empty until a value is visited.
fn read_values(
    site: &Site<'_>,
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
    scalar_references: bool,
    visit: &mut dyn FnMut(usize, Origin, &CalcValue) -> Step<()>,
) -> Step<()> {
    for (index, argument) in arguments.iter().enumerate() {
        match argument.core_ref() {
            CoreRef::Reference(reference) => {
                let cells = reader(site, services, index)?;
                if scalar_references
                    && matches!(reference.areas(), [area]
                    if area.row_count() == 1 && area.column_count() == 1)
                {
                    let mut value = CalcValue::empty();
                    read_reference(site, cells, reference, index, &mut |_, _, held| {
                        value = held.clone();
                        Ok(())
                    })?;
                    visit(index, Origin::Direct, &value)?;
                } else {
                    read_reference(site, cells, reference, index, &mut |_, _, value| {
                        visit(index, Origin::Held, value)
                    })?;
                }
            }
            CoreRef::Array(array) => {
                for element in array.iter_row_major() {
                    visit(index, Origin::Element, element)?;
                }
            }
            _ => visit(index, Origin::Direct, argument)?,
        }
    }
    Ok(())
}

catalogue/aggregate::averagea.text:
/// AVERAGEA: AVERAGE, with held text read as 0 and held logicals as 1 and 0.
fn averagea(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    mean(AVERAGEA, Held::AverageValues, arguments, services)
}

catalogue/conditional::averageif.text:
/// AVERAGEIF: the matched numbers added from 0 and divided by how many there are; #DIV/0! when
/// there is none.
fn averageif(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    let site = Site::new(AVERAGEIF, services);
    Site::finish(
        single(&site, arguments, services, true).and_then(|plan| mean(&site, &plan, services)),
    )
}

catalogue/conditional::total.text:
fn total(site: &Site<'_>, plan: &Plan, services: &mut EvalServices<'_>) -> Step<CalcValue> {
    let mut total = 0.0;
    plan.each_matched(site, services, &mut |n| {
        total = site.add(total, n)?;
        Ok(())
    })?;
    site.number(total)
}

catalogue/conditional::mean.text:
fn mean(site: &Site<'_>, plan: &Plan, services: &mut EvalServices<'_>) -> Step<CalcValue> {
    let (mut total, mut counted) = (0.0, 0u64);
    plan.each_matched(site, services, &mut |n| {
        total = site.add(total, n)?;
        counted += 1;
        Ok(())
    })?;
    // A count is below 2^53, so it converts to binary64 exactly.
    site.number(site.divide(total, counted as f64)?)
}

catalogue/conditional::range.text:
/// The reference argument at `index` as a range of one area.
fn range(
    site: &Site<'_>,
    services: &mut EvalServices<'_>,
    arguments: &[CalcValue],
    index: usize,
) -> Step<Range> {
    let CoreRef::Reference(reference) = arguments[index].core_ref() else {
        return Err(Exit::Fault(FunctionFault::ReferenceRequired {
            id: site.id(),
            index,
        }));
    };
    match reference.areas() {
        // dc-ylr: Excel gives the conditional family #VALUE! for a range of a closed workbook.
        [area]
            if services
                .host()
                .is_some_and(|host| host.is_external_sheet(area.sheet())) =>
        {
            Err(Exit::Error(WorksheetErrorCode::Value))
        }
        [area] => Ok(Range { index, area: *area }),
        _ => Err(Exit::Error(WorksheetErrorCode::Value)),
    }
}

catalogue/conditional::single.text:
/// The plan of COUNTIF (no target), SUMIF and AVERAGEIF: the range, its criterion, and the
/// target, which is the range when the third argument is omitted and otherwise the third
/// argument's top-left cell extended to the range's size, cut at the sheet's last row; one cut at
/// the last column is not modelled (see the module documentation).
fn single(
    site: &Site<'_>,
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
    with_target: bool,
) -> Step<Plan> {
    let criteria_range = range(site, services, arguments, 0)?;
    let target = match (with_target, arguments.get(2)) {
        (false, _) => None,
        (true, None) => Some(criteria_range),
        (true, Some(_)) => {
            let given = range(site, services, arguments, 2)?;
            let (rows, columns) = criteria_range.shape();
            let first = given.area.first();
            let last_column = u64::from(first.column()) + u64::from(columns) - 1;
            if last_column > u64::from(MAX_COLUMNS) {
                return Err(site.not_modelled(Some(2)));
            }
            let last_row = (u64::from(first.row()) + u64::from(rows) - 1).min(u64::from(MAX_ROWS));
            let last = CellKey::new(first.sheet(), last_row as u32, last_column as u32)
                .expect("a cell on the sheet");
            let area = GridArea::new(first, last).expect("an area from the given first cell");
            Some(Range { index: 2, area })
        }
    };
    let criterion = criterion(site, services, 1, &arguments[1])?;
    Ok(Plan {
        conditions: vec![(criteria_range, criterion)],
        target,
        size: criteria_range.area.cell_count(),
    })
}

catalogue/conditional::Plan::each_matche.text:
/// Calls `take` with every number of the target in a row that every criterion matches, in
/// row-major order; the first error in such a row is the result.
fn each_matched(
    &self,
    site: &Site<'_>,
    services: &mut EvalServices<'_>,
    take: &mut dyn FnMut(f64) -> Step<()>,
) -> Step<()> {
    let target = self.target.expect("a function with a target range");
    let mut used: Option<Vec<(u64, Used)>> = None;
    let mut conditions = Vec::with_capacity(self.conditions.len());
    for (range, criterion) in &self.conditions {
        let keep = used.is_none() && range.area == target.area;
        let mut kept = Vec::new();
        conditions.push(verdicts(
            site,
            services,
            *range,
            criterion,
            keep.then_some(&mut kept),
        )?);
        if keep {
            used = Some(kept);
        }
    }
    let used = match used {
        Some(used) => used,
        None => target_cells(site, services, target)?,
    };
    let mut cursors = vec![0usize; conditions.len()];
    for (offset, cell) in used {
        match row(&conditions, &mut cursors, offset) {
            Row::Yes => match cell {
                Used::Number(n) => take(n)?,
                Used::Error(code) => return Err(Exit::Error(code)),
            },
            Row::No => {}
            Row::Unknown(index) => return Err(site.not_modelled(Some(index))),
        }
    }
    Ok(())
}

catalogue/conditional::row.text:
/// The verdict of the row at `offset`, at or past every cursor's position: each range's verdict
/// at a cell it holds there, else its verdict on a blank. Moves each cursor to its first held
/// cell at or past `offset`.
fn row(conditions: &[Verdicts], cursors: &mut [usize], offset: u64) -> Row {
    let mut unknown = None;
    for (verdicts, cursor) in conditions.iter().zip(cursors.iter_mut()) {
        while verdicts
            .held
            .get(*cursor)
            .is_some_and(|&(at, _)| at < offset)
        {
            *cursor += 1;
        }
        let verdict = match verdicts.held.get(*cursor) {
            Some(&(at, verdict)) if at == offset => verdict,
            _ => verdicts.blank,
        };
        match verdict {
            Match::No => return Row::No,
            Match::Unknown => {
                unknown.get_or_insert(verdicts.index);
            }
            Match::Yes => {}
        }
    }
    match unknown {
        Some(index) => Row::Unknown(index),
        None => Row::Yes,
    }
}

catalogue/conditional::offset.text:
/// The row-major offset of `key` in `area`.
fn offset(area: GridArea, key: CellKey) -> u64 {
    let first = area.first();
    u64::from(key.row() - first.row()) * u64::from(area.column_count())
        + u64::from(key.column() - first.column())
}

catalogue/conditional::read_range.text:
/// Reads `range` through the cell reader, calling `visit` with the offset and value of each cell
/// visited with a value, in increasing offset order. A reader that visits a cell outside the area
/// or out of row-major order cannot supply it.
fn read_range(
    site: &Site<'_>,
    services: &mut EvalServices<'_>,
    range: Range,
    visit: &mut dyn FnMut(u64, &CalcValue) -> Step<()>,
) -> Step<()> {
    let cells = reader(site, services, range.index)?;
    let reference = ReferenceLike::area(range.area);
    let mut last: Option<u64> = None;
    read_reference(
        site,
        cells,
        &reference,
        range.index,
        &mut |area, key, value| {
            if matches!(value.core_ref(), CoreRef::Empty | CoreRef::Missing) {
                return Ok(());
            }
            let at = offset(area, key);
            if last.is_some_and(|last| last >= at) {
                return Err(Exit::Fault(FunctionFault::ReferenceUnreadable {
                    id: site.id(),
                    index: range.index,
                }));
            }
            last = Some(at);
            visit(at, value)
        },
    )
}

catalogue/conditional::verdicts.text:
/// Reads a criteria range into its verdicts under `criterion`; with `kept`, also keeps the cells
/// a target uses, when the target is this range.
fn verdicts(
    site: &Site<'_>,
    services: &mut EvalServices<'_>,
    range: Range,
    criterion: &Criterion,
    mut kept: Option<&mut Vec<(u64, Used)>>,
) -> Step<Verdicts> {
    let mut held = Vec::new();
    read_range(site, services, range, &mut |at, value| {
        held.push((at, criterion.verdict(site, range.index, value)?));
        if let Some(kept) = kept.as_deref_mut()
            && let Some(cell) = used(site, range.index, value)?
        {
            kept.push((at, cell));
        }
        Ok(())
    })?;
    Ok(Verdicts {
        index: range.index,
        held,
        blank: criterion.verdict(site, range.index, &CalcValue::empty())?,
    })
}

catalogue/conditional::target_cells.text:
/// Reads the target range: the cells a matched row would use, by offset.
fn target_cells(
    site: &Site<'_>,
    services: &mut EvalServices<'_>,
    target: Range,
) -> Step<Vec<(u64, Used)>> {
    let mut kept = Vec::new();
    read_range(site, services, target, &mut |at, value| {
        if let Some(cell) = used(site, target.index, value)? {
            kept.push((at, cell));
        }
        Ok(())
    })?;
    Ok(kept)
}

catalogue/conditional::used.text:
/// What a target cell gives a matched row: a number, an error, or nothing (text, logicals and
/// blank cells are skipped).
fn used(site: &Site<'_>, index: usize, value: &CalcValue) -> Step<Option<Used>> {
    match value.core_ref() {
        CoreRef::Number(n) => Ok(Some(Used::Number(
            site.argument(index, coerce::operand(n))?,
        ))),
        CoreRef::Error(code) => Ok(Some(Used::Error(code))),
        CoreRef::Text(_) | CoreRef::Logical(_) | CoreRef::Empty | CoreRef::Missing => Ok(None),
        CoreRef::Array(_) | CoreRef::Reference(_) => Err(site.not_modelled(Some(index))),
    }
}

catalogue/conditional::Match::of.text:
fn of(holds: bool) -> Self {
    if holds { Match::Yes } else { Match::No }
}

catalogue/conditional::Match::negated.text:
fn negated(self) -> Self {
    match self {
        Match::Yes => Match::No,
        Match::No => Match::Yes,
        Match::Unknown => Match::Unknown,
    }
}

catalogue/conditional::Op::holds.text:
fn holds(self, ordering: Ordering) -> bool {
    match self {
        Op::Equal => ordering.is_eq(),
        Op::NotEqual => ordering.is_ne(),
        Op::Less => ordering.is_lt(),
        Op::LessOrEqual => ordering.is_le(),
        Op::Greater => ordering.is_gt(),
        Op::GreaterOrEqual => ordering.is_ge(),
    }
}

catalogue/conditional::Op::is_equality.text:
fn is_equality(self) -> bool {
    matches!(self, Op::Equal | Op::NotEqual)
}

catalogue/conditional::spells.text:
fn spells(units: &[u16], word: &str) -> bool {
    units.len() == word.len()
        && units.iter().zip(word.bytes()).all(|(&unit, byte)| {
            u8::try_from(unit).is_ok_and(|unit| unit.to_ascii_uppercase() == byte)
        })
}

catalogue/conditional::criterion.text:
/// The criterion argument at `index`, dereferenced when it is a reference to one cell.
fn criterion(
    site: &Site<'_>,
    services: &mut EvalServices<'_>,
    index: usize,
    argument: &CalcValue,
) -> Step<Criterion> {
    let dereferenced;
    let value = match argument.core_ref() {
        CoreRef::Reference(reference) => {
            let [area] = reference.areas() else {
                return Err(site.not_modelled(Some(index)));
            };
            if area.cell_count() != 1 {
                // A criterion of several cells lifts the function over them: not modelled.
                return Err(site.not_modelled(Some(index)));
            }
            let mut found = CalcValue::empty();
            read_range(
                site,
                services,
                Range { index, area: *area },
                &mut |_, value| {
                    found = value.clone();
                    Ok(())
                },
            )?;
            dereferenced = found;
            &dereferenced
        }
        _ => argument,
    };
    match value.core_ref() {
        CoreRef::Number(n) => Ok(Criterion::Number(
            Op::Equal,
            site.argument(index, coerce::operand(n))?,
        )),
        CoreRef::Logical(b) => Ok(Criterion::Logical(Op::Equal, b)),
        CoreRef::Error(code) => Ok(Criterion::Error(Op::Equal, code)),
        // An empty cell given as the criterion, and an omitted criterion, are the value 0.
        CoreRef::Empty | CoreRef::Missing => Ok(Criterion::Number(Op::Equal, 0.0)),
        CoreRef::Text(text) => criterion_text(site, index, text.utf16_code_units()),
        CoreRef::Array(_) | CoreRef::Reference(_) => Err(site.not_modelled(Some(index))),
    }
}

catalogue/conditional::rank.text:
/// An error's place in the order of [`ERROR_CRITERIA`], when it has a literal there.
fn rank(code: WorksheetErrorCode) -> Option<usize> {
    ERROR_CRITERIA.iter().position(|(_, known)| *known == code)
}

catalogue/conditional::criterion_text.text:
/// A criterion written as text; see the module documentation.
fn criterion_text(site: &Site<'_>, index: usize, units: &[u16]) -> Step<Criterion> {
    if units.len() > LONGEST_TEXT {
        return Err(Exit::Error(WorksheetErrorCode::Value));
    }
    let starts = |prefix: &str| {
        units.len() >= prefix.len()
            && units
                .iter()
                .zip(prefix.bytes())
                .all(|(&u, b)| u == u16::from(b))
    };
    let (op, written, rest) = if starts("<=") {
        (Op::LessOrEqual, true, &units[2..])
    } else if starts(">=") {
        (Op::GreaterOrEqual, true, &units[2..])
    } else if starts("<>") {
        (Op::NotEqual, true, &units[2..])
    } else if starts("<") {
        (Op::Less, true, &units[1..])
    } else if starts(">") {
        (Op::Greater, true, &units[1..])
    } else if starts("=") {
        (Op::Equal, true, &units[1..])
    } else {
        (Op::Equal, false, units)
    };
    if rest.is_empty() {
        return Ok(match (op, written) {
            (Op::Equal, false) => Criterion::BlankOrEmptyText,
            (Op::Equal, true) => Criterion::Blank,
            (Op::NotEqual, _) => Criterion::NotBlank,
            _ => Criterion::Never,
        });
    }
    if let Some(&(_, code)) = ERROR_CRITERIA
        .iter()
        .find(|(spelling, _)| spells(rest, spelling))
    {
        return Ok(Criterion::Error(op, code));
    }
    if OTHER_ERRORS.iter().any(|spelling| spells(rest, spelling)) {
        return Err(site.not_modelled(Some(index)));
    }
    let special = |unit: &u16| [b'*', b'?', b'~'].iter().any(|&b| *unit == u16::from(b));
    // Excel 16.0.20527, dc-971p.37 service measurements (2026-11-13): tilde
    // escapes activate only when * or ? occurs. Thus =a~~ matches a~~, while
    // =a~~* matches text beginning a~ and =a~~~* matches the literal a~*.
    if op.is_equality() && rest.iter().any(special) {
        if !rest
            .iter()
            .any(|&unit| unit == u16::from(b'*') || unit == u16::from(b'?'))
        {
            return Ok(Criterion::Text(op, rest.to_vec()));
        }
        let mut tokens = Vec::with_capacity(rest.len());
        let mut at = 0;
        while at < rest.len() {
            let unit = rest[at];
            tokens.push(if unit == u16::from(b'~') {
                match rest.get(at + 1) {
                    Some(&next) if special(&next) => {
                        at += 1;
                        Token::Unit(next)
                    }
                    // Before any other character, or at the end, ~ is itself.
                    _ => Token::Unit(unit),
                }
            } else if unit == u16::from(b'*') {
                Token::Run
            } else if unit == u16::from(b'?') {
                Token::One
            } else {
                Token::Unit(unit)
            });
            at += 1;
        }
        if tokens.iter().all(|token| matches!(token, Token::Unit(_))) {
            let literal = tokens
                .into_iter()
                .map(|token| match token {
                    Token::Unit(unit) => unit,
                    Token::One | Token::Run => unreachable!("only literal units remain"),
                })
                .collect();
            return Ok(Criterion::Text(op, literal));
        }
        return Ok(Criterion::Pattern(op, tokens));
    }
    let operand = CalcValue::text(ExcelText::from_utf16_code_units(rest.to_vec()));
    match site.number_argument(index, &operand) {
        Ok(n) => Ok(Criterion::Number(op, n)),
        // Text that reads as no number: no digit, out of the range Excel reads, or a word outside
        // the words coercion's measured list lets number text hold (such as the label 2016-17
        // Winter).
        Err(Exit::Error(_)) => {
            let logical = if spells(rest, TRUE_TEXT) {
                Some(true)
            } else if spells(rest, FALSE_TEXT) {
                Some(false)
            } else {
                None
            };
            Ok(match logical {
                Some(b) => Criterion::Logical(op, b),
                None => Criterion::Text(op, rest.to_vec()),
            })
        }
        Err(exit) => Err(exit),
    }
}

catalogue/conditional::decided.text:
/// A comparison's step as a verdict: a refusal as not modelled is an unknown verdict, and any
/// other fault (ExactUnavailable) stops the call.
fn decided(step: Step<bool>) -> Step<Match> {
    match step {
        Ok(holds) => Ok(Match::of(holds)),
        Err(Exit::Fault(FunctionFault::NotImplemented { .. })) => Ok(Match::Unknown),
        Err(exit) => Err(exit),
    }
}

catalogue/conditional::Criterion::verdic.text:
/// The verdict of a cell of the range at argument `index` holding `value` (Empty for a blank
/// cell).
pub(super) fn verdict(&self, site: &Site<'_>, index: usize, value: &CalcValue) -> Step<Match> {
    if let CoreRef::Number(n) = value.core_ref() {
        site.argument(index, coerce::operand(n))?;
    }
    let blank = matches!(value.core_ref(), CoreRef::Empty | CoreRef::Missing);
    match self {
        Criterion::BlankOrEmptyText => Ok(Match::of(
            blank
                || value
                    .as_text()
                    .is_some_and(|t| t.len_utf16_code_units() == 0),
        )),
        Criterion::Blank => Ok(Match::of(blank)),
        Criterion::NotBlank => Ok(Match::of(!blank)),
        Criterion::Never => Ok(Match::No),
        Criterion::Number(op, operand) => {
            let cell = match value.core_ref() {
                CoreRef::Number(n) => Some(n),
                // Text is never a number to an ordering or to <>; only = reads it as one.
                CoreRef::Text(_) if *op != Op::Equal => None,
                CoreRef::Text(text) => match site.number_argument(index, value) {
                    Ok(n) => Some(n),
                    // Text that reads as no number (see the criterion's operand above).
                    Err(Exit::Error(_)) => None,
                    // Wildcards and a leading comparison operator in a range cell are
                    // literal, not numeric text, when neither separator uses them. The
                    // recorded separators suffice to reject these ASCII labels.
                    Err(Exit::Fault(FunctionFault::NotImplemented { .. }))
                        if site.number_separators().is_some_and(|(decimal, group)| {
                            let units = text.utf16_code_units();
                            units.iter().all(|u| (0x20..=0x7e).contains(u))
                                && [b'*', b'?', b'~', b'<', b'>'].iter().any(|&c| {
                                    let present = if matches!(c, b'<' | b'>') {
                                        units.first() == Some(&u16::from(c))
                                    } else {
                                        units.contains(&u16::from(c))
                                    };
                                    present
                                        && !decimal.contains(char::from(c))
                                        && !group.contains(char::from(c))
                                })
                        }) => None,
                    Err(exit) => return decided(Err(exit)),
                },
                _ => None,
            };
            let verdict = match cell {
                Some(n) => decided(
                    comparison::numbers(site, n, *operand).map(|ordering| op.holds(ordering)),
                )?,
                None => Match::of(*op == Op::NotEqual),
            };
            Ok(verdict)
        }
        Criterion::Logical(op, operand) => Ok(match value.core_ref() {
            CoreRef::Logical(b) => Match::of(op.holds(b.cmp(operand))),
            CoreRef::Text(text)
                if spells(text.utf16_code_units(), TRUE_TEXT)
                    || spells(text.utf16_code_units(), FALSE_TEXT) =>
            {
                Match::Unknown
            }
            _ => Match::of(*op == Op::NotEqual),
        }),
        Criterion::Error(op, operand) => Ok(match value.core_ref() {
            CoreRef::Error(code) => {
                let ordering = if code == *operand {
                    Some(Ordering::Equal)
                } else if op.is_equality() {
                    Some(Ordering::Less)
                } else {
                    rank(code)
                        .zip(rank(*operand))
                        .map(|(code, operand)| code.cmp(&operand))
                };
                ordering.map_or(Match::Unknown, |ordering| Match::of(op.holds(ordering)))
            }
            CoreRef::Text(text)
                if ERROR_CRITERIA.iter().any(|(spelling, code)| {
                    (code == operand || !op.is_equality())
                        && spells(text.utf16_code_units(), spelling)
                }) =>
            {
                Match::Unknown
            }
            _ => Match::of(*op == Op::NotEqual),
        }),
        Criterion::Text(op, operand) => {
            let Some(text) = value.as_text() else {
                return Ok(Match::of(*op == Op::NotEqual));
            };
            let units = text.utf16_code_units();
            if units.len() > LONGEST_TEXT {
                return Ok(Match::Unknown);
            }
            let want = if op.is_equality() {
                Want::Equality
            } else {
                Want::Order
            };
            Ok(match comparison::texts(units, operand, want) {
                Ok(ordering) => Match::of(op.holds(ordering)),
                Err(_) => Match::Unknown,
            })
        }
        Criterion::Pattern(op, tokens) => {
            let equal = match value.as_text() {
                None => Match::No,
                Some(text) => {
                    let units = text.utf16_code_units();
                    if units.len() > LONGEST_TEXT {
                        Match::Unknown
                    } else if tokens.iter().all(|token| *token == Token::Run) {
                        Match::Yes
                    } else if units.iter().any(|&unit| is_surrogate(unit))
                        || tokens.iter().any(
                            |token| matches!(token, Token::Unit(unit) if is_surrogate(*unit)),
                        )
                    {
                        // A pattern over text holding a character beyond the BMP: whether ?
                        // takes one character or one code unit there is not modelled.
                        Match::Unknown
                    } else {
                        Match::of(wildcard(tokens, units))
                    }
                }
            };
            Ok(equality(*op, equal))
        }
    }
}

catalogue/conditional::equality.text:
/// An equality verdict under `op`, which is = or <>.
fn equality(op: Op, equal: Match) -> Match {
    if op == Op::NotEqual {
        equal.negated()
    } else {
        equal
    }
}

catalogue/conditional::wildcard.text:
/// Whether `text` (no surrogates) matches `pattern`, case ignored character by character through
/// the simple lower-case mapping: Excel 16.0.20430 matched é* to Élan, ασ* to ΑΣ and ǆ* to ǅemal,
/// and matched neither *SSE to Straße nor nai* to naïve (read ad hoc on this machine, dc-ip6).
fn wildcard(pattern: &[Token], text: &[u16]) -> bool {
    let fold = crate::ported::text_kernels::fold_unit;
    let (mut p, mut t) = (0, 0);
    // The last * met: its position in the pattern and the text position its run ends at.
    let mut star: Option<(usize, usize)> = None;
    while t < text.len() {
        match pattern.get(p) {
            Some(Token::Run) => {
                star = Some((p, t));
                p += 1;
                continue;
            }
            Some(Token::One) => {
                p += 1;
                t += 1;
                continue;
            }
            Some(Token::Unit(unit)) if fold(*unit) == fold(text[t]) => {
                p += 1;
                t += 1;
                continue;
            }
            _ => {}
        }
        match star {
            Some((at, end)) => {
                p = at + 1;
                t = end + 1;
                star = Some((at, end + 1));
            }
            None => return false,
        }
    }
    pattern[p..].iter().all(|token| *token == Token::Run)
}

ported/text_kernels::fold_unit.text:
/// A UTF-16 unit with its case folded for SEARCH: the simple lower-case mapping of a unit that is
/// a whole character and maps to one character of one unit; any other unit as it is.
pub(crate) fn fold_unit(unit: u16) -> u16 {
    if unit < 0x80 {
        return if (b'A' as u16..=b'Z' as u16).contains(&unit) {
            unit + 32
        } else {
            unit
        };
    }
    let Some(ch) = char::from_u32(u32::from(unit)) else {
        return unit;
    };
    let mut lower = ch.to_lowercase();
    match (lower.next(), lower.next()) {
        (Some(single), None) if (single as u32) <= 0xFFFF => single as u32 as u16,
        _ => unit,
    }
}

ported/text_kernels::push_lower.text:
fn push_lower(out: &mut String, ch: char, is_final_sigma: bool) {
    // The delivered fn3 LOWER/PROPER readings preserve supplementary pairs.
    if ch as u32 > 0xFFFF {
        out.push(ch);
        return;
    }
    match ch {
        'İ' => out.push('i'),
        'ẞ' => out.push('ẞ'),
        'Σ' if is_final_sigma => out.push('ς'),
        _ => push_singleton_or_original(out, ch.to_lowercase(), ch),
    }
}

ported/text_kernels::lower.text:
pub(crate) fn lower(text: &ExcelText) -> ExcelText {
    let chars = text.to_string_lossy().chars().collect::<Vec<_>>();
    let mut out = String::new();
    let mut previous_letter = false;
    for (index, ch) in chars.iter().copied().enumerate() {
        // The fn1 sigma controls skip preceding marks, while a following mark keeps the
        // nonfinal form even at the end: ΆΣ -> άς; ΑΣ́ -> ασ́.
        let is_final_sigma = ch == 'Σ'
            && previous_letter
            && !chars
                .get(index + 1)
                .is_some_and(|&c| c.is_alphabetic() || calc_value::is_combining_mark(c));
        push_lower(&mut out, ch, is_final_sigma);
        if !calc_value::is_combining_mark(ch) {
            previous_letter = ch.is_alphabetic();
        }
    }
    text_from_str(&out)
}

catalogue/conditional::averageifs.text:
/// AVERAGEIFS: AVERAGEIF over the rows that meet every criterion.
fn averageifs(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    let site = Site::new(AVERAGEIFS, services);
    Site::finish(
        pairs(&site, arguments, services, true).and_then(|plan| mean(&site, &plan, services)),
    )
}

catalogue/conditional::pairs.text:
/// The plan of an *IFS function: its pairs from argument 1 behind the target range (argument 0)
/// when `with_target`, from argument 0 otherwise. A count of arguments that does not form pairs
/// is an arity the entry does not admit. Every range must have the first range's shape.
fn pairs(
    site: &Site<'_>,
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
    with_target: bool,
) -> Step<Plan> {
    let first_pair = usize::from(with_target);
    if !(arguments.len() - first_pair).is_multiple_of(2) {
        return Err(Exit::Fault(FunctionFault::ArityMismatch {
            id: site.id(),
            supplied: arguments.len(),
        }));
    }
    let target = if with_target {
        Some(range(site, services, arguments, 0)?)
    } else {
        None
    };
    let mut ranges = Vec::with_capacity((arguments.len() - first_pair) / 2);
    for index in (first_pair..arguments.len()).step_by(2) {
        ranges.push(range(site, services, arguments, index)?);
    }
    let shape = target.unwrap_or(ranges[0]).shape();
    if ranges.iter().any(|range| range.shape() != shape) {
        return Err(Exit::Error(WorksheetErrorCode::Value));
    }
    let mut conditions = Vec::with_capacity(ranges.len());
    for range in ranges {
        let index = range.index + 1;
        conditions.push((range, criterion(site, services, index, &arguments[index])?));
    }
    Ok(Plan {
        conditions,
        target,
        size: u64::from(shape.0) * u64::from(shape.1),
    })
}

catalogue/text_format::thai_number.text:
/// A whole number (decimal digits, no leading zero) in Thai words: groups of six digits joined by
/// the word for a million; a one in the units after any other digit is "et", a two in the tens is
/// "yi", and a one in the tens is the tens word alone.
fn thai_number(digits: &str) -> String {
    let bytes = digits.as_bytes();
    let mut out = String::new();
    let length = bytes.len();
    for (at, &byte) in bytes.iter().enumerate() {
        let digit = usize::from(byte - b'0');
        let from_right = length - 1 - at;
        let place = from_right % 6;
        if digit != 0 {
            match place {
                0 if digit == 1 && at > 0 => out.push_str(THAI_ET),
                1 if digit == 1 => {}
                1 if digit == 2 => out.push_str(THAI_YI),
                _ => out.push_str(THAI_DIGITS[digit]),
            }
            out.push_str(THAI_PLACES[place]);
        }
        if place == 0 && from_right > 0 {
            out.push_str(THAI_MILLION);
        }
    }
    out
}

catalogue/text_format::bahttext.text:
/// BAHTTEXT: the number rounded to satang (two places, from its 15-digit reading, a half away
/// from zero) in Thai words. Retained BAHTTEXT readings keep the original negative sign
/// even when rounding leaves zero baht and zero satang; signed zero itself has no minus word.
fn bahttext(site: &Site<'_>, a: &[CalcValue]) -> Step<CalcValue> {
    let n = num(site, a, 0)?;
    let (whole, fraction) = format::digits(n, 2);
    let satang = fraction.trim_start_matches('0');
    let negative = n < 0.0;
    let mut out = String::new();
    if negative {
        out.push_str(THAI_MINUS);
    }
    if !whole.is_empty() {
        out.push_str(&thai_number(&whole));
        out.push_str(THAI_BAHT);
    }
    if satang.is_empty() {
        if whole.is_empty() {
            out.push_str(THAI_DIGITS[0]);
            out.push_str(THAI_BAHT);
        }
        out.push_str(THAI_EXACT);
    } else {
        out.push_str(&thai_number(satang));
        out.push_str(THAI_SATANG);
    }
    Ok(crate::catalogue::kit::text_value(&out))
}

