/// The radix functions and BESSELJ refuse logicals with #VALUE! and omitted arguments with #N/A.
/// A blank cell remains distinct from an omitted argument.
fn radix_kind(a: &[CalcValue], index: usize) -> Step<()> {
    match a[index].core_ref() {
        CoreRef::Logical(_) => fail(WorksheetErrorCode::Value),
        CoreRef::Missing => fail(WorksheetErrorCode::NA),
        _ => Ok(()),
    }
}

catalogue/engineering::bessel.text:
fn bessel(
    site: &Site<'_>,
    a: &[CalcValue],
    kernel: fn(f64, f64) -> Result<f64, WorksheetErrorCode>,
    checked_kinds: bool,
) -> Step<CalcValue> {
    if checked_kinds {
        radix_kind(a, 0)?;
    }
    let x = num(site, a, 0)?;
    if checked_kinds {
        radix_kind(a, 1)?;
    }
    let n = num(site, a, 1)?;
    out(site, kernel(x, n))
}

ported/bessel::exp.text:
fn exp<const S: bool>(x: D<S>) -> D<S> {
    D::new(excel_exp(x.0))
}

ported/bessel::horner.text:
/// `c[0] + y (c[1] + y (c[2] + ...))`.
fn horner<const S: bool>(c: &[f64], y: D<S>) -> D<S> {
    let mut r = D(c[c.len() - 1]);
    for &k in c[..c.len() - 1].iter().rev() {
        r = D(k) + y * r;
    }
    r
}

ported/bessel::i1.text:
fn i1<const S: bool>(x: D<S>) -> D<S> {
    let ax = x.abs();
    if ax.0 < 3.75 {
        let t = x / D(3.75);
        x * horner(&I1_SMALL, t * t)
    } else {
        let r = exp(ax) / ax.sqrt() * horner(&I1_LARGE, D(3.75) / ax);
        if x.0 < 0.0 { -r } else { r }
    }
}

ported/bessel::order.text:
/// The order as Excel reads it: truncated; #NUM! when negative or above [`MAX_ORDER`].
fn order(n: f64) -> Result<u32, WorksheetErrorCode> {
    if !(n >= 0.0) {
        return Err(WorksheetErrorCode::Num);
    }
    let n = n.trunc();
    if n > MAX_ORDER {
        return Err(WorksheetErrorCode::Num);
    }
    Ok(n as u32)
}

ported/bessel::odd_sign.text:
fn odd_sign(x: D, n: u32, v: D) -> D {
    if x.0 < 0.0 && n % 2 == 1 { -v } else { v }
}

