ported/bessel::forward.text:
/// The forward recurrence from orders 0 and 1 up to `n`: `next = j (2/x) c - previous` for J and
/// Y, `next = previous + j (2/x) c` for K.
fn forward<const S: bool>(x: D<S>, n: u32, c0: D<S>, c1: D<S>, plus: bool) -> D<S> {
    let tox = D(2.0) / x;
    let (mut before, mut c) = (c0, c1);
    for j in 1..n {
        let step = D(j as f64) * tox * c;
        let next = if plus { before + step } else { step - before };
        before = c;
        c = next;
    }
    c
}

ported/bessel::besselj_kernel.text:
/// `BESSELJ(x, n)`.
pub fn besselj_kernel(x: f64, n: f64) -> Result<f64, WorksheetErrorCode> {
    if !x.is_finite() {
        return Err(WorksheetErrorCode::Num);
    }
    let n = order(n)?;
    let x = D::new(x);
    finish(match n {
        0 => j0(x),
        1 => j1(x),
        _ if x.0 == 0.0 => Ok(D(0.0)),
        _ => {
            let ax = x.abs();
            let v = if ax.0 > n as f64 {
                forward(ax, n, j0(ax)?, j1(ax)?, false)
            } else {
                D::new(super::bessel_rational::jn(n as i32, ax.0))
            };
            Ok(odd_sign(x, n, v))
        }
    })
}

