fn i0<const S: bool>(x: D<S>) -> D<S> {
    let ax = x.abs();
    if ax.0 < 3.75 {
        let t = x / D(3.75);
        horner(&I0_SMALL, t * t)
    } else {
        exp(ax) / ax.sqrt() * horner(&I0_LARGE, D(3.75) / ax)
    }
}

ported/bessel::k0.text:
fn k0<const S: bool>(x: D<S>) -> D<S> {
    if x.0 <= 2.0 {
        let h = x / D(2.0);
        -(ln(h) * i0(x)) + horner(&K0_SMALL, x * x / D(4.0))
    } else {
        exp(-x) / x.sqrt() * horner(&K0_LARGE, D(2.0) / x)
    }
}

ported/bessel::k1.text:
fn k1<const S: bool>(x: D<S>) -> D<S> {
    if x.0 <= 2.0 {
        let h = x / D(2.0);
        ln(h) * i1(x) + D(1.0) / x * horner(&K1_SMALL, x * x / D(4.0))
    } else {
        exp(-x) / x.sqrt() * horner(&K1_LARGE, D(2.0) / x)
    }
}

