ported/beta_gamma_stats_family::gamma_di.text:
pub fn gamma_dist_kernel(
    x: f64,
    alpha: f64,
    beta: f64,
    cumulative: bool,
) -> Result<f64, WorksheetErrorCode> {
    validate_gamma_shape(alpha, beta)?;
    if !x.is_finite() {
        return Err(WorksheetErrorCode::Value);
    }
    if x < 0.0 {
        return Err(WorksheetErrorCode::Num);
    }
    if cumulative {
        // Inverse-problem identity, live Excel 16.0 b20228:
        // GAMMA.DIST(x,0.5,beta,TRUE) == ERF.PRECISE(SQRT(x/beta))
        // for beta in {1,2,4} on 68/68 (and beta=2 on the earlier 154/154
        // bank). Staging is divide-then-sqrt, matching the df=1 chi route
        // when beta=2. Other shapes are not claimed.
        if alpha == 0.5 && beta > 0.0 && beta.is_finite() {
            return crate::ported::special_dist_family::erf_precise_kernel((x / beta).sqrt());
        }
        // Inverse-problem identity, live Excel 16.0 b20228:
        // GAMMA.DIST(x,1,beta,TRUE) == EXPON.DIST(x/beta,1,TRUE)
        // (85/85 on dyadic scales; 11/11 on beta=3 and beta=5).
        // EXPON.DIST(x,1/beta,TRUE) misses by 1 ULP when 1/beta is inexact.
        // PDF identity is false (33/85).
        if alpha == 1.0 {
            return crate::ported::discrete_dist::expon_dist_kernel(x / beta, 1.0, true);
        }
        // W109 lane-3 (2026-07-18): the pre-W109 integer-shape fast path
        // (1 − e^{-x}·Σ x^k/k!) is an OxFunc-side shortcut Excel does NOT
        // take — on the b26 integer-a corpora it scored 8.1% with ±4,400-ULP
        // catastrophics vs 39.4% (worst −10) through the identified GRATIO
        // path. All other shapes route through regularized_gamma_p.
        return Ok(regularized_gamma_p(alpha, x / beta));
    }
    // Gamma(1) = 1 exactly; Lanczos leaves a small nonzero log at this point.
    if x > 0.0 {
        // The density is the Poisson mass at `alpha` of mean `x/beta`, stored, times the stored
        // `alpha/x`: R30's scaled public calls read the ratio, and with this mass every one of
        // the 750 unit-shape rows of the bank agrees, where `exp(-x/beta)/beta` does not.
        use crate::ported::excel_numeric::{excel_x87_div, excel_x87_mul};
        let y = excel_x87_div(x, beta);
        let r = crate::ported::discrete_dist::poisson_mass(alpha, y);
        let pdf = excel_x87_mul(r, excel_x87_div(alpha, x));
        return if pdf.is_finite() {
            Ok(pdf)
        } else {
            Err(WorksheetErrorCode::Num)
        };
    }
    let log_normalizer = if alpha == 1.0 { 0.0 } else { ln_gamma(alpha) };
    let log_pdf = (alpha - 1.0) * crt_log(x) - x / beta - log_normalizer - alpha * crt_log(beta);
    let pdf = crt_exp(log_pdf);
    if pdf.is_finite() {
        Ok(pdf)
    } else {
        Err(WorksheetErrorCode::Num)
    }
}

ported/discrete_dist::stirling_error.text:
///
/// A count that is not whole reaches here from GAMMA.DIST: the series at `n + k` in `[6, 7)`, each
/// step stored into the running value. At `x` next to `a` the exponent is `-s(a)` alone, and that
/// pins `s(a)` to a double: of 2,430 shapes from 1.1 to 7, 2,392 hold within two of 40 rows.
/// The ten-term series at 6 is what puts the error of -3.6 units of 2^-53 just above each integer.
pub(crate) fn stirling_error(n: f64) -> f64 {
    if n == n.floor() && n < 7.0 {
        return STIRLING_ERROR[n as usize];
    }
    let steps = (6.0 - n.floor()).max(0.0);
    let mut s = excel_stirling_series(n + steps);
    let mut k = steps - 1.0;
    while k >= 0.0 {
        s = excel_x87_add(s, excel_stirling_step(n + k));
        k -= 1.0;
    }
    s
}

ported/discrete_dist::deviance.text:
/// Loader's deviance `x ln(x/np) + np - x`. Measured on POISSON.DIST: the series range is
/// `|x - np| < 0.2 (x + np)`, that is `x/np` inside `(2/3, 3/2)`, where Loader has 0.1. Outside it
/// the quotient, its logarithm, the product and `np - x` are each stored and then summed.
pub(crate) fn deviance(x: f64, np: f64) -> f64 {
    if excel_deviance_in_series(x, np) {
        return excel_deviance_series(x, np);
    }
    excel_x87_add(
        excel_x87_mul(x, excel_log(excel_x87_div(x, np))),
        excel_x87_sub(np, x),
    )
}

ported/discrete_dist::beta_density.text:
/// The beta density at `0 < x < 1`, as BETA.DIST(x, a, b, FALSE) gives it on the unit interval and
/// as the cumulative's recurrence arm uses it (dc-6332.8, Excel 16.0.20527; 100 random `x` per
/// shape pair unless said otherwise, `docs/research/beta-family-2026-11-12.md`):
///
/// - Both shapes above 1: the binomial mass of `a - 1` successes in `a + b - 2` trials, its stored
///   exponent and running normalizer, with one more running term, `-LN(a + b - 1)`: all rows at
///   15 pairs from (1.1, 1.1) to (300, 2); with a shape of 1.5, 63 to 95 of 100.
/// - A shape of 1: the mass's end forms, `(b - 1) ln(1 - x)` by the internal logarithm or the
///   stored `(a - 1) LN(x)`, with the running term `-LN(b)` or `-LN(a)`: all rows at 18 shapes.
/// - A shape below 1: `exp((a - 1) LN(x) + (b - 1) ln(1 - x) - ln B)`, the first product stored,
///   the second by the internal logarithm, `ln B` from GAMMALN, as running terms: all rows at 12
///   pairs with the larger shape at most 8. Above 8 the form of `ln B` is not read: `None`.
pub(crate) fn beta_density(x: f64, a: f64, b: f64) -> Option<f64> {
    beta_density_at(x, excel_x87_sub(1.0, x), a, b)
}

ported/discrete_dist::beta_density_at.text:
/// [`beta_density`] at the pair `(x, y)` the incomplete beta holds. Only the form for both shapes
/// above 1 takes `y`; the others form `ln(1 - x)` from `x` (in the recurrence arm BETA.DIST's
/// answers on adjacent `x` with one stored `1 - x` change with the series term alone).
pub(crate) fn beta_density_at(x: f64, y: f64, a: f64, b: f64) -> Option<f64> {
    if a == 1.0 {
        return Some(excel_exp_running(
            excel_log1p_times(b - 1.0, -x),
            &[-excel_log(b)],
        ));
    }
    if b == 1.0 {
        return Some(excel_exp_running(
            excel_x87_mul(a - 1.0, excel_log(x)),
            &[-excel_log(a)],
        ));
    }
    if a < 1.0 || b < 1.0 {
        let ln_beta = crate::ported::special_math_common::excel_ln_beta_small(a, b)?;
        return Some(excel_exp_running(
            excel_x87_mul(a - 1.0, excel_log(x)),
            &[-excel_log1p_times(b - 1.0, -x), ln_beta],
        ));
    }
    let (k, n) = (a - 1.0, a + b - 2.0);
    let exponent = binom_exponent(k, n, x, y);
    let normalizer = binom_normalizer(k, n);
    Some(excel_exp_running(
        exponent,
        &[
            normalizer[0],
            normalizer[1],
            normalizer[2],
            normalizer[3],
            -excel_log(a + b - 1.0),
        ],
    ))
}

ported/discrete_dist::binom_exponent.text:
/// The stored exponent of the binomial mass, `0 < x < n`. The stored order is read from the
/// exponent's grid: 100% of 13,000 rows of six pairs `(n, x)`.
fn binom_exponent(x: f64, n: f64, p: f64, q: f64) -> f64 {
    let lc = excel_x87_sub(stirling_error(n), stirling_error(x));
    let lc = excel_x87_sub(lc, deviance(x, excel_x87_mul(n, p)));
    let lc = excel_x87_sub(lc, stirling_error(n - x));
    excel_x87_sub(lc, deviance(n - x, excel_x87_mul(n, q)))
}

ported/discrete_dist::binom_normalizer.text:
/// `sqrt(n / (2 pi x (n - x)))` as halves of stored logarithms, in this order: outside the series
/// range 41,430 of 41,437 bank and live rows.
fn binom_normalizer(x: f64, n: f64) -> [f64; 4] {
    [
        -excel_log(n) / 2.0,
        excel_log(x) / 2.0,
        excel_log(n - x) / 2.0,
        LN_SQRT_2PI,
    ]
}

ported/discrete_dist::poisson_mass.text:
/// The Poisson mass at `x` for `lambda > 0`, with `x` not necessarily whole: it is also GAMMA.DIST's
/// prefactor `y^a exp(-y) / Gamma(a + 1)`, in the cumulative's arms and in the density, which is the
/// mass times the stored `a/y`. At `a = 2` the error of GAMMA.DIST jumps at `y = 1.1` (5,000 live
/// answers around it), and with this route the bank's failures fall from 29,872 to 594.
///
/// Two routes, split at `lambda = 1.1` (bisected on live answers at `x = 2, 3, 7`) with `x <= 1`
/// always on the first:
///
/// - `exp(x ln lambda - lambda - GAMMALN(x + 1))`.
///   `ln lambda` is stored (the answers sit on its grid) and so is the product with `x`; the stored
///   GAMMALN is why the bank's constants carry its low bits (+1 unit at `x = 2, 8`). The two
///   subtractions are compensated (`excel_exp_compensated`).
/// - Loader's saddle point `exp(-stirling_error(x) - deviance(x, lambda)) / sqrt(2 pi x)`, with the
///   exponent and the exponential each stored: the answers sit on the exponent's binary64 grid
///   once the normalizer is removed, from `lambda` near 4 to 1000 and `x` up to 100.
pub(crate) fn poisson_mass(x: f64, lambda: f64) -> f64 {
    if x == 0.0 {
        return excel_exp(-lambda);
    }
    if x <= 1.0 || lambda < 1.1 {
        let t = excel_x87_mul(x, excel_log(lambda));
        return excel_exp_compensated(t, &[lambda, gammaln_excel(x + 1.0)]);
    }
    let exponent = excel_x87_sub(-stirling_error(x), deviance(x, lambda));
    excel_x87_div(
        excel_exp(exponent),
        (2.0 * core::f64::consts::PI * x).sqrt(),
    )
}

ported/discrete_dist::finite.text:
/// A finite result, with a subnormal one flushed to zero as Excel computes (EXPON.DIST(745,1,FALSE)
/// is 0); otherwise #NUM!.
fn finite(v: f64) -> R {
    if v.is_subnormal() {
        Ok(0.0)
    } else if v.is_finite() {
        Ok(v)
    } else {
        Err(NUM)
    }
}

ported/discrete_dist::expon_dist_kernel.text:
/// `EXPON.DIST(x, lambda, cumulative)`.
pub fn expon_dist_kernel(x: f64, lambda: f64, cumulative: bool) -> R {
    use crate::ported::excel_numeric::excel_x87_mul;
    if x < 0.0 || lambda <= 0.0 {
        return Err(NUM);
    }
    let mut t = excel_x87_mul(lambda, x);
    if !t.is_finite() {
        return Err(NUM);
    }
    if t.is_subnormal() {
        t = 0.0;
    }
    finite(if cumulative {
        -excel_expm1_spilled(-t)
    } else {
        excel_x87_mul(lambda, excel_exp(-t))
    })
}

ported/excel_numeric::top16.text:
#[inline]
fn top16(x: f64) -> u32 {
    (asuint64(x) >> 48) as u32
}

ported/excel_numeric::excel_expm1_intern.text:
/// Excel's internal expm1 (W109 identification, 17,992/18,000 on the
/// EXPON/GAMMA.DIST-a=1 windows): msvcr100 exports no C99 `expm1`, so Excel
/// builds it from its own primitives via Kahan's cancellation-free correction
/// in DOUBLE arithmetic — `u = exp(t)` (the x87 chain, RN53); `t` when
/// `u == 1`; `(u-1)*t/ln(u)` for `|t| < 1` (ln = the fyl2x chain, == CR on
/// everything probed); plain `u - 1` otherwise. The numerator is one double
/// product, then the divide (alternate orderings refuted at 82.9%/84.9%).
pub(crate) fn excel_expm1_internal(t: f64) -> f64 {
    expm1_internal_graph(t, false)
}

ported/excel_numeric::excel_expm1_spille.text:
/// The same cancellation correction with each arithmetic assignment stored from x87 PC64.
/// EXPON.DIST's recorded rows distinguish both the numerator product and the final division
/// from binary64 arithmetic; its density also stores the rate product through x87.
pub(crate) fn excel_expm1_spilled(t: f64) -> f64 {
    expm1_internal_graph(t, true)
}

ported/excel_numeric::expm1_internal_gra.text:
fn expm1_internal_graph(t: f64, spilled: bool) -> f64 {
    // Up to and including DBL_EPSILON the answer is t, where u == 1 alone would run the correction
    // on 1.1e-16 to 2.2e-16: consecutive doubles around 2^-52 show the edge through SINH, the last t
    // at 2^-52 itself, the correction's alternating unit from the next double up.
    if t.abs() <= f64::EPSILON {
        return t;
    }
    let u = excel_exp(t);
    let difference = if spilled {
        excel_x87_sub(u, 1.0)
    } else {
        u - 1.0
    };
    if t.abs() < 1.0 {
        if spilled {
            excel_x87_div(excel_x87_mul(difference, t), excel_log(u))
        } else {
            difference * t / excel_log(u)
        }
    } else {
        difference
    }
}

ported/excel_numeric::excel_x87_mul_add.text:
/// `RN53(RN64(RN64(a * b) + c))`: carry the PC64 product into the sum,
/// then store once to binary64. Both x87 operations use the same backend
/// on native and portable targets, with no binary64 store between them.
pub(crate) fn excel_x87_mul_add(a: f64, b: f64, c: f64) -> f64 {
    let product = Native::mul(&load(a), &load(b), CW);
    Native::store(&Native::add(&product, &load(c), CW), CW)
}

ported/excel_numeric::excel_x87_temme_fi.text:
/// Temme's `c * (w +/- coefficient * t / rta)`, retaining each PC64 result
/// until the final binary64 store. The complement starts from that stored result.
pub(crate) fn excel_x87_temme_finish(
    c: f64,
    w: f64,
    coefficient: f64,
    t: f64,
    rta: f64,
    subtract: bool,
) -> (f64, f64) {
    let correction = Native::div(
        &Native::mul(&load(coefficient), &load(t), CW),
        &load(rta),
        CW,
    );
    let inner = if subtract {
        Native::sub(&load(w), &correction, CW)
    } else {
        Native::add(&load(w), &correction, CW)
    };
    let answer = Native::store(&Native::mul(&load(c), &inner, CW), CW);
    let half = load(0.5);
    let complement = Native::store(
        &Native::add(&half, &Native::sub(&half, &load(answer), CW), CW),
        CW,
    );
    (answer, complement)
}

ported/excel_numeric::log_general_hi_lo.text:
/// Internal: the main `__log` table path, returning the result as an unrounded
/// (hi, lo_rest) pair such that `log(x) == hi + lo_rest` (before final rounding).
/// `ix` is `asuint64(x)` for a NORMAL, positive x already outside the close-to-1
/// window (subnormals must be pre-normalized by the caller as in `excel_log`).
/// Exposing the split lets `excel_log1p` inject the `1+x` compensation term
/// into `lo_rest` and round only once.
#[inline]
fn log_general_hi_lo(ix: u64) -> (f64, f64) {
    let tmp = ix.wrapping_sub(OFF);
    let i = ((tmp >> (52 - LOG_TABLE_BITS)) % N_LOG) as usize;
    let k = (tmp as i64) >> 52; // arithmetic shift
    let iz = ix.wrapping_sub(tmp & (0xfffu64 << 52));
    let (invc, logc) = LOG_TAB[i];
    let z = asdouble(iz);

    // no-FMA path: r = (z - chi - clo) * invc
    let (chi, clo) = LOG_TAB2[i];
    let r = (z - chi - clo) * invc;
    let kd = k as f64;

    let w = kd * LOG_LN2HI + logc;
    let hi = w + r;
    let lo = w - hi + r + kd * LOG_LN2LO;

    let r2 = r * r;
    let a = &LOG_POLY;
    // lo_rest = lo + polynomial (everything except the dominant `hi` term)
    let lo_rest = lo + r2 * a[0] + r * r2 * (a[1] + r * a[2] + r2 * (a[3] + r * a[4]));
    (hi, lo_rest)
}

ported/excel_numeric::excel_log1p.text:
/// log(1 + x) — faithful (~0.5 ULP) deterministic double-precision log1p.
pub(crate) fn excel_log1p(x: f64) -> f64 {
    let ix = asuint64(x);
    let top = top16(x);

    // ---- edge cases ----
    // log1p(0) = +0 ; log1p(-0) = -0 (preserve sign of zero).
    if x == 0.0 {
        return x;
    }
    if x.is_nan() {
        return x + x;
    }
    if x == f64::INFINITY {
        return f64::INFINITY;
    }
    // x < -1 -> NaN ; x == -1 -> -inf.
    if x < -1.0 {
        return (x - x) / (x - x); // NaN
    }
    if x == -1.0 {
        return f64::NEG_INFINITY;
    }

    // ---- small |x|: direct poly1 double-double kernel with f = x ----
    // The __log close-to-1 branch computes log(1+r) with r = (input) - 1. Here
    // the input IS 1+x, so r = x exactly (no rounding), giving a cancellation-
    // free log1p for |x| in [-0x1p-4, 0x1.09p-4].
    // Bounds mirror excel_log's close-to-1 window, expressed on x directly.
    let x_lo = -f64::from_bits(0x3fb0000000000000); // -0x1p-4
    let x_hi = f64::from_bits(0x3fb0900000000000); //  0x1.09p-4
    if x >= x_lo && x <= x_hi {
        let r = x;
        let r2 = r * r;
        let r3 = r * r2;
        let b = &LOG_POLY1;
        let mut y = r3
            * (b[1]
                + r * b[2]
                + r2 * b[3]
                + r3 * (b[4]
                    + r * b[5]
                    + r2 * b[6]
                    + r3 * (b[7] + r * b[8] + r2 * b[9] + r3 * b[10])));
        let w = r * f64::from_bits(0x41a0000000000000); // 0x1p27
        let rhi = r + w - w;
        let rlo = r - rhi;
        let w2 = rhi * rhi * b[0]; // b[0] == -0.5
        let hi = r + w2;
        let mut lo = r - hi + w2;
        lo += b[0] * rlo * (rhi + r);
        y += lo;
        y += hi;
        return y;
    }

    // ---- general path: form 1+x as compensated (uhi, ulo), then
    //      log1p(x) = log(uhi) + ulo/uhi. ----
    let _ = (ix, top);
    // two_sum(1.0, x) (Knuth, no ordering assumption) so uhi + ulo == 1 + x
    // EXACTLY. ulo captures the bits of x lost when rounding 1+x.
    let uhi = 1.0 + x;
    let bv = uhi - 1.0;
    let ulo = (1.0 - (uhi - bv)) + (x - bv);

    // uhi is in (0, 2) and normal here (|x| may be up to 1e6). If uhi happens to
    // land in the close-to-1 window we still get a correct result via the table
    // kernel below (poly1 already handled small x). Get log(uhi) as (hi, lo_rest)
    // and inject the correction ulo/uhi BEFORE the single final rounding:
    //   log(1+x) = log(uhi + ulo) = log(uhi) + ulo/uhi  (d log/du = 1/u).
    let (hi, mut lo_rest) = log_general_hi_lo(asuint64(uhi));
    lo_rest += ulo / uhi;
    hi + lo_rest
}

ported/excel_numeric/x87_chains::pow2_po.text:
/// `2^t` for an extended `t >= 0`: `FRNDINT`, `F2XM1` of the fraction, `+1`, `FSCALE`.
fn pow2_positive<F: Fpu>(t: &Ext80) -> Ext80 {
    let whole = F::rndint(t, CW);
    let fraction = F::sub(t, &whole, CW);
    let m = F::add(&F::f2xm1(&fraction, CW), &ext_one(), CW);
    F::scale(&m, &whole, CW)
}

ported/excel_numeric/x87_chains::pow2.text:
/// `2^t` for an extended `t`; a negative `t` as the extended reciprocal of `2^-t` (measured: the
/// EXP witnesses of small negative arguments are the reciprocals' roundings).
fn pow2<F: Fpu>(t: &Ext80) -> Ext80 {
    if t.0[9] & 0x80 != 0 {
        F::div(&ext_one(), &pow2_positive::<F>(&ext_chs(t, CW)), CW)
    } else {
        pow2_positive::<F>(t)
    }
}

ported/excel_numeric/x87_chains::exp_ext.text:
/// `e^t` for an extended `t`: `2^(t log2 e)`.
fn exp_ext<F: Fpu>(t: &Ext80) -> Ext80 {
    pow2::<F>(&F::mul(t, &ext_l2e(), CW))
}

ported/excel_numeric/x87_chains::exp_wit.text:
fn exp_with<F: Fpu>(x: f64, cw: u16) -> f64 {
    if x.is_nan() {
        return x;
    }
    if x == f64::INFINITY {
        return x;
    }
    if x == f64::NEG_INFINITY {
        return 0.0;
    }
    F::store(&exp_ext::<F>(&load(x)), cw)
}

ported/excel_numeric/x87_chains::excel_e.text:
/// Excel's `EXP`.
pub(crate) fn excel_exp(x: f64) -> f64 {
    exp_with::<Native>(x, CW)
}

ported/excel_numeric/x87_chains::log_wit.text:
/// `constant * log2 x` by `FYL2X`, with the logarithm's special values.
fn log_with<F: Fpu>(x: f64, constant: &Ext80) -> f64 {
    if x.is_nan() {
        return x;
    }
    if x < 0.0 {
        return f64::NAN;
    }
    if x == 0.0 {
        return f64::NEG_INFINITY;
    }
    if x == f64::INFINITY {
        return x;
    }
    if x == 1.0 {
        return 0.0;
    }
    F::store(&F::fyl2x(constant, &load(x), CW), CW)
}

ported/excel_numeric/x87_chains::excel_l.text:
/// Excel's `LN`.
pub(crate) fn excel_log(x: f64) -> f64 {
    log_with::<Native>(x, &ext_ln2())
}

ported/normal_dist_common::stored_horner.text:
/// One Horner evaluation with every product and sum stored to binary64, as `erf_approx` needs.
fn stored_horner(coefficients: &[u64], t: f64) -> f64 {
    use crate::ported::excel_numeric::{excel_x87_add, excel_x87_mul};
    let mut value = 0.0;
    for (i, &bits) in coefficients.iter().enumerate().rev() {
        let c = f64::from_bits(bits);
        value = if i + 1 == coefficients.len() {
            c
        } else {
            excel_x87_add(excel_x87_mul(value, t), c)
        };
    }
    value
}

ported/normal_dist_common::erf_approx.text:
/// The shared ERF body (ERF, ERF.PRECISE, the below-half ERFC complement and GAUSS's tiny
/// route).
///
/// For `|x| < 0.5` Excel evaluates a (4, 5) rational `x * N(t) / D(t)` as compiled double
/// arithmetic on the x87 at precision 64: every operation is `RN53(RN64(..))`, that is, its
/// result is stored to binary64 before the next one reads it, in the order
///
/// ```text
/// t = x*x;  N = Horner(t);  D = Horner(t);  p = x*N;  y = p/D
/// ```
///
/// Excel shows this directly. Stored `N` and `D` step at edges found by bisection to one input
/// ulp, and the two `D` edges measured agree to 1e-15 only with the 64-bit register's half unit on
/// each. Of the store placements raced on 2,000 consecutive answers at each of about 20 sites up
/// to 0.5, all stores leaves 0.5% of the rows unexplained (the coefficients' last bits) and every
/// other placement more than twice that. The measured coefficients give `N1/N0 - D1/D0 = -1/3`
/// to 2e-16 and reproduce erf to a flat offset of 9e-17 up to 0.5, past which the error climbs at
/// once, which places the approximation's design interval.
///
/// Above 0.5 the magnitude is the stored-PC64 complement of the upper ERFC body. Independent
/// public calls agree on 3,328 adjacent inputs; exponent-edge controls distinguish the final
/// PC64 store from strict binary64 subtraction. Exactly 0.5 keeps its existing boundary body.
/// Subnormal arguments cannot be written to a cell (Excel reads them back as zero).
pub fn erf_approx(x: f64) -> f64 {
    if x.is_normal() && x.abs() < 0.5 {
        use crate::ported::excel_numeric::{excel_x87_div, excel_x87_mul};
        let t = excel_x87_mul(x, x);
        let numerator = stored_horner(&ERF_N, t);
        let denominator = stored_horner(&ERF_D, t);
        return excel_x87_div(excel_x87_mul(x, numerator), denominator);
    }
    if x.abs() > 0.5 {
        use crate::ported::excel_numeric::excel_x87_sub;
        return excel_x87_sub(1.0, erfc_upper(x.abs())).copysign(x);
    }
    libm::erf(x)
}

ported/normal_dist_common::erfc_upper.text:
/// The upper branch of Excel's erfc for `x >= 0.5`: `Q = E * F`.
///
/// `E` is measured. `z = RN53(RN64(x*x))` and `E = exp(-z)` are stored to binary64 before use: over
/// 220,000 Excel answers up to `x = 26.5` the residual of `Q` against this `E` times the true
/// `exp(x*x)*erfc(x)` stays within about 10 units of 2^-53, where the exact `exp(-x*x)` spreads by
/// hundreds of units. `z`'s double rounding shows directly: plain binary64 `x*x` leaves outliers of
/// up to 1,024 units.
///
/// `F` has two branches, both relative-error minimax rationals of `exp(x*x)*erfc(x)` in `x`, with
/// `D(0) = 1`, Horner, each product, sum and the final quotient stored to binary64 from precision
/// 64, and `Q` the stored product `E * F`. `x = 4` itself falls below: bisected on consecutive
/// doubles, Excel leaves the table below at the next double up.
///
/// - `1/2 <= x <= 4`: degrees (9, 10), on exactly that interval.
/// - `x > 4`: degrees (8, 9), on `[4, 26.54]`. A fresh solve there reproduces the table read from
///   Excel to 1e-12. 26.54 is Cody's XBIG (26.543) to four digits.
///
/// The degrees and intervals are identified by theory. Of 45 solves of (m, m + 1) on candidate
/// intervals, the binade crossings of the Horner stages of (9, 10) on `[1/2, 4]` alone land on the
/// 30 bias steps of Excel's answers: 27 within 0.002, where the next best has 10. Its predicted stage
/// lines then appear in runs of adjacent doubles at the predicted frequency and amplitude, line by
/// line.
///
/// The solve fixes the leading digits only. The two weakest singular directions of the coefficients
/// differ from it by 4e-8 and 2e-10 relative (the error curve moves by 1e-28), so the printed table
/// came from a less converged solve. Those directions were read from the phases of the stage lines
/// over 140 windows. The low bits were not derived: a search of chained moves over the coefficients,
/// on the squared last-bit error of 1,076,000 Excel answers, fixed them. That the search ended on
/// the table rather than on a fit is shown by answers it did not see, not by its count.
/// R35's adjacent-load probe leaves original tail literals undetermined: over
/// `4 < x <= 26.5`, both neighboring loads of N0--N2, D1--D2 and D4 are absorbed at
/// their first stored sum. N3 and D3 absorb the upward neighbor only;163 fresh
/// separating questions reject their downward neighbors and the other tested
/// changes. This identifies equivalent loads, not unique historical literals.
pub fn erfc_upper(x: f64) -> f64 {
    use crate::ported::excel_numeric::{excel_exp, excel_x87_mul};
    let z = excel_x87_mul(x, x);
    let e = excel_exp(-z);
    if e == 0.0 {
        // Past about 27 the exponential is gone and the polynomials below can overflow.
        return 0.0;
    }
    excel_x87_mul(e, erfc_scaled(x))
}

ported/normal_dist_common::erfc_scaled.text:
/// `exp(x*x)*erfc(x)` for `x >= 1/2`: the stored `F` of [`erfc_upper`] alone, with no exponential.
/// NSWC's erfc1 with `ind = 1`, which Morris's Temme expansion calls.
pub fn erfc_scaled(x: f64) -> f64 {
    use crate::ported::excel_numeric::excel_x87_div;
