    let (answer, complement) =
        crate::ported::excel_numeric::excel_x87_temme_finish(c, w, GRATIO_RT2PIN, t, rta, l < 1.0);
    if l >= 1.0 {
        (complement, answer)
    } else {
        (answer, complement)
    }
}

