/// gamln: evaluation of ln(gamma(a)) for positive a.
fn bratio_gamln(a: f64) -> f64 {
    const D: f64 = 0.418938533204673e0;
    const C0: f64 = 0.833333333333333e-01;
    const C1: f64 = -0.277777777760991e-02;
    const C2: f64 = 0.793650666825390e-03;
    const C3: f64 = -0.595202931351870e-03;
    const C4: f64 = 0.837308034031215e-03;
    const C5: f64 = -0.165322962780713e-02;
    if a <= 0.8 {
        return bratio_gamln1(a) - crt_log(a);
    }
    if a <= 2.25 {
        let t = (a - 0.5) - 0.5;
        return bratio_gamln1(t);
    }
    if a < 10.0 {
        let n = bratio_ftoi(a - 1.25);
        let mut t = a;
        let mut w = 1.0;
        for _ in 0..n {
            t -= 1.0;
            w = t * w;
        }
        return bratio_gamln1(t - 1.0) + crt_log(w);
    }
    let t = crt_pow(1.0 / a, 2.0);
    let w = (((((C5 * t + C4) * t + C3) * t + C2) * t + C1) * t + C0) / a;
    (D + w) + (a - 0.5) * (crt_log(a) - 1.0)
}

ported/special_math_common::bratio_gsuml.text:
/// gsumln: evaluation of ln(gamma(a + b)) for 1 <= a <= 2 and 1 <= b <= 2.
fn bratio_gsumln(a: f64, b: f64) -> f64 {
    let x = a + b - 2.0;
    if x <= 0.25 {
        return bratio_gamln1(1.0 + x);
    }
    if x <= 1.25 {
        return bratio_gamln1(x) + bratio_alnrel(x);
    }
    bratio_gamln1(x - 1.0) + crt_log(x * (1.0 + x))
}

ported/special_math_common::bratio_betal.text:
/// betaln: evaluation of the logarithm of the beta function.
fn bratio_betaln(a0: f64, b0: f64) -> f64 {
    const E: f64 = 0.918938533204673e0;
    let mut a = a0.min(b0);
    let b = a0.max(b0);
    if a >= 8.0 {
        let w = bratio_bcorr(a, b);
        let h = a / b;
        let c = h / (1.0 + h);
        let u = -(a - 0.5) * crt_log(c);
        let v = b * bratio_alnrel(h);
        if u > v {
            return (((-0.5 * crt_log(b) + E) + w) - v) - u;
        }
        return (((-0.5 * crt_log(b) + E) + w) - u) - v;
    }
    if a >= 1.0 {
        // At a = 2, the recorded beta and F tails use the reduction arm.
        if a < 2.0 {
            if b <= 2.0 {
                return bratio_gamln(a) + bratio_gamln(b) - bratio_gsumln(a, b);
            }
            let w = 0.0;
            if b < 8.0 {
                return bratio_betaln_60(a, b, w);
            }
            return bratio_gamln(a) + bratio_algdiv(a, b);
        }
        // a >= 2
        if b > 1000.0 {
            let n = bratio_ftoi(a - 1.0);
            let mut w = 1.0;
            for _ in 0..n {
                a -= 1.0;
                w *= a / (1.0 + a / b);
            }
            return (crt_log(w) - n as f64 * crt_log(b)) + (bratio_gamln(a) + bratio_algdiv(a, b));
        }
        let n = bratio_ftoi(a - 1.0);
        let mut w = 1.0;
        for _ in 0..n {
            a -= 1.0;
            let h = a / b;
            w *= h / (1.0 + h);
        }
        let w = crt_log(w);
        if b >= 8.0 {
            return w + bratio_gamln(a) + bratio_algdiv(a, b);
        }
        return bratio_betaln_60(a, b, w);
    }
    // a < 1
    if b >= 8.0 {
        return bratio_gamln(a) + bratio_algdiv(a, b);
    }
    bratio_gamln(a) + (bratio_gamln(b) - bratio_gamln(a + b))
}

fn bratio_betaln_60(a: f64, b0: f64, w: f64) -> f64 {
    let n = bratio_ftoi(b0 - 1.0);
    let mut z = 1.0;
    let mut b = b0;
    for _ in 0..n {
        b -= 1.0;
        z *= b / (a + b);
    }
    w + crt_log(z) + (bratio_gamln(a) + (bratio_gamln(b) - bratio_gsumln(a, b)))
}

ported/special_math_common::bratio_fpser.text:
/// fpser: power series for Ix(a, b) when b < eps, x <= 0.5.
fn bratio_fpser(a: f64, b: f64, x: f64, eps: f64) -> f64 {
    let mut fp = 1.0;
    if a > 1.0e-3 * eps {
        fp = 0.0;
        let t = a * crt_log(x);
        if t < bratio_exparg(1) {
            return fp;
        }
        fp = crate::ported::excel_numeric::excel_exp(t);
    }
    fp = (b / a) * fp;
    let tol = eps / a;
    let mut an = a + 1.0;
    let mut t = x;
    let mut s = t / an;
    loop {
        an += 1.0;
        t = x * t;
        let c = t / an;
        s += c;
        if c.abs() <= tol {
            break;
        }
    }
    fp * (1.0 + a * s)
}

ported/special_math_common::bratio_apser.text:
/// apser: Ix(a, b) - a series expansion for a very small (used with x <= 0.5).
fn bratio_apser(a: f64, b: f64, x: f64, eps: f64) -> f64 {
    const G: f64 = 0.577215664901533e0;
    let bx = b * x;
    let mut t = x - bx;
    let c;
    if b * eps <= 2.0e-2 {
        c = crt_log(x) + bratio_psi(b) + G + t;
    } else {
        c = crt_log(bx) + G + t;
    }
    let tol = 5.0 * eps * c.abs();
    let mut j = 1.0;
    let mut s = 0.0;
    loop {
        j += 1.0;
        t *= x - bx / j;
        let aj = t / j;
        s += aj;
        if aj.abs() <= tol {
            break;
        }
    }
    -a * (c + s)
}

ported/special_math_common::excel_ln_bet.text:
/// `ln B(a, b)` as Excel forms it when neither shape is above 8: three public GAMMALN values, the
/// larger shape's less the sum's first, each step stored (dc-6332.8: every row of 24 tiny-x
/// BETA.DIST calls at each of 300 shape pairs from 0.25 to 8, Excel 16.0.20527). With a shape of
/// 1, which only the recurrence arm asks for, it is `-LN` of the other shape (879 of 880 calls at
/// b = 2). Above 8 Excel's form is not read (it is within about a unit of the true value, which a
/// difference of GAMMALN values is not): `None`.
pub(crate) fn excel_ln_beta_small(a: f64, b: f64) -> Option<f64> {
    use crate::ported::excel_numeric::{excel_log, excel_x87_add, excel_x87_sub, gammaln_excel};
    let (small, large) = if a <= b { (a, b) } else { (b, a) };
    if large > 8.0 {
        return None;
    }
    if small == 1.0 {
        return Some(-excel_log(large));
    }
    Some(excel_x87_add(
        excel_x87_sub(gammaln_excel(large), gammaln_excel(a + b)),
        gammaln_excel(small),
    ))
}

ported/special_math_common::excel_brcomp.text:
/// `x^a y^b / B(a, b)` as Excel's recurrence arm forms it: the stored `x y` times the beta density
/// (dc-6332.8: with Excel's own density, all 80 calls at each of BETA.DIST(x, a, 2) for eleven
/// `a`, less one row).
fn excel_brcomp(a: f64, b: f64, x: f64, y: f64) -> Option<f64> {
    use crate::ported::excel_numeric::excel_x87_mul;
    let density = crate::ported::discrete_dist::beta_density_at(x, y, a, b)?;
    Some(excel_x87_mul(excel_x87_mul(x, y), density))
}

ported/special_math_common::bratio_bpser.text:
/// bpser: power series expansion for Ix(a, b) when b <= 1 or b*x <= 0.7.
fn bratio_bpser(a: f64, b: f64, x: f64, eps: f64) -> f64 {
    let mut bp = 0.0;
    if x == 0.0 {
        return bp;
    }
    if let Some(ln_beta) = excel_ln_beta_small(a, b) {
        return crate::ported::excel_numeric::excel_beta_power_series(a, b, x, ln_beta);
    }
    let a0 = a.min(b);
    if a0 >= 1.0 {
        let z = a * crt_log(x) - bratio_betaln(a, b);
        bp = crate::ported::excel_numeric::excel_exp(z) / a;
    } else {
        let b0 = a.max(b);
        if b0 >= 8.0 {
            let u = bratio_gamln1(a0) + bratio_algdiv(a0, b0);
            let z = a * crt_log(x) - u;
            bp = (a0 / a) * crate::ported::excel_numeric::excel_exp(z);
        } else if b0 > 1.0 {
            let mut u = bratio_gamln1(a0);
            let m = bratio_ftoi(b0 - 1.0);
            let mut b0m = b0;
            if m >= 1 {
                let mut c = 1.0;
                for _ in 0..m {
                    b0m -= 1.0;
                    c *= b0m / (a0 + b0m);
                }
                u = crt_log(c) + u;
            }
            let z = a * crt_log(x) - u;
            b0m -= 1.0;
            let apb = a0 + b0m;
            let t;
            if apb > 1.0 {
                let uu = a0 + b0m - 1.0;
                t = (1.0 + bratio_gam1(uu)) / apb;
            } else {
                t = 1.0 + bratio_gam1(apb);
            }
            bp = crate::ported::excel_numeric::excel_exp(z) * (a0 / a) * (1.0 + bratio_gam1(b0m))
                / t;
        } else {
            bp = crt_pow(x, a);
            if bp == 0.0 {
                return bp;
            }
            let apb = a + b;
            let z;
            if apb > 1.0 {
                let u = a + b - 1.0;
                z = (1.0 + bratio_gam1(u)) / apb;
            } else {
                z = 1.0 + bratio_gam1(apb);
            }
            let c = (1.0 + bratio_gam1(a)) * (1.0 + bratio_gam1(b)) / z;
            bp = bp * c * (b / apb);
        }
    }
    if bp == 0.0 || a <= 0.1 * eps {
        return bp;
    }
    let mut summ = 0.0;
    let mut n = 0.0;
    let mut c = 1.0;
    let tol = eps / a;
    loop {
        n += 1.0;
        c = c * (0.5 + (0.5 - b / n)) * x;
        let w = c / (a + n);
        summ += w;
        if w.abs() <= tol {
            break;
        }
    }
    bp * (1.0 + a * summ)
}

ported/special_math_common::bratio_bup.text:
/// bup: Ix(a, b) - Ix(a+n, b) evaluated for n a positive integer.
fn bratio_bup(a: f64, b: f64, x: f64, y: f64, n: i32, eps: f64, excel_form: bool) -> f64 {
    use crate::ported::excel_numeric::excel_x87_mul;
    let apb = a + b;
    let ap1 = a + 1.0;
    let mut mu: i32 = 0;
    let mut d = 1.0;
    if !(n == 1 || a < 1.0) {
        if apb >= 1.1 * ap1 {
            mu = bratio_ftoi(bratio_exparg(1).abs());
            let k = bratio_ftoi(bratio_exparg(0));
            if k < mu {
                mu = k;
            }
            let t = mu as f64;
            d = crate::ported::excel_numeric::excel_exp(-t);
        }
    }
    let bp = match if excel_form { excel_brcomp(a, b, x, y) } else { None } {
        // Excel's own form has no scaling by exp(mu).
        Some(h) => {
            d = 1.0;
            crate::ported::excel_numeric::excel_x87_div(h, a)
        }
        None => bratio_brcmp1(mu, a, b, x, y) / a,
    };
    if n == 1 || bp == 0.0 {
        return bp;
    }
    let nm1 = n - 1;
    let mut w = d;
    let mut k: i32 = 0;
    if b > 1.0 {
        if y > 1.0e-4 {
            let r = (b - 1.0) * x / y - a;
            if r >= 1.0 {
                k = nm1;
                let t = nm1 as f64;
                if r < t {
                    k = bratio_ftoi(r);
                }
            }
        } else {
            k = nm1;
        }
    }
    for i in 1..=k {
        let l = (i - 1) as f64;
        d = excel_x87_mul(((apb + l) / (ap1 + l)) * x, d);
        w += d;
    }
    if k != nm1 {
        for i in (k + 1)..=nm1 {
            let l = (i - 1) as f64;
            d = excel_x87_mul(((apb + l) / (ap1 + l)) * x, d);
            w += d;
            if d <= eps * w {
                break;
            }
        }
    }
    // The recurrence and its final product have measured binary64 stores from PC64.
    excel_x87_mul(bp, w)
}

ported/special_math_common::bratio_brcom.text:
/// brcomp: evaluation of x^a * y^b / beta(a, b).
fn bratio_brcomp(a: f64, b: f64, x: f64, y: f64) -> f64 {
    const CONST: f64 = 0.398942280401433e0;
    if x == 0.0 || y == 0.0 {
        return 0.0;
    }
    let a0 = a.min(b);
    if a0 >= 8.0 {
        let (h, x0, y0, lambda_);
        if a > b {
            h = b / a;
            x0 = 1.0 / (1.0 + h);
            y0 = h / (1.0 + h);
            lambda_ = (a + b) * y - b;
        } else {
            h = a / b;
            x0 = h / (1.0 + h);
            y0 = 1.0 / (1.0 + h);
            lambda_ = a - (a + b) * x;
        }
        let mut e = -lambda_ / a;
        let u = if e.abs() > 0.6 {
            e - crt_log(x / x0)
        } else {
            bratio_rlog1(e)
        };
        e = lambda_ / b;
        let v = if e.abs() > 0.6 {
            e - crt_log(y / y0)
        } else {
            bratio_rlog1(e)
        };
        let z = crate::ported::excel_numeric::excel_exp(-(a * u + b * v));
        return CONST
            * (b * x0).sqrt()
            * z
            * crate::ported::excel_numeric::excel_exp(-bratio_bcorr(a, b));
    }

    let lnx;
    let lny;
    if x > 0.375 {
        if y > 0.375 {
            lnx = crt_log(x);
            lny = crt_log(y);
        } else {
            lnx = bratio_alnrel(-y);
            lny = crt_log(y);
        }
    } else {
        lnx = crt_log(x);
        lny = bratio_alnrel(-x);
    }
    let mut z = a * lnx + b * lny;
    if a0 >= 1.0 {
        z -= bratio_betaln(a, b);
        return crate::ported::excel_numeric::excel_exp(z);
    }
    let mut b0 = a.max(b);
    if b0 >= 8.0 {
        let u = bratio_gamln1(a0) + bratio_algdiv(a0, b0);
        return a0 * crate::ported::excel_numeric::excel_exp(z - u);
    }
    if b0 > 1.0 {
        let mut u = bratio_gamln1(a0);
        let n = bratio_ftoi(b0 - 1.0);
        if n >= 1 {
            let mut c = 1.0;
            for _ in 0..n {
                b0 -= 1.0;
                c *= b0 / (a0 + b0);
            }
            u = crt_log(c) + u;
        }
        z -= u;
        b0 -= 1.0;
        let apb = a0 + b0;
        let t;
        if apb > 1.0 {
            let uu = a0 + b0 - 1.0;
            t = (1.0 + bratio_gam1(uu)) / apb;
        } else {
            t = 1.0 + bratio_gam1(apb);
        }
        return a0 * crate::ported::excel_numeric::excel_exp(z) * (1.0 + bratio_gam1(b0)) / t;
    }
    let br = crate::ported::excel_numeric::excel_exp(z);
    if br == 0.0 {
        return br;
    }
    let apb = a + b;
    let zz;
    if apb > 1.0 {
        let u = a + b - 1.0;
        zz = (1.0 + bratio_gam1(u)) / apb;
    } else {
        zz = 1.0 + bratio_gam1(apb);
    }
    let c = (1.0 + bratio_gam1(a)) * (1.0 + bratio_gam1(b)) / zz;
    br * (a0 * c) / (1.0 + a0 / b0)
}

ported/special_math_common::bratio_brcmp.text:
/// brcmp1: evaluation of exp(mu) * x^a * y^b / beta(a, b).
fn bratio_brcmp1(mu: i32, a: f64, b: f64, x: f64, y: f64) -> f64 {
    const CONST: f64 = 0.398942280401433e0;
    let a0 = a.min(b);
    if a0 >= 8.0 {
        let (h, x0, y0, lambda_);
        if a > b {
            h = b / a;
            x0 = 1.0 / (1.0 + h);
            y0 = h / (1.0 + h);
            lambda_ = (a + b) * y - b;
        } else {
            h = a / b;
            x0 = h / (1.0 + h);
            y0 = 1.0 / (1.0 + h);
            lambda_ = a - (a + b) * x;
        }
        let mut e = -lambda_ / a;
        let u = if e.abs() > 0.6 {
            e - crt_log(x / x0)
        } else {
            bratio_rlog1(e)
        };
        e = lambda_ / b;
        let v = if e.abs() > 0.6 {
            e - crt_log(y / y0)
        } else {
            bratio_rlog1(e)
        };
        let z = bratio_esum(mu, -(a * u + b * v));
        return CONST
            * (b * x0).sqrt()
            * z
            * crate::ported::excel_numeric::excel_exp(-bratio_bcorr(a, b));
    }

    let lnx;
    let lny;
    if x > 0.375 {
        if y > 0.375 {
            lnx = crt_log(x);
            lny = crt_log(y);
        } else {
            lnx = bratio_alnrel(-y);
            lny = crt_log(y);
        }
    } else {
        lnx = crt_log(x);
        lny = bratio_alnrel(-x);
    }
    let mut z = a * lnx + b * lny;
    if a0 >= 1.0 {
        z -= bratio_betaln(a, b);
        return bratio_esum(mu, z);
    }
    let mut b0 = a.max(b);
    if b0 >= 8.0 {
        let u = bratio_gamln1(a0) + bratio_algdiv(a0, b0);
        return a0 * bratio_esum(mu, z - u);
    }
    if b0 > 1.0 {
        let mut u = bratio_gamln1(a0);
        let n = bratio_ftoi(b0 - 1.0);
        if n >= 1 {
            let mut c = 1.0;
            for _ in 0..n {
                b0 -= 1.0;
                c *= b0 / (a0 + b0);
            }
            u = crt_log(c) + u;
        }
        z -= u;
        b0 -= 1.0;
        let apb = a0 + b0;
        let t;
        if apb > 1.0 {
            let uu = a0 + b0 - 1.0;
            t = (1.0 + bratio_gam1(uu)) / apb;
        } else {
            t = 1.0 + bratio_gam1(apb);
        }
        return a0 * bratio_esum(mu, z) * (1.0 + bratio_gam1(b0)) / t;
    }
    let br = bratio_esum(mu, z);
    if br == 0.0 {
        return br;
    }
    let apb = a + b;
    let zz;
    if apb > 1.0 {
        let u = a + b - 1.0;
        zz = (1.0 + bratio_gam1(u)) / apb;
    } else {
        zz = 1.0 + bratio_gam1(apb);
    }
    let c = (1.0 + bratio_gam1(a)) * (1.0 + bratio_gam1(b)) / zz;
    br * (a0 * c) / (1.0 + a0 / b0)
}

ported/special_math_common::bratio_bfrac.text:
/// bfrac: continued fraction expansion for Ix(a, b) when a, b > 1.
fn bratio_bfrac(a: f64, b: f64, x: f64, y: f64, lambda_: f64, eps: f64) -> f64 {
    let bf = bratio_brcomp(a, b, x, y);
    if bf == 0.0 {
        return bf;
    }
    let c = 1.0 + lambda_;
    let c0 = b / a;
    let c1 = 1.0 + 1.0 / a;
    let yp1 = y + 1.0;
    let mut n = 0.0;
    let mut p = 1.0;
    let mut s = a + 1.0;
    let mut an = 0.0;
    let mut bn = 1.0;
    let mut anp1 = 1.0;
    let mut bnp1 = c / c1;
    let mut r = c1 / c;
    loop {
        n += 1.0;
        let t0 = n / a;
        let w = n * (b - n) * x;
        let mut e = a / s;
        let alpha = (p * (p + c0) * e * e) * (w * x);
        e = (1.0 + t0) / (c1 + t0 + t0);
        let beta = n + w / s + e * (c + n * yp1);
        p = 1.0 + t0;
        s += 2.0;
        let mut t = alpha * an + beta * anp1;
        an = anp1;
        anp1 = t;
        t = alpha * bn + beta * bnp1;
        bn = bnp1;
        bnp1 = t;
        let r0 = r;
        r = anp1 / bnp1;
        if (r - r0).abs() <= eps * r {
            break;
        }
        an /= bnp1;
        bn /= bnp1;
        anp1 = r;
        bnp1 = 1.0;
    }
    bf * r
}

ported/special_math_common::bratio_bgrat.text:
/// bgrat: asymptotic expansion for Ix(a, b) when a is larger than b. Adds the
/// expansion to `w`; returns (w_new, ierr).
fn bratio_bgrat(a: f64, b: f64, x: f64, y: f64, w: f64, eps: f64) -> (f64, i32) {
    let mut c = [0.0f64; 31];
    let mut d = [0.0f64; 31];
    let bm1 = (b - 0.5) - 0.5;
    let nu = a + 0.5 * bm1;
    // Excel's `z` is the stored `nu * LN(x)` at every x (dc-6332.8: at a = 200 its answers sit
    // within 4 units, one sigma, of the true value carried through that stored product, at ten
    // values of b; with the rational below, the 90th percentile at (200, 0.3) is 59 units away,
    // with LN 5). It is not taken yet: the arm's other pieces are not read, the bank moves by one
    // row, and the three rows pinned below move from 3, 5, 3 to 9, 5, 3 units.
    let lnx = if y > 0.375 {
        crt_log(x)
    } else {
        bratio_alnrel(-y)
    };
    let z = -nu * lnx;
    if b * z == 0.0 {
        return (w, 1);
    }
    let mut r =
        b * (1.0 + bratio_gam1(b)) * crate::ported::excel_numeric::excel_exp(b * crt_log(z));
    r = r
        * crate::ported::excel_numeric::excel_exp(a * lnx)
        * crate::ported::excel_numeric::excel_exp(0.5 * bm1 * lnx);
    // The gamma-family pieces, as the gamma upper tail forms them: the prefactor `r` is `z` times
    // the gamma density at `b`, and `u / r = Gamma(a+b) / (Gamma(a) nu^b)` is one exponential of
    // `(n - 1/2) log1p(b/a) - b log1p((b-1)/(2a)) - b + s(n) - s(a)` with the measured real-shape
    // Stirling errors (dc-6332.4: BETA.DIST bank rows gained 75, lost 35).
    if let Ok(dens) = crate::ported::beta_gamma_stats_family::gamma_dist_kernel(z, b, 1.0, false) {
        r = z * dens;
    }
    let n = a + b;
    let v1 = (n - 0.5) * crate::ported::excel_numeric::excel_log1p(b / a);
    let l2 = -crate::ported::excel_numeric::excel_log1p(bm1 / (2.0 * a));
    let g = (((v1 + b * l2) - b) + crate::ported::discrete_dist::stirling_error(n))
        - crate::ported::discrete_dist::stirling_error(a);
    let u = r * crate::ported::excel_numeric::excel_exp(g);
    if u == 0.0 {
        return (w, 1);
    }
    let (_p, q) = bratio_grat1(b, z, r, eps);
    let v = 0.25 * crt_pow(1.0 / nu, 2.0);
    let t2 = 0.25 * lnx * lnx;
    let l = w / u;
    let mut j = q / r;
    let mut summ = j;
    let mut t = 1.0;
    let mut cn = 1.0;
    let mut n2 = 0.0;
    for n in 1..=30usize {
        let bp2n = b + n2;
        j = (bp2n * (bp2n + 1.0) * j + (z + bp2n + 1.0) * t) * v;
        n2 += 2.0;
        t *= t2;
        cn /= n2 * (n2 + 1.0);
        c[n] = cn;
        let mut s = 0.0;
        if n != 1 {
            let nm1 = n - 1;
            let mut coef = b - n as f64;
            for i in 1..=nm1 {
                s += coef * c[i] * d[n - i];
                coef += b;
            }
        }
        d[n] = bm1 * cn + s / n as f64;
        let dj = d[n] * j;
        summ += dj;
        if summ <= 0.0 {
            return (w, 1);
        }
        if dj.abs() <= eps * (summ + l) {
            break;
        }
    }
    (w + u * summ, 0)
}

ported/special_math_common::bratio_grat1.text:
/// grat1: evaluation of (P(a,x), Q(a,x)) for a <= 1.
fn bratio_grat1(a: f64, x: f64, r: f64, eps: f64) -> (f64, f64) {
    if a * x == 0.0 {
        if x <= a {
            return (0.0, 1.0);
        }
        return (1.0, 0.0);
    }
    if a == 0.5 {
        if x < 0.25 {
            let p = bratio_erf_nswc(x.sqrt());
            return (p, 0.5 + (0.5 - p));
        }
        let q = bratio_erfc1(0, x.sqrt());
        return (0.5 + (0.5 - q), q);
    }
    if x < 1.1 {
        let mut an = 3.0;
        let mut c = x;
        let mut summ = x / (a + 3.0);
        let tol = 0.1 * eps / (a + 1.0);
        loop {
            an += 1.0;
            c = -c * (x / an);
            let t = c / (a + an);
            summ += t;
            if t.abs() <= tol {
                break;
            }
        }
        let j = a * x * ((summ / 6.0 - 0.5 / (a + 2.0)) * x + 1.0 / (a + 1.0));
        let z = a * crt_log(x);
        let h = bratio_gam1(a);
        let g = 1.0 + h;
        let go50 = if x < 0.25 { z > -0.13394 } else { a < x / 2.59 };
        if go50 {
            let l = bratio_rexp(z);
            let w = 0.5 + (0.5 + l);
            let q = (w * j - l) * g - h;
            if q < 0.0 {
                return (1.0, 0.0);
            }
            return (0.5 + (0.5 - q), q);
        }
        let w = crate::ported::excel_numeric::excel_exp(z);
        let p = w * g * (0.5 + (0.5 - j));
        return (p, 0.5 + (0.5 - p));
    }
    // continued fraction
    let mut a2nm1 = 1.0;
    let mut a2n = 1.0;
    let mut b2nm1 = x;
    let mut b2n = x + (1.0 - a);
    let mut c = 1.0;
    let mut an0;
    loop {
        a2nm1 = x * a2n + c * a2nm1;
        b2nm1 = crate::ported::excel_numeric::excel_x87_mul_add(x, b2n, c * b2nm1);
        let am0 = a2nm1 / b2nm1;
        c += 1.0;
        let cma = c - a;
        a2n = a2nm1 + cma * a2n;
        b2n = b2nm1 + cma * b2n;
        an0 = a2n / b2n;
        if (an0 - am0).abs() < eps * an0 {
            break;
        }
    }
    let q = r * an0;
    (0.5 + (0.5 - q), q)
}

ported/special_math_common::bratio_basym.text:
/// basym: asymptotic expansion for Ix(a, b) when a and b are large.
fn bratio_basym(a: f64, b: f64, lambda_: f64, eps: f64) -> f64 {
    let num = 20usize;
    const E0: f64 = 1.12837916709551;
    const E1: f64 = 0.353553390593274;
    let mut a0 = [0.0f64; 22];
    let mut b0 = [0.0f64; 22];
    let mut c = [0.0f64; 22];
    let mut d = [0.0f64; 22];
    let ba = 0.0;
    let (h, r0, r1, w0);
    if a >= b {
        h = b / a;
        r0 = 1.0 / (1.0 + h);
        r1 = (b - a) / a;
        w0 = 1.0 / (b * (1.0 + h)).sqrt();
    } else {
        h = a / b;
        r0 = 1.0 / (1.0 + h);
        r1 = (b - a) / b;
        w0 = 1.0 / (a * (1.0 + h)).sqrt();
    }
    let f = a * bratio_rlog1(-lambda_ / a) + b * bratio_rlog1(lambda_ / b);
    let t = crate::ported::excel_numeric::excel_exp(-f);
    if t == 0.0 {
        return ba;
    }
    let z0 = f.sqrt();
    let z = 0.5 * (z0 / E1);
    let z2 = f + f;
    a0[1] = (2.0 / 3.0) * r1;
    c[1] = -0.5 * a0[1];
    d[1] = -c[1];
    let mut j0 = (0.5 / E0) * bratio_erfc1(1, z0);
    let mut j1 = E1;
    let mut summ = j0 + d[1] * w0 * j1;
    let mut s = 1.0;
    let h2 = h * h;
    let mut hn = 1.0;
    let mut w = w0;
    let mut znm1 = z;
    let mut zn = z2;
    let mut n = 2usize;
    while n <= num {
        hn = h2 * hn;
        a0[n] = 2.0 * r0 * (1.0 + h * hn) / (n as f64 + 2.0);
        let np1 = n + 1;
        s += hn;
        a0[np1] = 2.0 * r1 * s / (n as f64 + 3.0);
        for i in n..=np1 {
            let r = -0.5 * (i as f64 + 1.0);
            b0[1] = r * a0[1];
            for m in 2..=i {
                let mut bsum = 0.0;
                let mm1 = m - 1;
                for jj in 1..=mm1 {
                    let mmj = m - jj;
                    bsum += (jj as f64 * r - mmj as f64) * a0[jj] * b0[mmj];
                }
                b0[m] = r * a0[m] + bsum / m as f64;
            }
            c[i] = b0[i] / (i as f64 + 1.0);
            let mut dsum = 0.0;
            let im1 = i - 1;
            for jj in 1..=im1 {
                let imj = i - jj;
                dsum += d[imj] * c[jj];
            }
            d[i] = -(dsum + c[i]);
        }
        j0 = E1 * znm1 + (n as f64 - 1.0) * j0;
        j1 = E1 * zn + n as f64 * j1;
        znm1 = z2 * znm1;
        zn = z2 * zn;
        w = w0 * w;
        let t0 = d[n] * w * j0;
        w = w0 * w;
        let t1 = d[np1] * w * j1;
        summ += t0 + t1;
        if (t0.abs() + t1.abs()) <= eps * summ {
            break;
        }
        n += 2;
    }
    let u = crate::ported::excel_numeric::excel_exp(-bratio_bcorr(a, b));
    E0 * t * u * summ
}

ported/special_math_common::bratio.text:
/// bratio: evaluation of the incomplete beta function Ix(a, b). Returns
/// (w, w1) = (Ix(a, b), 1 - Ix(a, b)). Domain errors (the Fortran ierr != 0
/// cases) return (NaN, NaN).
pub fn bratio(a: f64, b: f64, x: f64, y: f64) -> (f64, f64) {
    let eps0 = bratio_spmpar1();
    let mut w;
    let mut w1 = 0.0; // read as the seed of the bgrat_150 branch
    if a < 0.0 || b < 0.0 {
        return (f64::NAN, f64::NAN);
    }
    if a == 0.0 && b == 0.0 {
        return (f64::NAN, f64::NAN);
    }
    if x < 0.0 || x > 1.0 {
        return (f64::NAN, f64::NAN);
    }
    if y < 0.0 || y > 1.0 {
        return (f64::NAN, f64::NAN);
    }
    let z = ((x + y) - 0.5) - 0.5;
    if z.abs() > 3.0 * eps0 {
        return (f64::NAN, f64::NAN);
    }
    if x == 0.0 {
        if a == 0.0 {
            return (f64::NAN, f64::NAN);
        }
        return (0.0, 1.0);
    }
    if y == 0.0 {
        if b == 0.0 {
            return (f64::NAN, f64::NAN);
        }
        return (1.0, 0.0);
    }
    if a == 0.0 {
        return (1.0, 0.0);
    }
    if b == 0.0 {
        return (0.0, 1.0);
    }
    let eps = eps0.max(1.0e-15);
    // Excel 20527's half/half integral is the arcsine graph, with the
    // complementary coordinate at and above 0.9. Public controls also show that
    // this arm forms its own 1-x rather than retaining a wrapper's y.
    if a == 0.5 && b == 0.5 {
        use crate::ported::excel_numeric::{
            excel_sqrt_staged, excel_x87_div, excel_x87_mul, excel_x87_sub,
        };
        let coordinate = if x < 0.9 { x } else { excel_x87_sub(1.0, x) };
        let angle = crate::ported::asin::asin_kernel(excel_sqrt_staged(coordinate)).unwrap_or(f64::NAN);
        let small = excel_x87_div(excel_x87_mul(2.0, angle), std::f64::consts::PI);
        return if x < 0.9 {
            (small, 0.5 + (0.5 - small))
        } else {
            (0.5 + (0.5 - small), small)
        };
    }
    // bgrat runs at `eps`, not TOMS 708's `15 * eps`: at 1.5e-14 its truncated positive series
    // sat about 5 units low on average over the BETA.DIST bank (mean |ulp| 8.1, signed -5.3);
    // at `eps` 3.9 and +0.3, with 31 rows gained and 8 lost (dc-ymjf.6).
    // The unit-shape arms, read from single-bit-stepped public calls (Excel 16.0 b20527). With
    // b = 1 and x <= 0.9 the answer is exp(a * log x), one rounding of each, on every x and shape
    // asked; b = 1 +- 1 ulp leaves this arm, and just above 0.9 the answer is the complement of
    // I_{1-x}(1, a). With a = 1 and x >= 0.1 it is that complement's own arm,
    // 0.5 + (0.5 - exp(b * log y)); below 0.1 it is -expm1(b * log1p(-x)) with the
    // product taken on the x87 chain (R43: 3,000 of 3,000 public calls, b from 0.3 to 1,000
    // and x from 1e-9 to 0.0999; the spilled and internal EXPM1 graphs agree on all 20,000
    // sampled arguments, so which of them Excel runs is undetermined).
    if b == 1.0 && x <= 0.9 {
        let w = crate::ported::excel_numeric::excel_exp(a * crt_log(x));
        return (w, 0.5 + (0.5 - w));
    }
    if a == 1.0 && x >= 0.1 {
        let w1 = crate::ported::excel_numeric::excel_exp(b * crt_log(y));
        return (0.5 + (0.5 - w1), w1);
    }
    if a == 1.0 {
        use crate::ported::excel_numeric::{excel_expm1_spilled, excel_log1p_times};
        let w = -excel_expm1_spilled(excel_log1p_times(b, -x));
        return (w, 0.5 + (0.5 - w));
    }
    if a.max(b) < 1.0e-3 * eps {
        return (b / (a + b), a / (a + b));
    }

    let mut ind = 0;
    let mut a0 = a;
    let mut b0 = b;
    let mut x0 = x;
    let mut y0 = y;
    if a0.min(b0) <= 1.0 {
        // procedure for a0 <= 1 or b0 <= 1
        if x > 0.5 {
            ind = 1;
            a0 = b;
            b0 = a;
            x0 = y;
            y0 = x;
        }
        let branch: &str;
        if b0 < eps.min(eps * a0) {
            branch = "fpser";
        } else if a0 < eps.min(eps * b0) && b0 * x0 <= 1.0 {
            branch = "apser";
        } else if a0.max(b0) > 1.0 {
            if b0 <= 1.0 {
                branch = "bpser";
            } else if x0 >= 0.3 {
                branch = "bpser_sym";
            } else if x0 < 0.1 && crt_pow(x0 * b0, a0) <= 0.7 {
                branch = "bpser";
            } else if b0 > 15.0 {
                branch = "bgrat_150";
            } else {
                branch = "bup_140";
            }
        } else if a0 >= 0.2_f64.min(b0) {
            branch = "bpser";
        } else if crt_pow(x0, a0) <= 0.9 {
            branch = "bpser";
        } else if x0 >= 0.3 {
            branch = "bpser_sym";
        } else {
            branch = "bup_140";
        }

        match branch {
            "fpser" => {
                w = bratio_fpser(a0, b0, x0, eps);
                w1 = 0.5 + (0.5 - w);
            }
            "apser" => {
                w1 = bratio_apser(a0, b0, x0, eps);
                w = 0.5 + (0.5 - w1);
            }
            "bpser" => {
                w = bratio_bpser(a0, b0, x0, eps);
                w1 = 0.5 + (0.5 - w);
            }
            "bpser_sym" => {
                w1 = bratio_bpser(b0, a0, y0, eps);
                w = 0.5 + (0.5 - w1);
            }
            "bup_140" => {
                let n = 20;
                w1 = bratio_bup(b0, a0, y0, x0, n, eps, false);
                b0 += n as f64;
                let (nw1, _ie) = bratio_bgrat(b0, a0, y0, x0, w1, eps);
                w1 = nw1;
                w = 0.5 + (0.5 - w1);
            }
            "bgrat_150" => {
                let (nw1, _ie) = bratio_bgrat(b0, a0, y0, x0, w1, eps);
                w1 = nw1;
                w = 0.5 + (0.5 - w1);
            }
            _ => unreachable!(),
        }
        if ind != 0 {
            std::mem::swap(&mut w, &mut w1);
        }
        return (w, w1);
    }

    // procedure for a0 > 1 and b0 > 1
    let mut lambda_ = if a > b {
        (a + b) * y - b
    } else {
        a - (a + b) * x
    };
    if lambda_ < 0.0 {
        ind = 1;
        a0 = b;
        b0 = a;
        x0 = y;
        y0 = x;
        lambda_ = lambda_.abs();
    }
    let branch: &str;
    if b0 < 40.0 && b0 * x0 <= 0.7 {
        branch = "bpser";
    } else if b0 < 40.0 {
        branch = "bup_160";
    } else if a0 > b0 {
        if b0 <= 100.0 {
            branch = "bfrac";
        } else if lambda_ > 0.03 * b0 {
            branch = "bfrac";
        } else {
            branch = "basym";
        }
    } else if a0 <= 100.0 {
        branch = "bfrac";
    } else if lambda_ > 0.03 * a0 {
        branch = "bfrac";
    } else {
        branch = "basym";
    }

    match branch {
        "bpser" => {
            w = bratio_bpser(a0, b0, x0, eps);
            w1 = 0.5 + (0.5 - w);
        }
        "bfrac" => {
            w = bratio_bfrac(a0, b0, x0, y0, lambda_, 15.0 * eps);
            w1 = 0.5 + (0.5 - w);
        }
        "basym" => {
            w = bratio_basym(a0, b0, lambda_, 100.0 * eps);
            w1 = 0.5 + (0.5 - w);
        }
        "bup_160" => {
            let mut n = bratio_ftoi(b0);
            b0 -= n as f64;
            if b0 == 0.0 {
                n -= 1;
                b0 = 1.0;
            }
            w = bratio_bup(b0, a0, y0, x0, n, eps, true);
            if x0 <= 0.7 {
                w += bratio_bpser(a0, b0, x0, eps);
                w1 = 0.5 + (0.5 - w);
            } else {
                if a0 <= 15.0 {
                    let nn = 20;
                    w += bratio_bup(a0, b0, x0, y0, nn, eps, true);
                    a0 += nn as f64;
                }
                let (nw, _ie) = bratio_bgrat(a0, b0, x0, y0, w, eps);
                w = nw;
                w1 = 0.5 + (0.5 - w);
            }
        }
        _ => unreachable!(),
    }
    if ind != 0 {
        std::mem::swap(&mut w, &mut w1);
    }
    (w, w1)
}

ported/special_math_common::regularized_.text:
pub fn regularized_beta(x: f64, a: f64, b: f64) -> f64 {
    if !(0.0..=1.0).contains(&x) || !(a > 0.0) || !(b > 0.0) {
        return f64::NAN;
    }
    if x == 0.0 {
        return 0.0;
    }
    if x == 1.0 {
        return 1.0;
    }
    let y = 1.0 - x;
    bratio(a, b, x, y).0
}

