catalogue/distributions::chisq_test_of.text:
fn chisq_test_of(site: &Site<'_>, a: &[CalcValue], sv: &mut EvalServices<'_>) -> Step<CalcValue> {
    // Single-cell blanks and errors are checked in argument order before
    // comparing sample shapes or examining errors in multi-cell ranges.
    validate_paired_singletons(site, a, [0, 1], sv)?;
    let actual = grid(site, a, 0, sv)?;
    let expected = grid(site, a, 1, sv)?;
    if (actual.rows, actual.cols) != (expected.rows, expected.cols) {
        return fail(WorksheetErrorCode::NA);
    }
    let df = if actual.rows > 1 && actual.cols > 1 {
        (actual.rows - 1) * (actual.cols - 1)
    } else if actual.rows == 1 {
        actual.cols - 1
    } else {
        actual.rows - 1
    };
    if df == 0 {
        return fail(WorksheetErrorCode::NA);
    }
    let mut statistic = 0.0;
    for (x, e) in actual.cells.iter().zip(&expected.cells) {
        let (x, e) = match (x.core_ref(), e.core_ref()) {
            (CoreRef::Error(code), _) | (_, CoreRef::Error(code)) => return fail(code),
            (CoreRef::Number(x), CoreRef::Number(e)) => (x, e),
            _ => return fail(WorksheetErrorCode::Value),
        };
        if e <= 0.0 {
            return fail(WorksheetErrorCode::Num);
        }
        let delta = x - e;
        statistic += delta * delta / e;
    }
    out(site, cft::chisq_dist_rt_kernel(statistic, df as f64))
}

catalogue/kit::validate_paired_singleton.text:
/// Paired statistical functions validate single-cell arguments in formula order before
/// inspecting multi-cell samples. A referenced empty cell is VALUE, unlike an empty
/// element inside a larger range or an array.
pub(super) fn validate_paired_singletons(
    site: &Site<'_>,
    arguments: &[CalcValue],
    indices: [usize; 2],
    services: &mut EvalServices<'_>,
) -> Step<()> {
    for index in indices {
        let argument = &arguments[index];
        match argument.core_ref() {
            CoreRef::Reference(reference) => {
                let [area] = reference.areas() else { continue };
                if area.cell_count() != 1 { continue; }
                let cell = grid(site, arguments, index, services)?;
                match cell.cells[0].core_ref() {
                    CoreRef::Empty | CoreRef::Missing => return fail(WorksheetErrorCode::Value),
                    CoreRef::Error(code) => return fail(code),
                    _ => {}
                }
            }
            CoreRef::Error(code) => return fail(code),
            _ => {}
        }
    }
    Ok(())
}

