ported/chi_f_t_family::t_inv_2t_kernel.text:
pub fn t_inv_2t_kernel(probability: f64, deg_freedom: f64) -> Result<f64, WorksheetErrorCode> {
    let v = truncate_positive_integer(deg_freedom)?;
    if !probability.is_finite() || probability < 0.0 || probability >= 2.0 {
        return Err(WorksheetErrorCode::Num);
    }
    if probability == 1.0 {
        return Ok(0.0);
    }
    let (p, sign) = if probability > 1.0 {
        (2.0 - probability, -1.0)
    } else {
        (probability, 1.0)
    };
    if v == 1.0 {
        // Reflect before forming the Cauchy cotangent; the stored angular
        // argument at p>1 is not equivalent. Its zero pole is #DIV/0!.
        if p == 0.0 {
            return Err(WorksheetErrorCode::Div0);
        }
        if p == 0.5 {
            return Ok(sign);
        }
        let arg = std::f64::consts::PI * p / 2.0;
        return Ok(sign / crate::ported::tan::tan_kernel(arg));
    }
    if p == 0.0 {
        return Err(WorksheetErrorCode::Num);
    }
    // Excel 20527: the direct coordinate is used through p=0.9, the
    // complementary coordinate above it. The latter preserves tiny roots.
    let t = if p <= 0.9 {
        let z = crate::ported::beta_gamma_stats_family::beta_inv_kernel(p, v / 2.0, 0.5, 0.0, 1.0)?;
        (v * (1.0 / z - 1.0)).sqrt()
    } else {
        let y = crate::ported::beta_gamma_stats_family::beta_inv_kernel(
            1.0 - p,
            0.5,
            v / 2.0,
            0.0,
            1.0,
        )?;
        (v * y / (1.0 - y)).sqrt()
    };
    Ok(sign * t)
}

ported/confidence_test_family::confidenc.text:
pub fn confidence_t_kernel(
    alpha: f64,
    standard_dev: f64,
    size: f64,
) -> Result<f64, WorksheetErrorCode> {
    if !alpha.is_finite() || !standard_dev.is_finite() || !size.is_finite() {
        return Err(WorksheetErrorCode::Value);
    }
    let n = size.trunc();
    if !(0.0 < alpha && alpha < 1.0) || standard_dev <= 0.0 || n < 1.0 {
        return Err(WorksheetErrorCode::Num);
    }
    if n == 1.0 {
        return Err(WorksheetErrorCode::Div0);
    }
    // Excel 20527: scale first, then multiply the quantile (512/512
    // controls; multiplying the quantile first matched 330/512).
    use crate::ported::excel_numeric::{excel_sqrt_staged, excel_x87_div, excel_x87_mul};
    let scale = excel_x87_div(standard_dev, excel_sqrt_staged(n));
    Ok(excel_x87_mul(scale, t_inv_2t_kernel(alpha, n - 1.0)?))
}

ported/excel_numeric::tan_with.text:
/// The TAN chain: `FPREM1(x, FLDPI/2)`, `FPTAN`, and `-1/tan(r)` on odd quadrants.
fn tan_with<F: Fpu>(x: f64) -> f64 {
    let minus_one = ext_chs(&ext_one(), CW);
    let pi_half = F::scale(&ext_pi(), &minus_one, CW);
    let (r, q) = F::prem1_quo(&load(x), &pi_half, CW);
    let t = F::tan(&r, CW);
    let v = if q & 1 == 0 {
        t
    } else {
        ext_chs(&F::div(&ext_one(), &t, CW), CW)
    };
    F::store(&v, CW)
}

ported/excel_numeric::excel_tan.text:
/// Excel `TAN` — bit-exact on `x86_64` (W109 G4-01, 1020/1020): the TAN
/// π/2-quadrant chain — `FPREM1(x, FLDPI/2)`, `FPTAN` on the residue, and on
/// odd quadrants `-1/tan(r)` with the reciprocal taken in EXTENDED before the
/// single binary64 store.
pub(crate) fn excel_tan(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
