fn coupon_args(
    site: &Site<'_>,
    a: &[CalcValue],
    sv: &EvalServices<'_>,
) -> Step<(f64, f64, f64, Option<f64>)> {
    let (settlement, maturity) = (date_1900(site, a, 0, sv)?, date_1900(site, a, 1, sv)?);
    if let Err(code) = coupon::check_coupon_dates(settlement, maturity) {
        return fail(code);
    }
