/// PMT adds fv after this common stage; period parts retain the quotient.
fn discounted_balance(present_value: f64, future_value: f64, em: f64) -> f64 {
    excel_x87_div(excel_x87_add(present_value, future_value), em)
}

ported/financial_time_value_family::due_.text:
/// Beginning-payment coefficient, with each reciprocal and addition stored
/// from PC64. Shared by PMT and the period interest/principal finish.
fn due_coefficient(rate: f64) -> f64 {
    let reciprocal = excel_x87_recip(rate);
    if reciprocal.is_finite() {
        excel_x87_recip(excel_x87_add(1.0, reciprocal))
    } else {
        rate
    }
}

ported/financial_time_value_family::pmt.text:
/// PMT on the correctly-rounded numeric core (W108 Bead C).
///
/// PV-side stable discount form (the live-Excel search winner). Instead of the
/// FV `powi` factor + `(F-1)/r` term (catastrophically wrong on the PMT lane —
/// up to ~5.5e8 ULP), this reproduces Excel's own `exp`/`log1p`/`expm1` chain:
///
/// ```text
/// negL  = -(n * log1p(r))        // -n·ln(1+r)
/// invF  = exp(negL)              // (1+r)^-n   (no cancellation)
/// denom = -expm1(negL)           // 1 - (1+r)^-n  (stable; avoids 1 - tiny)
/// tf    = 1 + r·type
/// pmt   = -(pv + fv·invF) · r / (tf · denom)
/// ```
///
/// The transcendentals are the faithful (~0.5-ULP) deterministic core, matching
/// Excel's bespoke routine on ~99% of inputs. The residual is the tracked W108
/// floor (≤2-3 ULP open discrepancy), NOT an acceptance.
pub fn pmt(
    periodic_rate: f64,
    periods: f64,
    present_value: f64,
    future_value: f64,
    timing: PaymentTiming,
) -> Result<f64, FinancialError> {
    validate_finite(&[periodic_rate, periods, present_value, future_value])?;
    if periods == 0.0 {
        return Err(FinancialError::Num);
    }
    // W108 Bead C: the zero-rate special case is EXACT `r == 0.0`, matching Excel
    // and the live-search model — a merely-tiny rate (e.g. 1e-13) is NOT collapsed
    // to the linear branch (that was a ~3813-ULP miss); it flows through the
    // stable discount form (1-ULP on PMT-0025).
    if periodic_rate == 0.0 {
        return Ok(-(future_value + present_value) / periods);
    }
    // Growth-domain guard: (1+r) <= 0 has no real (1+r)^-n — #NUM!, matching the
    // prior `growth` guard and live Excel.
    if 1.0 + periodic_rate <= 0.0 {
        return Err(FinancialError::Num);
    }
    // R31 adjacent-rate calls: beginning payments reject the pole in the
    // stored-PC64 reciprocal coefficient, even when balances cancel. End
    // payments at the same rate retain their ordinary discount domain.
    if matches!(timing, PaymentTiming::BeginningOfPeriod)
        && excel_x87_add(1.0, excel_x87_recip(periodic_rate)) == 0.0
    {
        return Err(FinancialError::Num);
    }
    // W109 G6-01 (2026-07-23, multi-agent workflow): the transcendental substrate is
    // the x87 chain (Excel's PMT `exp` is the x87 exponential `excel_exp`, matched 234/234; `expm1` is the internal
    // x87 double-rounded Kahan), and the combine is the live-Excel-pinned **quotient-first,
    // ·rate LAST** graph for end payments. R30 separately identifies the positive-rate
    // discount/type-one coefficient and its stores below; other routes keep the timing division.
    //
    // dc-j9k.12: the logarithm is not a correctly rounded log1p but the atanh series of
    // `excel_log1p_atanh`. Holding pv varied at fixed (rate, nper) pins Excel's binary64 em in
    // 4,720 recorded groups (fv 0, type 0, rate > 0). For each of the 1,184 rates among them
    // one binary64 L reproduces em = expm1(-(nper * L)) through the x87 Kahan expm1 below at
    // every nper; the series gives that L for 1,181 rates, a correctly rounded log1p for 667.
    // The series was used where its twelve terms have converged (-1/3 <= rate <= 1/2, so
    // |s| <= 1/5); outside that range Excel's logarithm was not identified and the
    // correctly rounded one stayed. The range is Morris's alnrel bound instead, as in
    // `excel_log1p_times`: one rate at 0.419 held 128 rows, all cleared by LN of the stored 1 + r.
    let log_growth = alnrel(periodic_rate);
    let neg_log = -(periods * log_growth);
    let em = crate::ported::excel_numeric::excel_expm1_spilled(neg_log); // (1+r)^-n − 1  (x87 Kahan; negative for r>0)
    // Preserve the growth-reciprocal overflow refusal before the balance
    // fold can turn pv/Inf + fv into a finite payment. R31 paired parts keep
    // first-period beginning IPMT zero ahead of this shared PMT check.
    if em == 0.0 || !em.is_finite() {
        return Err(FinancialError::Num);
    }
    let tf = timing.factor(periodic_rate); // 1 + r·type
    // Equal opposite balances are interest only: pv + fv*v = fv*(v - 1).
    // Cancelling that common factor before rounding avoids subtracting nearly
    // equal balances. Negative rates use the common stored fold below: its
    // quotient is exactly fv here, retaining their measured final stores.
    if periodic_rate > 0.0 && present_value != 0.0 && future_value == -present_value {
        let product = future_value * periodic_rate;
        let result = if product.is_finite() {
            // Beginning payments are fv / stored(1 + stored(1 / rate)), the reciprocal coefficient
            // of the pole check above: 20 of the 21 rows that missed by a unit here.
            match timing {
                PaymentTiming::EndOfPeriod => excel_x87_mul(future_value, periodic_rate),
                PaymentTiming::BeginningOfPeriod => excel_x87_div(
                    future_value,
                    excel_x87_add(1.0, excel_x87_recip(periodic_rate)),
                ),
            }
        } else {
            let scaled = (future_value / tf) * periodic_rate;
            if scaled.is_finite() {
                scaled
            } else {
                // With beginning payments and a positive rate, rate/tf <= 1.
                // This order cannot overflow a finite balance. The previous
                // order can round MAX/tf upward and overflow its final product.
                future_value * (periodic_rate / tf)
            }
        };
        return if result.is_finite() {
            Ok(result)
        } else {
            Err(FinancialError::Num)
        };
    }
    // Both arms store the quotient from PC64 (dc-j9k.12). With pv varied at fixed (rate, nper),
    // fv 0 and type 0, q = RN53(RN64(pv / em)) followed by RN53(RN64(q * rate)) admits one
    // binary64 em in every one of 4,802 recorded groups; a binary64 quotient leaves 59 groups
    // with no em at all.
    let quotient = if neg_log < 0.0 || periodic_rate < 0.0 {
        // dc-j9k.12, R29/R31: the discount and negative-rate arms combine balances as
        // (pv + fv)/em + fv, with both additions and the division stored
        // from PC64. Public type-zero calls constrain em independently:
        // this fold matches all192 paired future-value calls for each rate sign.
        // Separate negative-rate ties distinguish each addition (84 and114 readings).
        // Forming pv + fv*(1+em) loses those recorded roundings.
        excel_x87_add(
            discounted_balance(present_value, future_value, em),
            future_value,
        )
    } else {
        let inv_factor = 1.0 + em;
        let numerator = present_value + future_value * inv_factor;
        excel_x87_div(numerator, em)
    };
    let result = if (neg_log < 0.0 || periodic_rate < 0.0)
        && matches!(timing, PaymentTiming::BeginningOfPeriod)
    {
        // R30/R31: paired type-zero calls pin em independently of timing. The
        // discount and negative-rate arms multiply by 1/(1+1/r), storing each
        // operation from PC64. Negative-rate calls also pin this coefficient
        // under either final-word model before 44 fresh product ties distinguish
        // the PC64 store. Dividing by (1+r) loses those recorded roundings.
        // If its reciprocal overflows, r is subnormal and the coefficient
        // rounds to r because r*r is below half a subnormal unit.
        let factor = due_coefficient(periodic_rate);
        excel_x87_mul(quotient, factor)
    } else {
        let quotient = excel_x87_div(quotient, tf);
        // R31: 32 independently measured negative-rate product ties require
        // the PC64-to-binary64 store after the already stored quotient.
        // Their denominators are pinned by separate public type-zero calls.
        if neg_log < 0.0 || periodic_rate < 0.0 {
            excel_x87_mul(quotient, periodic_rate)
        } else {
            quotient * periodic_rate
        }
    };
    if result.is_finite() {
        Ok(result)
    } else {
        Err(FinancialError::Num)
    }
}

ported/financial_time_value_family::rate.text:
pub fn rate(
    periods: f64,
    payment_value: f64,
    present_value: f64,
    future_value: f64,
    timing: PaymentTiming,
    guess: Option<f64>,
) -> Result<f64, FinancialError> {
    let guess = guess.unwrap_or(0.1);
    // The initial guess has its own domain error. Preserve the numeric API's
    // existing NUM result for nonfinite values, which cannot be worksheet inputs.
    if guess.is_finite() && guess <= -1.0 {
        return Err(FinancialError::Value);
    }
    let result = rate_secant(
        periods,
        payment_value,
        present_value,
        future_value,
        timing,
        guess,
    )?;
    // This is a result rule, not an evaluation-domain bound: Excel accepts
    // near-minus-one starting guesses that lead to an ordinary root. Adjacent
    // exact-root probes locate the final boundary at the solver's tolerance.
    if excel_x87_add(1.0, result) < RATE_TOLERANCE {
        Err(FinancialError::Num)
    } else {
        Ok(result)
    }
}

/// RATE's search as IRR's (`irr_discount_secant`), in the rate itself: the secant from the guess and
/// a second point 0.001 away, against the sign of the balance at the guess. Over guesses a distance
/// `d` from the root the error is `K d` with `K / C^2 = 1.00e-6`, `C` being `f''/2f'` in the rate.
/// The balance is FV's, every step stored.
///
/// It stops when the rate moved by less than 1e-7 and the balance at the new rate is under 1e-7 as
/// well, both at once. With a mortgage's slope the balance is the one that runs on to full
/// convergence, where the small slope of RATE(10,-120,1000) leaves the error at the step's size:
/// a guess 2.4e-7 off stops, a guess 4.8e-7 off takes one step more.
///
/// 200 steps, from a live window: RATE(360,-599.55,100000,0,0,g) answers up to g = 0.455, the
/// 200th step, and is #NUM! from g = 0.46, the 201st. After the budget, a separate
/// 1e-4 step/balance/result check can accept the last iterate. Intermediate powers
/// retain their own domain, including negative bases with integer exponents.
fn rate_secant(
    periods: f64,
    payment_value: f64,
    present_value: f64,
    future_value: f64,
    timing: PaymentTiming,
    guess: f64,
) -> Result<f64, FinancialError> {
    let balance = |rate: f64| -> Result<f64, FinancialError> {
        if rate == 0.0 {
            return Ok(excel_x87_add(
                excel_x87_add(future_value, present_value),
                excel_underflow_to_zero(excel_x87_mul(payment_value, periods)),
            ));
        }
        let base = excel_x87_add(1.0, rate);
        // The initial guess and final root have separate domain rules. An
        // intermediate integer-period power can cross a negative base.
        let factor = growth_from_base(base, periods)?;
        let term = excel_x87_mul(
            excel_x87_div(excel_x87_sub(factor, 1.0), rate),
            timing.factor(rate),
        );
        Ok(excel_x87_add(
            payment_balance(present_value, payment_value, factor, term),
            future_value,
        ))
    };
    let mut before = guess;
    let mut value_before = balance(before)?;
    // A zero balance still needs a nonzero secant slope; a flat zero
    // objective is NUM. The comparison sends either sign of zero upward.
    let offset = if value_before > 0.0 { -0.001 } else { 0.001 };
    let mut current = excel_x87_add(before, offset);
    let mut value = balance(current)?;
    let mut step = f64::INFINITY;
    for _ in 0..200 {
        let change = excel_x87_sub(value, value_before);
        if change == 0.0 {
            // A balance that does not move between two rates has no secant step: #NUM!, as in
            // IRR's search (Excel 16.0.20527, dcztvv_r23: RATE(0,-100,1000,0,0,0.5),
            // RATE(2^-1022,-100,1000,0,0,0.5) and RATE(FALSE,-200,8000) are #NUM!).
            return Err(FinancialError::Num);
        }
        // The slope comparison precedes the division's DAZ input stage:
        // an exactly flat objective is NUM, a subnormal divisor is DIV/0.
        let divisor = financial_daz(change);
        if divisor == 0.0 {
            return Err(FinancialError::Div0);
        }
        let numerator = excel_underflow_to_zero(excel_x87_mul(value, excel_x87_sub(current, before)));
        let next = excel_x87_sub(current, excel_x87_div(numerator, divisor));
        step = excel_x87_sub(next, current).abs();
        (before, value_before) = (current, value);
        current = next;
        value = balance(current)?;
        if step < RATE_TOLERANCE && value.abs() < RATE_TOLERANCE {
            return Ok(current);
        }
    }
    // Excel has a separate final check after the iteration budget. Adjacent-word
    // public calls locate its step, balance and near-minus-one boundaries.
    // Keep this outside the strict convergence loop: using 1e-4 there changes
    // ordinary loan answers and accepting every final iterate admits failures.
    if step <= RATE_FINAL_TOLERANCE
        && value.abs() <= RATE_FINAL_TOLERANCE
        && excel_x87_add(1.0, current) >= RATE_FINAL_TOLERANCE
    {
        Ok(current)
    } else {
        Err(FinancialError::Num)
    }
}

ported/financial_time_value_family::end_.text:
/// The stored balance quotient before PMT adds the future value. Retaining
/// h=(pv+fv)/em avoids cancelling that future value again in each period's
/// interest and principal. Negative-rate end/beginning calls use the same
/// stored quotient; its subnormal store flushes before the large discount.
fn end_payment_quotient(
    periodic_rate: f64,
    periods: f64,
    present_value: f64,
    future_value: f64,
) -> Option<(f64, f64)> {
    if !periodic_rate.is_finite() || periodic_rate == 0.0 {
        return None;
    }
    let log_growth = alnrel(periodic_rate);
    let em = crate::ported::excel_numeric::excel_expm1_spilled(-(periods * log_growth));
    if em == 0.0 || !em.is_finite() {
        return None;
    }
    let quotient = excel_underflow_to_zero(discounted_balance(present_value, future_value, em));
    quotient.is_finite().then_some((log_growth, quotient))
}

ported/financial_time_value_family::peri.text:
/// Stored interest and principal components before their final timing factor.
fn period_components(
    period_index: f64,
    periods: f64,
    future_value: f64,
    log_growth: f64,
    quotient: f64,
) -> (f64, f64) {
    let t = -((periods - period_index + 1.0) * log_growth);
    let em = crate::ported::excel_numeric::excel_expm1_spilled(t);
    let u = crate::ported::excel_numeric::excel_exp(t);
    // Retain h before adding fv. Forming (h+fv)*em-fv*u instead loses
    // the entire interest when the two stored products cancel.
    (
        -excel_x87_sub(excel_x87_mul(quotient, em), future_value),
        excel_x87_mul(quotient, u),
    )
}

ported/financial_time_value_family::end_.text:
fn end_payment_parts(
    periodic_rate: f64,
    period_index: f64,
    periods: f64,
    future_value: f64,
    log_growth: f64,
    quotient: f64,
    timing: PaymentTiming,
) -> (f64, f64) {
    let (interest, principal) = period_components(
        period_index,
        periods,
        future_value,
        log_growth,
        quotient,
    );
    let factor = if matches!(timing, PaymentTiming::BeginningOfPeriod) {
        due_coefficient(periodic_rate)
    } else {
        periodic_rate
    };
    (
        excel_x87_mul(interest, factor),
        excel_x87_mul(principal, factor),
    )
}

ported/financial_time_value_family::ipmt.text:
/// IPMT on the correctly-rounded numeric core (W108 Bead C). Interest portion of
/// payment `period_index`: the remaining balance entering the period times `r`,
/// reconstructed from the core PMT and the `fv_exp` balance recurrence.
pub fn ipmt(
    periodic_rate: f64,
    period_index: f64,
    periods: f64,
    present_value: f64,
    future_value: f64,
    timing: PaymentTiming,
) -> Result<f64, FinancialError> {
    validate_finite(&[
        periodic_rate,
        period_index,
        periods,
        present_value,
        future_value,
    ])?;
    // Excel checks the stored zero-based index. A fractional last period
    // remains admitted until per-1 reaches nper; it is not per<=nper.
    if period_index < 1.0 || period_index - 1.0 >= periods {
        return Err(FinancialError::Num);
    }
    // R31 public IPMT calls return zero here even at rate -1 and below.
    // This precedes PMT's rate and reciprocal-pole checks, but follows the
    // finite-argument and period-range checks.
    if period_index == 1.0 && matches!(timing, PaymentTiming::BeginningOfPeriod) {
        return Ok(0.0);
    }
    // W109 G6-01 (2026-07-23): EXACT zero-rate special case (mirrors PMT's W108 Bead C),
    // NOT an `abs() < EPSILON` band. Live-Excel: IPMT(0,per,..)=+0.0, but a merely-tiny rate
    // (e.g. ±1e-13) flows through the MAIN path (IPMT(1e-13,1,360,2e5)=−2e-8, IPMT(−1e-13,..)=
    // +2e-8) — the old band wrongly collapsed tiny/negative rates to 0.0 and dropped the sign.
    if periodic_rate == 0.0 {
        return Ok(0.0);
    }
    if 1.0 + periodic_rate <= 0.0 {
        return Err(FinancialError::Num);
    }
    let periodic_payment = pmt(periodic_rate, periods, present_value, future_value, timing)?;
    // dc-j9k.12: payments at the end of a period take Excel's own pieces. On the catalogue
    // oracle and bank rows with fv 0 (95 of 95) the interest is -RN(RN(q * em_m) * rate).
    if let Some((log_growth, quotient)) =
        end_payment_quotient(periodic_rate, periods, present_value, future_value)
    {
        let (interest, _) = end_payment_parts(
            periodic_rate,
            period_index,
            periods,
            future_value,
            log_growth,
            quotient,
            timing,
        );
        return if interest.is_finite() {
            Ok(interest)
        } else {
            Err(FinancialError::Num)
        };
    }
    let tf = timing.factor(periodic_rate); // 1 + r·type
    let type_is_beginning = matches!(timing, PaymentTiming::BeginningOfPeriod);
    // Remaining balance entering `period_index` (the `rip` term); interest = rip·r. Excel
    // computes it backward from the end of the annuity (dc-j9k): the balance B after
    // `period_index - 1` periods is the one that `m = periods - period_index + 1` more periods
    // take to -fv, B = -fv·v^m + pmt·(1 + r·type)·(v^m - 1)/r with v = 1/(1 + r), so late
    // periods of a long, high-rate annuity do not lose the balance to cancellation. Against
    // the catalogue oracle's IPMT and PPMT readings, the forward recurrence missed by up to
    // 0.6 in absolute terms (PPMT(0.1713,191,264,-8172.57) was -0.588 where Excel gives
    // 0.0116); the backward form is within a few ulp of Excel on every reading.
    let rip = if period_index <= 1.0 {
        if type_is_beginning {
            0.0
        } else {
            -present_value
        }
    } else {
        let remaining = periods - period_index + 1.0;
        let log_discount = -(remaining * alnrel(periodic_rate));
        let discount = exp_portable(log_discount); // v^m
        let discount_m1 = excel_expm1(log_discount); // v^m - 1
        let balance =
            -future_value * discount + periodic_payment * tf * (discount_m1 / periodic_rate);
        if type_is_beginning {
            -balance / (1.0 + periodic_rate)
        } else {
            -balance
        }
    };
    let result = rip * periodic_rate;
    if result.is_finite() {
        Ok(result)
    } else {
        Err(FinancialError::Num)
    }
}

ported/financial_time_value_family::ppmt.text:
pub fn ppmt(
    periodic_rate: f64,
    period_index: f64,
    periods: f64,
    present_value: f64,
    future_value: f64,
    timing: PaymentTiming,
) -> Result<f64, FinancialError> {
    let payment = pmt(periodic_rate, periods, present_value, future_value, timing)?;
    // IPMT's checks (period range, rate) and its zero-rate case apply to PPMT too.
    let interest = ipmt(
        periodic_rate,
        period_index,
        periods,
        present_value,
        future_value,
        timing,
    )?;
    if periodic_rate == 0.0
        || (period_index <= 1.0 && matches!(timing, PaymentTiming::BeginningOfPeriod))
    {
        return Ok(payment - interest);
    }
    // dc-j9k.12: payments at the end of a period take Excel's own pieces: the principal is
    // RN(RN(RN(q - fv) * u) * rate) with u = exp(-(m * L)), not a payment less interest.
    // Catalogue oracle, bank and fresh Excel rows: 138 of 138 with fv 0, 25 of 27 with fv.
    // For positive beginning payments the same stored component takes the
    // reciprocal coefficient already shared by PMT/IPMT. R35's576 independent
    // end/beginning pairs distinguish that finish; all1152 fresh public calls match.
    if let Some((log_growth, quotient)) =
        end_payment_quotient(periodic_rate, periods, present_value, future_value)
    {
        let (_, principal) = end_payment_parts(
            periodic_rate,
            period_index,
            periods,
            future_value,
            log_growth,
            quotient,
            timing,
        );
        return if principal.is_finite() {
            Ok(principal)
        } else {
            Err(FinancialError::Num)
        };
    }
    // Excel does not subtract the interest from the payment, which cancels when the interest
    // is nearly the whole payment (dc-j9k: PPMT(0.1809,1,375,57755.66,635.76) is -8.79e-24 in
    // Excel, and payment - interest gave noise of order 1e-12). The principal is the payment
    // net of the future value's interest, discounted over the m = periods - period_index + 1
    // periods left: v^m * (pmt - fv*r), and v^m * (pmt - fv*r/(1 + r)) for payments at the
    // start of a period. The catalogue oracle's PPMT readings hold it.
    let result = discounted_payment_principal(
        periodic_rate,
        period_index,
        periods,
        payment,
        future_value,
        timing,
    );
    if result.is_finite() {
        Ok(result)
    } else {
        Err(FinancialError::Num)
    }
}

ported/financial_time_value_family::cumu.text:
/// The principal change across a whole-period span (dc-j9k.49). With PMT's stored
/// quotient q = PV/EXPM1(-nL), the common beginning-payment core is
/// q * (EXP(-(n-end+1)L) * -EXPM1(-count*L)), with both products stored from PC64.
/// The EXPM1 span preserves small principal amounts without subtracting balances.
/// Ending payments then multiply the stored core by stored 1+rate: all 160
/// recorded timing pairs agree, including the addition double-rounding cases.
/// Beginning payments add their whole first payment after the span from period 2.
/// None preserves the caller's existing fallback outside PMT's quotient domain.
pub(crate) fn cumulative_principal(
    periodic_rate: f64,
    periods: f64,
    present_value: f64,
    start_period: i32,
    end_period: i32,
    timing: PaymentTiming,
) -> Option<f64> {
    if !(periodic_rate > 0.0) || start_period > end_period || start_period < 1 {
        return None;
    }
    let (log_growth, quotient) = end_payment_quotient(periodic_rate, periods, present_value, 0.0)?;
    let beginning = matches!(timing, PaymentTiming::BeginningOfPeriod);
    let first = if beginning { start_period.max(2) } else { start_period };
    let mut total = 0.0;
    if end_period >= first {
        let last = periods - f64::from(end_period) + 1.0;
        let discount = crate::ported::excel_numeric::excel_exp(-(last * log_growth));
        let count = f64::from(end_period - first + 1);
        let span = -crate::ported::excel_numeric::excel_expm1_spilled(-(count * log_growth));
        total = excel_x87_mul(quotient, excel_x87_mul(discount, span));
        if !beginning {
            total = excel_x87_mul(total, excel_x87_add(1.0, periodic_rate));
        }
    }
    if beginning && start_period == 1 {
        total = excel_x87_add(total, excel_x87_mul(quotient, due_coefficient(periodic_rate)));
    }
    total.is_finite().then_some(total)
}

ported/financial_time_value_family::disc.text:
/// The discounted-payment principal expression. The cumulative beginning-payment
/// fallback still uses it: its singletons differ from public PPMT, whose measured
/// positive-rate finish uses the shared period component above. Keep this earlier
/// expression outside the shared quotient domain.
pub(crate) fn discounted_payment_principal(
    periodic_rate: f64,
    period_index: f64,
    periods: f64,
    payment: f64,
    future_value: f64,
    timing: PaymentTiming,
) -> f64 {
    let remaining = periods - period_index + 1.0;
    let discount = exp_portable(-(remaining * excel_log1p(periodic_rate)));
    let carried = if matches!(timing, PaymentTiming::BeginningOfPeriod) {
        future_value * periodic_rate / (1.0 + periodic_rate)
    } else {
        future_value * periodic_rate
    };
    discount * (payment - carried)
}

ported/power_fn::exact_integer_magnitude.text:
fn exact_integer_magnitude(power: f64) -> Option<u32> {
    if !power.is_finite() {
        return None;
    }
    let magnitude = power.abs();
    // W111 width controls distinguish the unsigned32 sentinel itself from
    // its predecessor. Out-of-range integers use the noninteger body below.
    if magnitude.fract() != 0.0 || magnitude >= u32::MAX as f64 {
        None
    } else {
        Some(magnitude as u32)
    }
}

ported/power_fn::accept_negative_base_od.text:
/// Excel's real-root acceptance for a negative base with a fractional exponent.
/// Excel accepts `POWER(x<0, y)` only when `1/y`, rounded to **15 significant
/// decimal digits**, is an odd integer within signed `int32`; the result is then
/// `-POWER(|x|, y)`, evaluated at the ORIGINAL `y`. (Round-1 live-Excel finding:
/// the acceptance band around `n=101` is exactly 100x the band around `n=3` — a
/// decimal signature no binary tolerance reproduces. BUG-FUNC-042 / W108.)
fn accept_negative_base_odd_root(power: f64) -> bool {
    // 15 significant decimal digits == 14 after the point in scientific form,
    // matching Excel's `%.14e` fuzz on 1/y.
    let n: f64 = match format!("{:.14e}", 1.0 / power).parse() {
        Ok(v) => v,
        Err(_) => return false,
    };
    n.fract() == 0.0 && (-2_147_483_648.0..=2_147_483_647.0).contains(&n) && (n as i64) % 2 != 0
}

ported/power_fn::binexp_positive.text:
/// LSB-first (right-to-left) square-and-multiply `base^n` for `n >= 0`, with
/// staged products followed by binary64 stores (W111 numerical observations,
/// distinct from `powf`). Returns the POSITIVE power; the caller reciprocates.
pub(crate) fn binexp_positive(base: f64, mut n: u64) -> f64 {
    let mut acc = 1.0;
    let mut b = base;
    while n > 0 {
        if n & 1 == 1 {
            acc = crate::ported::excel_numeric::excel_x87_mul(acc, b);
        }
        n >>= 1;
        if n > 0 {
            b = crate::ported::excel_numeric::excel_x87_mul(b, b);
        }
    }
    acc
}

ported/power_fn::ten_to.text:
/// 10 to the integer `scale`, from -308 to 308, as Excel's decimal power publishes it: 1E+scale
/// rounded to a 64-bit significand (the x87 unit's precision control) and then to binary64, which
/// is the nearest binary64 except where that double rounding lands a unit in the last place away:
/// 1E+126 is 0x5A17A2ECC414A040, not ...A03F. Excel 16.0.20527 through the question service,
/// POWER(10, k) and PERMUTATIONA(10, k) for every k from 0 to 308: 126 is the only difference from
/// the nearest value, the same discriminator as ROUNDUP's power-of-ten unit (jnt_w111_rounding row
/// 5910 holds it for PERMUTATIONA).
pub(crate) fn ten_to(scale: i32) -> f64 {
    crate::decimal::ExactDecimal::unit(scale)
        .rounded_pc64()
        .text()
        .parse()
        .unwrap_or(f64::INFINITY)
}

ported/power_fn::power_kernel.text:
/// `POWER(x, y)` candidate graph (the `^` operator shares this kernel).
/// Extends the black-box BUG-FUNC-042 / W108 graph with W111 integer-power
/// observations: positive base ten has a decimal-scale branch; other integer
/// exponents use staged binary exponentiation. Fractional exponents use
/// → `exp(y·ln x)` via the x87 backend with the `y<0` reciprocal staging (positive
/// power stored to `binary64`, then one x87 double-rounded reciprocal) that
/// resolved the earlier 1-ULP residual — `exp(y·ln x)` was the right function
/// evaluated at the wrong point for `y < 0`.
pub fn power_kernel(number: f64, power: f64) -> Result<f64, WorksheetErrorCode> {
    // 1. zero exponent
    if power == 0.0 {
        return if number == 0.0 {
            Err(WorksheetErrorCode::Num) // POWER(0, 0)
        } else {
            Ok(1.0)
        };
    }
    // 2. zero base
    if number == 0.0 {
        return if power < 0.0 {
            Err(WorksheetErrorCode::Div0) // POWER(0, negative)
        } else {
            Ok(0.0)
        };
    }

    // 3. integer exponent → binary-exponentiation publication. This is the
    // declared precision quirk on `POWER_META`, also used by `^`. Consumers
    // retain their separately assessed call-site graphs. Dispatch is EXACT —
    // `POWER(2, 3+ulp)` takes the fractional
    // path. The positive power is formed by `binexp`, reciprocated for `y<0`.
    // POWER_META declares PrecisionRoundingProfile::IntegerExponentPublication.
    let integer_publication = true;
    if let Some(magnitude) = exact_integer_magnitude(power).filter(|_| integer_publication) {
        // This branch is specific to positive ten; negative ten retains the
        // ordinary repeated-product graph and differs at many large powers.
        let mut p = if number == 10.0 {
            // The observed decimal scale wraps through signed32 inside the
            // admitted unsigned32 magnitude. E.g. 2^32-2 selects scale -2.
            let scale = magnitude as i32;
            if scale > 308 {
                f64::INFINITY
            } else if scale < -308 {
                0.0
            } else {
                ten_to(scale)
            }
        } else {
            binexp_positive(number, u64::from(magnitude))
        };
        if power < 0.0 {
            if p.abs() < f64::MIN_POSITIVE {
                return Err(WorksheetErrorCode::Div0); // reciprocal sees tiny magnitude as zero
            }
            p = excel_x87_recip(p); // 1/inf -> 0, published below
        }
        if p.is_nan() || p.is_infinite() {
            return Err(WorksheetErrorCode::Num);
        }
        // Integer path flushes subnormal / -0 / 0 to +0 (Excel: POWER(2,-1023)=0).
        return Ok(if p.abs() < f64::MIN_POSITIVE { 0.0 } else { p });
    }

    // 4. fractional exponent.
    let mut sign = 1.0;
    let mut base = number;
    if number < 0.0 {
        if !accept_negative_base_odd_root(power) {
            return Err(WorksheetErrorCode::Num); // no real root
        }
        sign = -1.0;
        base = -number; // continue with |x|
    }

    // p = exp_x87( RN53(RN64( |y| * ln_x87(base) )) ) — the positive power.
    let p = excel_pow_positive(base, power.abs());

    if power > 0.0 {
        if p.is_infinite() {
            return Err(WorksheetErrorCode::Num); // overflow
        }
        if p == 0.0 {
            return Ok(0.0);
        }
        return Ok(sign * p); // subnormals ARE published on the y>0 path
    }

    // y < 0: reciprocal staging (the resolved 1-ULP puzzle).
    if p < f64::MIN_POSITIVE {
        return Err(WorksheetErrorCode::Div0); // subnormal/zero positive power (DAZ-style)
    }
    if p.is_infinite() {
        return Ok(0.0); // 1 / inf
    }
    let r = excel_x87_recip(p); // RN53(RN64(1/p))
    if r < f64::MIN_POSITIVE {
        return Ok(0.0); // subnormal quotient flushes to +0
    }
    if r.is_infinite() {
        return Err(WorksheetErrorCode::Num);
    }
    Ok(sign * r)
}

ported/real_policy::excel_underflow_to_z.text:
pub(crate) fn excel_underflow_to_zero(value: f64) -> f64 {
