fn rank(
    site: &Site<'_>,
    a: &[CalcValue],
    sv: &mut EvalServices<'_>,
    average: bool,
) -> Step<CalcValue> {
    let number = rank_number(a)?;
    let values = list(site, a, 1, sv)?;
    let order = if given(a, 2) && num(site, a, 2)?.trunc() != 0.0 {
        RankOrder::Ascending
    } else {
        RankOrder::Descending
    };
    let r = if average {
        rank_avg(number, &values, order)
    } else {
        rank_eq(number, &values, order)
    };
    out(site, r)
}

ported/rank_common::rank_eq.text:
pub fn rank_eq(number: f64, values: &[f64], order: RankOrder) -> Result<f64, WorksheetErrorCode> {
    if values.is_empty() {
        return Err(WorksheetErrorCode::NA);
    }
    let matches = values.iter().filter(|value| **value == number).count();
    if matches == 0 {
        return Err(WorksheetErrorCode::NA);
    }

    let rank = match order {
        RankOrder::Descending => values.iter().filter(|value| **value > number).count() + 1,
        RankOrder::Ascending => values.iter().filter(|value| **value < number).count() + 1,
    };
    Ok(rank as f64)
}

