ported/text_kernels::mid_start.text:
/// MID's one-based start. Excel reads a start up to 2147483648.9999995 (truncated, at most 2^31),
/// one beyond the signed 32-bit bound the count has, and gives #VALUE! from 2147483649.0 (bisected
/// on Excel 16.0.20527 through the question service; the jnt_w111_text_dates rows hold 2147483648.5
/// as empty text and 4294967294.5 as #VALUE!).
pub(crate) fn mid_start(n: f64) -> Result<usize, WorksheetErrorCode> {
    if !n.is_finite() || n >= 2147483649.0 {
        return Err(WorksheetErrorCode::Value);
    }
    let truncated = n.trunc();
    if truncated < 1.0 {
        return Err(WorksheetErrorCode::Value);
    }
    Ok(truncated as usize)
}

ported/text_kernels::take_mid.text:
/// MID counts valid surrogate pairs once in Version 2; MIDB keeps its UTF-16 unit policy.
pub(crate) fn take_mid(
    text: &ExcelText,
    start_one_based: usize,
    count: usize,
    pairs: bool,
) -> ExcelText {
    let units = text.utf16_code_units();
    let first = start_one_based.saturating_sub(1);
    let start = if pairs {
        character_boundary(text, first)
    } else {
        first
    };
    if count == 0 || start >= units.len() {
        return ExcelText::from_utf16_code_units(Vec::new());
    }
    let end = if pairs {
        character_boundary(text, first.saturating_add(count))
    } else {
        start.saturating_add(count).min(units.len())
    };
    ExcelText::from_utf16_code_units(units[start..end].to_vec())
}

