pub fn factorial_of_int(n: i64) -> f64 {
    if n <= 1 {
        return 1.0;
    }
    (2..=n).fold(1.0, |acc, item| acc * item as f64)
}

ported/multinomial::next_down.text:
fn next_down(x: f64) -> f64 {
    if x.is_nan() || x == f64::NEG_INFINITY {
        x
    } else if x == 0.0 {
        -f64::from_bits(1)
    } else if x > 0.0 {
        f64::from_bits(x.to_bits() - 1)
    } else {
        f64::from_bits(x.to_bits() + 1)
    }
}

ported/multinomial::step_down.text:
fn step_down(mut x: f64, steps: u64) -> f64 {
    for _ in 0..steps {
        x = next_down(x);
    }
    x
}

