fn positive_items_are_consecutive(positive_items: &[i64]) -> bool {
    if positive_items.len() < 2 {
        return false;
    }
    let mut sorted = positive_items.to_vec();
    sorted.sort_unstable();
    sorted.windows(2).all(|window| window[1] == window[0] + 1)
}

