fn multinomial_exact_candidate(positive_items: &[i64]) -> f64 {
    let total = positive_items.iter().sum::<i64>();
    let denominator = positive_items
        .iter()
        .fold(1.0, |acc, item| acc * factorial_of_int(*item));
    factorial_of_int(total) / denominator
}

