catalogue/offset::offset.text:
fn offset(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    // dc-ylr: Excel gives OFFSET of a reference to a closed workbook #VALUE!.
    let external = arguments[0].as_reference().is_some_and(|reference| {
        reference.areas().iter().any(|area| {
            services
                .host()
                .is_some_and(|host| host.is_external_sheet(area.sheet()))
        })
    });
    let site = Site::new(OFFSET, services);
    if external {
        return Site::finish(Err(Exit::Error(WorksheetErrorCode::Value)));
    }
    Site::finish(shifted(&site, arguments))
}

catalogue/offset::shifted.text:
fn shifted(site: &Site<'_>, arguments: &[CalcValue]) -> Step<CalcValue> {
    site.scalar_operands(arguments)?;
    let Some(reference) = arguments[0].as_reference() else {
        return Err(Exit::Error(WorksheetErrorCode::Value));
    };
    let [base] = reference.areas() else {
        return Err(Exit::Error(WorksheetErrorCode::Value));
    };
    let rows = whole(site, 1, &arguments[1])?;
    let cols = whole(site, 2, &arguments[2])?;
    let height = extent(site, 3, arguments.get(3), base.row_count())?;
    let width = extent(site, 4, arguments.get(4), base.column_count())?;
    let top = i64::from(base.first().row()) + rows;
    let left = i64::from(base.first().column()) + cols;
    let (top, bottom) = span(top, height);
    let (left, right) = span(left, width);
    let on_grid = |low: i64, high: i64, max: u32| low >= 1 && high <= i64::from(max);
    if !on_grid(top, bottom, MAX_ROWS) || !on_grid(left, right, MAX_COLUMNS) {
        return Err(Exit::Error(WorksheetErrorCode::Ref));
    }
    let sheet = base.sheet();
    let corner = |row: i64, column: i64| {
        CellKey::new(sheet, row as u32, column as u32).expect("checked on the grid")
    };
    let area = GridArea::new(corner(top, left), corner(bottom, right))
        .expect("both corners lie on one sheet");
    Ok(CalcValue::reference(ReferenceLike::area(area)))
}

catalogue/offset::whole.text:
/// Argument `index` read as a number and truncated toward zero; a value beyond any grid offset
/// is kept large enough to leave the grid.
fn whole(site: &Site<'_>, index: usize, value: &CalcValue) -> Step<i64> {
    let n = site.number_argument(index, value)?.trunc();
    Ok(n.clamp(-4_000_000.0, 4_000_000.0) as i64)
}

catalogue/offset::extent.text:
/// The height or width argument `index`, truncated: the reference's own `own` when it is not
/// given, #REF! when it is 0.
fn extent(site: &Site<'_>, index: usize, value: Option<&CalcValue>, own: u32) -> Step<i64> {
    match value {
        None => Ok(i64::from(own)),
        Some(value) if value.is_missing() => Ok(i64::from(own)),
        Some(value) => match whole(site, index, value)? {
            0 => Err(Exit::Error(WorksheetErrorCode::Ref)),
            n => Ok(n),
        },
    }
}

catalogue/offset::span.text:
/// The first and last row (or column) of an extent of `size` from `start`: down or right when it
/// is positive, up or left when it is negative.
fn span(start: i64, size: i64) -> (i64, i64) {
    if size > 0 {
        (start, start + size - 1)
    } else {
        (start + size + 1, start)
    }
}

eval/refops::reference.text:
/// An operand of a reference operator: its reference, or the error value that is the result.
fn reference(operand: &CalcValue) -> Result<&ReferenceLike, CalcValue> {
    match operand.core_ref() {
        CoreRef::Reference(reference) => Ok(reference),
        CoreRef::Error(_) if operand.callable_value().is_none() => Err(operand.clone()),
        _ => Err(CalcValue::error(WorksheetErrorCode::Value)),
    }
}

eval/refops::implicit.text:
/// What implicit intersection takes of `value` for a formula at `at`: a reference to one cell, or
/// a value. An array's empty first element is the empty value.
pub(super) fn implicit(value: &CalcValue, at: CellKey) -> CalcValue {
    match value.core_ref() {
        CoreRef::Reference(reference) => match intersect_cell(reference, at) {
            Some(cell) => CalcValue::reference(ReferenceLike::cell(cell)),
            None => CalcValue::error(WorksheetErrorCode::Value),
        },
        CoreRef::Array(array) => array
            .get(0, 0)
            .cloned()
            .expect("an array holds at least one element"),
        _ => value.clone(),
    }
}

eval/refops::intersect_cell.text:
/// The cell implicit intersection picks of `reference` for a formula at `at`, if any.
pub(super) fn intersect_cell(reference: &ReferenceLike, at: CellKey) -> Option<CellKey> {
    let [area] = reference.areas() else {
        return None;
    };
    let (top, left, bottom, right) = bounds(*area);
    let row = if top == bottom {
        top
    } else if (top..=bottom).contains(&at.row()) {
        at.row()
    } else {
        return None;
    };
    let column = if left == right {
        left
    } else if (left..=right).contains(&at.column()) {
        at.column()
    } else {
        return None;
    };
    CellKey::new(area.sheet(), row, column).ok()
}

eval/refops::bounds.text:
fn bounds(area: GridArea) -> (u32, u32, u32, u32) {
    (
        area.first().row(),
        area.first().column(),
        area.last().row(),
        area.last().column(),
    )
}

eval/refops::area.text:
/// The area of `like`'s sheet between the given rows and columns, which lie on the grid.
fn area(like: GridArea, top: u32, left: u32, bottom: u32, right: u32) -> GridArea {
    let sheet = like.sheet();
    GridArea::new(
        CellKey::new(sheet, top, left).expect("a corner of areas on the grid"),
        CellKey::new(sheet, bottom, right).expect("a corner of areas on the grid"),
    )
    .expect("both corners lie on one sheet")
}

eval/refops::references.text:
/// The references of `operands`, all on one sheet, or the value that is the result.
fn references(operands: &[CalcValue]) -> Result<Vec<&ReferenceLike>, CalcValue> {
    let mut out = Vec::with_capacity(operands.len());
    for operand in operands {
        out.push(reference(operand)?);
    }
    let sheet = out[0].sheet();
    // A 3-D reference meets none of the operators (Excel 16.0, 2026-10-23:
    // `=SUM(Ja:Ma!A1:A2 Ja:Ma!A1)` is #VALUE!).
    if out
        .iter()
        .any(|reference| reference.sheet() != sheet || reference.spans_sheets())
    {
        return Err(CalcValue::error(WorksheetErrorCode::Value));
    }
    Ok(out)
}

eval/refops::intersect.text:
/// `left right`.
pub(super) fn intersect(left: &CalcValue, right: &CalcValue) -> CalcValue {
    let operands = [left.clone(), right.clone()];
    let references = match references(&operands) {
        Ok(references) => references,
        Err(value) => return value,
    };
    let mut out = Vec::new();
    for a in references[0].areas() {
        for b in references[1].areas() {
            let (at, al, ab, ar) = bounds(*a);
            let (bt, bl, bb, br) = bounds(*b);
            let (top, left, bottom, right) = (at.max(bt), al.max(bl), ab.min(bb), ar.min(br));
            if top <= bottom && left <= right {
                out.push(area(*a, top, left, bottom, right));
            }
        }
    }
    match ReferenceLike::from_areas(out) {
        Ok(reference) => CalcValue::reference(reference),
        Err(_) => CalcValue::error(WorksheetErrorCode::Null),
    }
}

eval/refops::range.text:
/// `left:right`.
pub(super) fn range(left: &CalcValue, right: &CalcValue) -> CalcValue {
    let operands = [left.clone(), right.clone()];
    let references = match references(&operands) {
        Ok(references) => references,
        Err(value) => return value,
    };
    let mut areas = references.iter().flat_map(|reference| reference.areas());
    let first = *areas.next().expect("a reference holds an area");
    let (mut top, mut left, mut bottom, mut right) = bounds(first);
    for area in areas {
        let (t, l, b, r) = bounds(*area);
        top = top.min(t);
        left = left.min(l);
        bottom = bottom.max(b);
        right = right.max(r);
    }
    CalcValue::reference(ReferenceLike::area(area(first, top, left, bottom, right)))
}

eval/refops::union.text:
/// `(a,b,...)`.
pub(super) fn union(operands: &[CalcValue]) -> CalcValue {
    let references = match references(operands) {
        Ok(references) => references,
        Err(value) => return value,
    };
    let areas = references
        .iter()
        .flat_map(|reference| reference.areas().iter().copied())
        .collect();
    match ReferenceLike::from_areas(areas) {
        Ok(reference) => CalcValue::reference(reference),
        Err(_) => CalcValue::error(WorksheetErrorCode::Value),
    }
}

