catalogue/aggregate::direct_first.text:
/// Reads the direct arguments through worksheet number coercion, in order, and stops at the first
/// that is an error or that coercion stops on. Their numbers are not used: the fold reads them
/// again in the reading order.
pub(super) fn direct_first(site: &Site<'_>, arguments: &[CalcValue]) -> Step<()> {
    for (index, argument) in arguments.iter().enumerate() {
        if !matches!(
            argument.core_ref(),
            CoreRef::Reference(_) | CoreRef::Array(_)
        ) {
            site.number_argument(index, argument)?;
        }
    }
    Ok(())
}

catalogue/group_pivot::percentof.text:
/// PERCENTOF (dc-h9u): the sum of data_subset divided by the sum of data_all, each summed as SUM
/// sums its one argument; #DIV/0! when the second sum is 0.
fn percentof(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    let site = Site::new(PERCENTOF, services);
    let mut sums = [0.0f64; 2];
    let mut read = Ok(());
    for (index, total) in sums.iter_mut().enumerate() {
        let one = std::slice::from_ref(&arguments[index]);
        let held = matches!(one[0].core_ref(), CoreRef::Reference(_) | CoreRef::Array(_));
        read = read
            .and_then(|()| direct_first(&site, one).map_err(|exit| reindex(exit, index)))
            .and_then(|()| {
                each_number(&site, one, services, Held::Numbers, &mut |n| {
                    *total = site.add(*total, n)?;
                    Ok(())
                })
                .map_err(|exit| match exit {
                    // An error a reference or an array holds is #NUM! (Excel 16.0.20527:
                    // PERCENTOF(C1,4) over C1 = #N/A, PERCENTOF({1,#N/A},4) are #NUM!).
                    Exit::Error(_) if held => Exit::Error(WorksheetErrorCode::Num),
                    other => reindex(other, index),
                })
            });
    }
    Site::finish(read.and_then(|()| site.number(site.divide(sums[0], sums[1])?)))
}

catalogue/group_pivot::reindex.text:
/// A refusal or fault naming argument 0 of a one-argument read, renamed to argument `index`.
fn reindex(exit: Exit, index: usize) -> Exit {
    match exit {
        Exit::Fault(FunctionFault::NotImplemented {
            id,
            argument: Some(0),
        }) => Exit::Fault(FunctionFault::NotImplemented {
            id,
            argument: Some(index),
        }),
        other => other,
    }
}

catalogue/statistics::percent_rank.text:
fn percent_rank(
    site: &Site<'_>,
    a: &[CalcValue],
    sv: &mut EvalServices<'_>,
    mode: PercentRankMode,
) -> Step<CalcValue> {
    // Literal text is coerced during argument binding; reference contents are
    // read after the scalar argument errors have been resolved.
    let literal_values = if matches!(a[0].core_ref(), CoreRef::Text(_)) {
        Some(list(site, a, 0, sv)?)
    } else {
        None
    };
    let x = num(site, a, 1)?;
    let significance = opt(site, a, 2, 3.0)?.trunc() as i64;
    let mut values = match literal_values {
        Some(values) => values,
        None => list(site, a, 0, sv)?,
    };
    out(site, percentrank(&mut values, x, significance, mode))
}

