catalogue/statistics::prob_nonnumeric_si.text:
/// A single text or logical item supplies no numeric pair to PROB. Excel 20527 validates the
/// bounds first, then returns #DIV/0!; blank cells and errors follow their existing routes.
fn prob_nonnumeric_singletons(
    site: &Site<'_>,
    a: &[CalcValue],
    sv: &mut EvalServices<'_>,
) -> Step<bool> {
    let scalar = |value: &CalcValue| match value.core_ref() {
        CoreRef::Reference(reference) => matches!(reference.areas(), [area] if area.cell_count() == 1),
        CoreRef::Number(_) | CoreRef::Text(_) | CoreRef::Logical(_) => true,
        _ => false,
    };
    if !scalar(&a[0]) || !scalar(&a[1]) {
        return Ok(false);
    }
    let x = grid(site, a, 0, sv)?;
    let p = grid(site, a, 1, sv)?;
    let [x] = x.cells.as_slice() else { return Ok(false) };
    let [p] = p.cells.as_slice() else { return Ok(false) };
    let supported = |v: &CalcValue| match v.core_ref() {
        CoreRef::Number(n) => n.is_finite(),
        CoreRef::Text(_) | CoreRef::Logical(_) => true,
        _ => false,
    };
    if !supported(x) || !supported(p)
        || (matches!(x.core_ref(), CoreRef::Number(_)) && matches!(p.core_ref(), CoreRef::Number(_)))
    {
        return Ok(false);
    }
    let _ = num(site, a, 2)?;
    if given(a, 3) {
        let _ = num(site, a, 3)?;
    }
    Ok(true)
}

catalogue/statistics::strict_numbers.text:
/// PROB's lists: every cell must hold a number (an error cell is the result, anything else
/// #VALUE!).
fn strict_numbers(
    site: &Site<'_>,
    a: &[CalcValue],
    index: usize,
    sv: &mut EvalServices<'_>,
) -> Step<Vec<f64>> {
    let g = grid(site, a, index, sv)?;
    let mut found = Vec::with_capacity(g.cells.len());
    for cell in &g.cells {
        match cell.core_ref() {
            CoreRef::Number(n) => found.push(n),
            CoreRef::Error(code) => return fail(code),
            _ => return fail(WorksheetErrorCode::Value),
        }
    }
    Ok(found)
}

ported/lookup_prob_frequency_family::pro.text:
pub(crate) fn prob_kernel(
    x_values: &[f64],
    probabilities: &[f64],
    lower: f64,
    upper: Option<f64>,
) -> Result<f64, WorksheetErrorCode> {
    if x_values.len() != probabilities.len() || x_values.is_empty() {
        return Err(WorksheetErrorCode::NA);
    }
    // Excel 20527's singleton sum check accepts the four predecessors of 1 through its 22nd
    // successor. A reversed interval has no members; multi-item sums keep their existing route.
    if let ([x], [p]) = (x_values, probabilities)
    {
        let upper = upper.unwrap_or(lower);
        if x.is_finite() && p.is_finite() && lower.is_finite() && upper.is_finite() {
            if (1.0_f64.to_bits() - 4..=1.0_f64.to_bits() + 22).contains(&p.to_bits()) {
                return Ok(if *x >= lower && *x <= upper { *p } else { 0.0 });
            }
            return Err(WorksheetErrorCode::Num);
        }
    }
    if probabilities
        .iter()
        .any(|p| !p.is_finite() || *p < 0.0 || *p > 1.0)
    {
        return Err(WorksheetErrorCode::Num);
    }
    let sum = probabilities.iter().sum::<f64>();
    if (sum - 1.0).abs() > PROB_SUM_TOLERANCE {
        return Err(WorksheetErrorCode::Num);
    }
    let upper = upper.unwrap_or(lower);
    if upper < lower || !lower.is_finite() || !upper.is_finite() {
        return Err(WorksheetErrorCode::Num);
    }
    let mut total = 0.0;
    for (x, p) in x_values.iter().zip(probabilities.iter()) {
        if *x >= lower && *x <= upper {
            total += *p;
        }
    }
    Ok(total)
}

catalogue/aggregate::product.text:
/// PRODUCT: the numbers multiplied from 1, or 0 when there is none. An omitted argument is passed
/// over (dc-bd5: PRODUCT(2,) is 2 in Excel 16.0.20430, where SUM and the others read it as 0).
fn product(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    let site = Site::new(PRODUCT, services);
    if holds_held_arrays(arguments) {
        return Site::finish(Err(Exit::Error(WorksheetErrorCode::NA)));
    }
    let given: Vec<CalcValue> = arguments
        .iter()
        .filter(|argument| !argument.is_missing())
        .cloned()
        .collect();
    let arguments = given.as_slice();
    let mut running: Option<f64> = None;
    let read = each_number(&site, arguments, services, Held::Numbers, &mut |n| {
        running = Some(times(&site, running.unwrap_or(1.0), n)?);
        Ok(())
    });
    Site::finish(read.and_then(|()| site.number(running.unwrap_or(0.0))))
}

