/// `a * b` at an arithmetic site; a product below binary64's normal range is 0, as Excel flushes
/// it (dc-bd5).
fn times(site: &Site<'_>, a: f64, b: f64) -> Step<f64> {
    let product = site.multiply(a, b)?;
    if product.is_subnormal() {
        Ok(0.0)
    } else {
        Ok(product)
    }
}

