    let pattern = text_arg(site, a, 1)?;
    let sensitive = case_sensitive(site, a, 2)?;
    let (_, found) = regex(site, &text, &pattern, sensitive, true)?;
    Ok(CalcValue::logical(!found.is_empty()))
}

