/// SIGN: 1 for a positive number, -1 for a negative one, 0 for zero.
fn sign(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    if let Some(n) = arguments[0].as_number()
        && n.is_subnormal()
        && n.is_sign_negative()
