        (CoreRef::Error(a), CoreRef::Error(b)) => Ok((a as u8).cmp(&(b as u8))),
        (CoreRef::Array(_) | CoreRef::Reference(_), _)
        | (_, CoreRef::Array(_) | CoreRef::Reference(_)) => Err(site.not_modelled(None)),
        _ => Ok(kind(x).cmp(&kind(y))),
