fn numeric_cells(
    site: &Site<'_>,
    a: &[CalcValue],
    index: usize,
    services: &mut crate::call::EvalServices<'_>,
) -> Step<NumericCells> {
    let g = grid(site, a, index, services)?;
    let mut cells = Vec::with_capacity(g.cells.len());
