fn t_cdf(x: f64, deg_freedom: f64) -> Result<f64, WorksheetErrorCode> {
    let v = truncate_positive_integer(deg_freedom)?;
    let half = 0.5 * t_two_tail(x, v)?;
    Ok(if x >= 0.0 { 1.0 - half } else { half })
}

