fn fold_ascii_case(unit: u16) -> u16 {
    if (b'A' as u16..=b'Z' as u16).contains(&unit) {
        unit + 32
    } else {
        unit
    }
}

ported/text_more::units_match.text:
fn units_match(left: &[u16], right: &[u16], case_insensitive: bool) -> bool {
    left.len() == right.len()
        && left.iter().zip(right).all(|(l, r)| {
            if case_insensitive {
                fold_ascii_case(*l) == fold_ascii_case(*r)
            } else {
                l == r
            }
        })
}

ported/text_more::delimited.text:
/// TEXTBEFORE or TEXTAFTER over any of `delimiters` (the first found at each position).
pub(crate) fn delimited(
    side: Side,
    text: &ExcelText,
    delimiters: &[ExcelText],
    instance: isize,
    case_insensitive: bool,
    match_end: bool,
    single_delimiter: bool,
) -> Delimited {
    let requested = instance.unsigned_abs();
    if instance == 0 {
        return Delimited::BadInstance;
    }
    // Excel's empty single delimiter ignores the ordinary length bound. When
    // the input is exactly one UTF-16 unit, BEFORE returns it and AFTER is empty.
    if single_delimiter && delimiters[0].utf16_code_units().is_empty() {
        let one_unit = text.len_utf16_code_units() == 1;
        let whole = match (side, instance < 0, one_unit) {
            (Side::Before, _, true) | (Side::Before, true, false) | (Side::After, false, false) => {
                text.clone()
            }
            _ => ExcelText::from_utf16_code_units(Vec::new()),
        };
        return Delimited::Text(whole);
    }
    // The first search of empty text is still a valid search, with no delimiter to find.
    // Excel 16.0.20430: TEXTBEFORE("","-") and TEXTAFTER("","-") are #N/A (the
    // recorded typed Value2 cases w111typed-00274 and w111typed-00266, dc-zsn.7).
    if requested > text.len_utf16_code_units().max(1) {
        return Delimited::BadInstance;
    }
    let units = text.utf16_code_units();
    if delimiters.iter().any(|d| d.utf16_code_units().is_empty()) {
        let whole = match (side, instance < 0) {
            (Side::After, false) | (Side::Before, true) => text.clone(),
            _ => ExcelText::from_utf16_code_units(Vec::new()),
        };
        return Delimited::Text(whole);
    }
    // The boundaries: (start, length) of each delimiter found, left to right, not overlapping.
    let mut boundaries = Vec::new();
    let mut at = 0usize;
    while at < units.len() {
        let found = delimiters.iter().find_map(|delimiter| {
            let needle = delimiter.utf16_code_units();
            (at + needle.len() <= units.len()
                && units_match(&units[at..at + needle.len()], needle, case_insensitive))
            .then_some(needle.len())
        });
        match found {
            Some(length) => {
                boundaries.push((at, length));
                at += length;
            }
            None => at += 1,
        }
    }
    if match_end {
        if instance < 0 {
            boundaries.insert(0, (0, 0));
        } else {
            boundaries.push((units.len(), 0));
        }
    }
    let selected = if instance < 0 {
        boundaries
            .len()
            .checked_sub(requested)
            .and_then(|index| boundaries.get(index))
    } else {
        boundaries.get(requested - 1)
    };
    match selected {
        Some(&(start, length)) => Delimited::Text(ExcelText::from_utf16_code_units(match side {
            Side::Before => units[..start].to_vec(),
            Side::After => units[start + length..].to_vec(),
        })),
        None => Delimited::NotFound,
    }
}

catalogue/text_functions::delimiters.text:
/// TEXTJOIN's delimiters: one text, or each cell of a reference or an array in turn, used in
/// order and again from the first (Microsoft's TEXTJOIN page: a range of delimiters). A reference
/// of several areas (a 3-D reference) gives the cells of each area in its order (Excel 16.0.20430,
/// 2026-10-25, dc-6au, sheets Ja, Fe and Ma holding 1, 2, 3 in A1 and 100, 200, 300 in A2:
/// `=TEXTJOIN(Ja:Ma!A1,1,"a","b")` "a1b", `=TEXTJOIN(Ja:Ma!A1:A2,1,"a","b","c")` "a1b100c",
/// `=TEXTJOIN(Fe:Ma!A1,1,"a","b","c")` "a2b3c").
fn delimiters(
    site: &Site<'_>,
    a: &[CalcValue],
    sv: &mut crate::call::EvalServices<'_>,
) -> Step<Vec<Vec<u16>>> {
    let mut found = Vec::new();
    match a[0].core_ref() {
        CoreRef::Reference(reference) => {
            for &area in reference.areas() {
                let one = [CalcValue::reference(crate::value::ReferenceLike::area(
                    area,
                ))];
                for value in &grid(site, &one, 0, sv)?.cells {
                    found.push(cell_text(site, 0, value)?);
                }
            }
        }
        CoreRef::Array(_) => {
            for value in &cells(site, a, 0, sv)?.cells {
                found.push(cell_text(site, 0, value)?);
            }
        }
        _ => found.push(text_arg(site, a, 0)?.utf16_code_units().to_vec()),
    }
    Ok(found)
}

catalogue/text_functions::textjoin.text:
fn textjoin(
    site: &Site<'_>,
    a: &[CalcValue],
    sv: &mut crate::call::EvalServices<'_>,
) -> Step<CalcValue> {
    let delimiters = delimiters(site, a, sv)?;
    let ignore_empty = num(site, a, 1)? != 0.0;
    let mut joined: Vec<u16> = Vec::new();
    let mut parts = 0usize;
    for index in 2..a.len() {
        let g = cells(site, a, index, sv)?;
        for value in &g.cells {
            if ignore_empty && matches!(value.core_ref(), CoreRef::Empty | CoreRef::Missing) {
                continue;
            }
            let units = cell_text(site, index, value)?;
            if ignore_empty && units.is_empty() {
                continue;
            }
            let delimiter: &[u16] = if delimiters.is_empty() {
                &[]
            } else {
                &delimiters[parts.saturating_sub(1) % delimiters.len()]
            };
            let extra = units.len() + if parts == 0 { 0 } else { delimiter.len() };
            if joined.len() + extra > EXCEL_TEXT_MAX_UTF16_CODE_UNITS {
                return fail(WorksheetErrorCode::Calc);
            }
            if parts > 0 {
                joined.extend_from_slice(delimiter);
            }
            joined.extend_from_slice(&units);
            parts += 1;
        }
    }
    Ok(CalcValue::text(ExcelText::from_utf16_code_units(joined)))
}

