/// The cells of row (or column, `by_col`) `index` of `array`.
fn line(array: &CalcArray, index: usize, by_col: bool) -> Vec<CalcValue> {
    let ArrayShape { rows, cols } = array.shape();
    if by_col {
        (0..rows)
            .map(|r| {
