pub fn eval_vstack_prepared(args: &[CalcValue]) -> Result<CalcValue, DynamicArrayReshapeEvalError> {
    let sources: Vec<StackArgSource<'_>> = args.iter().map(StackArgSource::new).collect();
    let rows: usize = sources.iter().map(|source| source.shape().rows).sum();
    let cols = sources
        .iter()
        .map(|source| source.shape().cols)
        .max()
        .unwrap_or(1);

    let cells = sources.iter().flat_map(|source| {
        (0..source.shape().rows).flat_map(move |row| {
            (0..cols).map(move |col| {
                source
                    .get(row, col)
                    .cloned()
                    .unwrap_or(CalcValue::error(WorksheetErrorCode::NA))
            })
        })
    });
    build_array(rows, cols, cells.collect())
}

fetch::names_a_port.text:
/// Whether a URL with no scheme is `host:port`, the one form Excel fetches without a scheme.
fn names_a_port(url: &str) -> bool {
    url.split_once(':').is_some_and(|(host, rest)| {
        let port = rest.split('/').next().unwrap_or_default();
        !host.is_empty()
            && !host.contains('/')
            && !port.is_empty()
            && port.bytes().all(|b| b.is_ascii_digit())
    })
}

fetch::prepare_text.text:
/// WEBSERVICE's one element.
pub(crate) fn prepare_text(url: &CalcValue) -> Prepared {
    let text = match url.core_ref() {
        CoreRef::Error(_) if url.image_value().is_none() => return Prepared::Answer(url.clone()),
        CoreRef::Text(text) => text.to_string_lossy(),
        _ => return Prepared::Answer(value_error()),
    };
    let trimmed = text.trim_matches(' ');
    let allowed = match scheme(trimmed) {
        Some(scheme) => scheme.eq_ignore_ascii_case("http") || scheme.eq_ignore_ascii_case("https"),
        None => names_a_port(trimmed),
    };
    if text.is_empty() || text.chars().count() > URL_LIMIT || !allowed {
        return Prepared::Answer(value_error());
    }
    Prepared::Fetch(
        FetchRequest {
            kind: FetchKind::Text,
            url: wire_url(&text),
        },
        None,
    )
}

