ported/dynamic_array_reshape_family::eva.text:
pub fn eval_wraprows_prepared(
    args: &[CalcValue],
) -> Result<CalcValue, DynamicArrayReshapeEvalError> {
    let wrap_count = wrap_count(&args[1])?;
    match args[0].core_ref() {
        CoreRef::Number(_) | CoreRef::Text(_) | CoreRef::Logical(_) | CoreRef::Error(_) => {
            return Ok(args[0].clone());
        }
        CoreRef::Array(_) | CoreRef::Reference(_) | CoreRef::Missing | CoreRef::Empty => {}
    }

    let source = wrap_vector(&args[0])?;
    let pad_cell = args
        .get(2)
        .map(scalar_cell)
        .unwrap_or(CalcValue::error(WorksheetErrorCode::NA));
    let flat = flatten_cells(&source, false);
    // A maximum width does not pad a vector that already fits in a single row.
    let cols = wrap_count.min(flat.len());
    let rows = flat.len().div_ceil(cols);
    let mut cells = Vec::with_capacity(rows * cols);
    let mut iter = flat.into_iter();
    for _row in 0..rows {
        for _col in 0..cols {
            cells.push(iter.next().unwrap_or_else(|| pad_cell.clone()));
        }
    }
    build_array(rows, cols, cells)
}

catalogue/financial::entry::XIRR.text:
20 xirr_fn |s, a, sv| {
    // XIRR reads its optional scalar guess before the two paired vectors.
    // Logical guesses are VALUE; IRR's separate call admits them.
    let g = guess(s, a, 2, sv, true)?;
    let values = resolved(s, a, 0, sv)?;
    let dates = resolved(s, a, 1, sv)?;
    let collect = |index, value: &CalcValue| -> Step<Vec<f64>> {
        if matches!(value.core_ref(), CoreRef::Array(_)) {
            match cash::collect_numeric_vector_from_eval(value) {
                Ok(v) => Ok(v),
                Err(error) => cash_err(error),
            }
        } else {
            required_number(value)?;
            s.number_argument(index, value).map(|n| vec![n])
        }
    };
    let values = collect(0, &values)?;
    // Read numeric dates before their serial domains. A singleton pair is
    // NA even at a negative date; scalar guess errors precede that check.
    let dates = collect(1, &dates)?;
    if g.is_some_and(|value| value <= -1.0) { return fail(W::Num); }
    if values.len() == 1 && dates.len() == 1 { return fail(W::NA); }
    let dates = match dates.into_iter().map(cash::serial_from_number).collect::<Result<Vec<_>, _>>() {
        Ok(dates) => dates,
        Err(error) => return cash_err(error),
    };
    out(s, cash::xirr_kernel(&values, &dates, g))
}

ported/cashflow_rate_family::collect_num.text:
pub(crate) fn collect_numeric_vector_from_eval(
    value: &CalcValue,
) -> Result<Vec<f64>, CashflowRateEvalError> {
    match value.core_ref() {
        CoreRef::Number(n) => Ok(vec![n]),
        CoreRef::Error(code) => Err(CashflowRateEvalError::Domain(code)),
        CoreRef::Array(array) => {
            let shape = array.shape();
            if shape.rows > 1 && shape.cols > 1 {
                return Err(CashflowRateEvalError::Domain(WorksheetErrorCode::Ref));
            }
            let mut out = Vec::with_capacity(shape.rows * shape.cols);
            for cell in array.iter_row_major() {
                out.push(numeric_from_cell(cell)?);
            }
            Ok(out)
        }
        CoreRef::Text(_) | CoreRef::Logical(_) | CoreRef::Reference(_) => {
            Err(CashflowRateEvalError::Domain(WorksheetErrorCode::Value))
        }
        _ => Err(CashflowRateEvalError::Domain(WorksheetErrorCode::Value)),
    }
}

ported/cashflow_rate_family::serial_from.text:
pub(crate) fn serial_from_number(value: f64) -> Result<i64, CashflowRateEvalError> {
    if !value.is_finite() {
        return Err(CashflowRateEvalError::Domain(WorksheetErrorCode::Num));
    }
    let serial = value.trunc() as i64;
    if serial < 0 {
        return Err(CashflowRateEvalError::Domain(WorksheetErrorCode::Num));
    }
    Ok(serial)
}

