fn validate_xcashflow_inputs(values: &[f64], dates: &[i64]) -> Result<(), WorksheetErrorCode> {
    validate_cashflows(values)?;
    if values.len() != dates.len() || dates.is_empty() {
        return Err(WorksheetErrorCode::Num);
    }
    let anchor = dates[0];
    if dates.iter().any(|date| *date < anchor) {
        return Err(WorksheetErrorCode::Num);
    }
    Ok(())
}

ported/cashflow_rate_family::validate_xn.text:
fn validate_xnpv_inputs(values: &[f64], dates: &[i64]) -> Result<(), WorksheetErrorCode> {
    if values.len() != dates.len() || dates.is_empty() {
        return Err(WorksheetErrorCode::Num);
    }
    if !values.iter().all(|v| v.is_finite()) {
        return Err(WorksheetErrorCode::Value);
    }
    let anchor = dates[0];
    if dates.iter().any(|date| *date < anchor) {
        return Err(WorksheetErrorCode::Num);
    }
    Ok(())
}

ported/cashflow_rate_family::xnpv_kernel.text:
fn xnpv_kernel_raw(rate: f64, values: &[f64], dates: &[i64]) -> Result<f64, WorksheetErrorCode> {
    validate_xnpv_inputs(values, dates)?;
    if !rate.is_finite() || rate <= MIN_VALID_RATE {
        return Err(WorksheetErrorCode::Num);
    }
    let base = 1.0 + rate;
    let anchor = dates[0];
    let mut total = 0.0;
    for (value, date) in values.iter().zip(dates.iter()) {
        let years = (*date - anchor) as f64 / 365.0;
        total += *value / crt_pow(base, years);
    }
    if total.is_finite() {
        Ok(total)
    } else {
        Err(WorksheetErrorCode::Num)
    }
}

ported/cashflow_rate_family::xnpv_deriva.text:
fn xnpv_derivative(rate: f64, values: &[f64], dates: &[i64]) -> Result<f64, WorksheetErrorCode> {
    validate_xnpv_inputs(values, dates)?;
    if !rate.is_finite() || rate <= MIN_VALID_RATE {
        return Err(WorksheetErrorCode::Num);
    }
    let base = 1.0 + rate;
    let anchor = dates[0];
    let mut total = 0.0;
    for (value, date) in values.iter().zip(dates.iter()) {
        let years = (*date - anchor) as f64 / 365.0;
        if years == 0.0 {
            continue;
        }
        total += -years * *value / crt_pow(base, years + 1.0);
    }
    if total.is_finite() {
        Ok(total)
    } else {
        Err(WorksheetErrorCode::Num)
    }
}

ported/cashflow_rate_family::bounded_rat.text:
fn bounded_rate_solve<F, D>(
    guess: f64,
    mut f: F,
    mut derivative: D,
) -> Result<f64, WorksheetErrorCode>
where
    F: FnMut(f64) -> Result<f64, WorksheetErrorCode>,
    D: FnMut(f64) -> Result<f64, WorksheetErrorCode>,
{
    let mut prev_rate = 0.0;
    let mut prev_value = f(prev_rate)?;
    let mut current_rate = if guess <= MIN_VALID_RATE { 0.1 } else { guess };
    let mut current_value = f(current_rate)?;

    for _ in 0..ROOT_MAX_ITERATIONS {
        if current_value.abs() <= ROOT_TOLERANCE {
            return polish_rate(current_rate, &mut f, &mut derivative);
        }

        let secant_next = if (current_value - prev_value).abs() > ROOT_DERIVATIVE_EPS {
            let next = current_rate
                - current_value * (current_rate - prev_rate) / (current_value - prev_value);
            (next.is_finite() && next > MIN_VALID_RATE).then_some(next)
        } else {
            None
        };

        let newton_next = if let Ok(deriv) = derivative(current_rate) {
            if deriv.abs() > ROOT_DERIVATIVE_EPS {
                let next = current_rate - current_value / deriv;
                (next.is_finite() && next > MIN_VALID_RATE).then_some(next)
            } else {
                None
            }
        } else {
            None
        };

        let next_rate = secant_next.or(newton_next).unwrap_or_else(|| {
            if current_rate > 0.0 {
                current_rate / 2.0
            } else {
                0.1
            }
        });

        prev_rate = current_rate;
        prev_value = current_value;
        current_rate = if next_rate <= MIN_VALID_RATE {
            0.1
        } else {
            next_rate
        };
        current_value = f(current_rate)?;
    }

    if current_value.abs() <= ROOT_TOLERANCE {
        polish_rate(current_rate, &mut f, &mut derivative)
    } else {
        Err(WorksheetErrorCode::Num)
    }
}

ported/cashflow_rate_family::polish_rate.text:
/// Once the bracketed solve is within `ROOT_TOLERANCE` of a root, the residual
/// `|NPV|` can still leave the *rate* far (10^4–10^5 ULP) from the true root when
/// the NPV slope is gentle — beyond the `IRR_PUBLICATION_ULP_SCAN_RADIUS` plateau
/// scan that selects Excel's published double. Polish the seed with analytic
/// Newton to a rate fixpoint so the plateau sits adjacent to the |NPV|-minimal
/// double (for a representable exact root this lands on it bit-for-bit).
fn polish_rate<F, D>(seed: f64, f: &mut F, derivative: &mut D) -> Result<f64, WorksheetErrorCode>
where
    F: FnMut(f64) -> Result<f64, WorksheetErrorCode>,
    D: FnMut(f64) -> Result<f64, WorksheetErrorCode>,
{
    let mut rate = seed;
    let mut last_step = f64::INFINITY;
    for _ in 0..ROOT_POLISH_ITERATIONS {
        let value = f(rate)?;
        let deriv = match derivative(rate) {
            // Currency units do not decide whether a nonzero slope can polish a rate.
            Ok(d) if d != 0.0 => d,
            _ => break,
        };
        let next = rate - value / deriv;
        if !next.is_finite() || next <= MIN_VALID_RATE {
            break;
        }
        if next.to_bits() == rate.to_bits() {
            break; // bit-level fixpoint
        }
        let step = (next - rate).abs();
        if step >= last_step {
            // No longer contracting (rounding noise near the root): keep whichever
            // of the adjacent candidates has the smaller residual.
            if f(next)?.abs() <= value.abs() {
                rate = next;
            }
            break;
        }
        last_step = step;
        rate = next;
    }
    Ok(rate)
}

ported/cashflow_rate_family::xirr_two_ca.text:
fn xirr_two_cashflow_root(values: &[f64], dates: &[i64]) -> Result<f64, WorksheetErrorCode> {
    if values.len() != 2 || dates.len() != 2 {
        return Err(WorksheetErrorCode::Num);
    }
    let first = values[0];
    let second = values[1];
    let years = (dates[1] - dates[0]) as f64 / 365.0;
    if years <= 0.0 || first == 0.0 {
        return Err(WorksheetErrorCode::Num);
    }
    let ratio = -second / first;
    if !ratio.is_finite() || ratio <= 0.0 {
        return Err(WorksheetErrorCode::Num);
    }
    let root = crt_pow(ratio, 1.0 / years) - 1.0;
    if root.is_finite() && root > MIN_VALID_RATE {
        Ok(root)
    } else {
        Err(WorksheetErrorCode::Num)
    }
}

fn xirr_two_cashflow_positive_root_excel_like(
    values: &[f64],
    dates: &[i64],
    guess: f64,
) -> Result<f64, WorksheetErrorCode> {
    if !guess.is_finite() || guess <= 0.0 {
        return Err(WorksheetErrorCode::Num);
    }

    let mut lower = 0.0;
    let mut lower_value = xnpv_kernel_raw(lower, values, dates)?;
    let mut upper = guess;
    let mut upper_value = xnpv_kernel_raw(upper, values, dates)?;

    if lower_value == 0.0 {
        return Ok(lower);
    }
    if upper_value == 0.0 {
        return Ok(upper);
    }

    let mut expansions = 0usize;
    while lower_value.signum() == upper_value.signum() {
        lower = upper;
        lower_value = upper_value;
        upper *= 2.0;
        if !upper.is_finite() || upper <= MIN_VALID_RATE {
            return Err(WorksheetErrorCode::Num);
        }
        upper_value = xnpv_kernel_raw(upper, values, dates)?;
        expansions += 1;
        if expansions > XIRR_TWO_CASHFLOW_MAX_BRACKET_EXPANSIONS {
            return Err(WorksheetErrorCode::Num);
        }
    }

    for _ in 0..ROOT_MAX_ITERATIONS {
        let midpoint = (lower + upper) / 2.0;
        let relative_width = (upper - lower) / midpoint.abs();
        if relative_width <= XIRR_TWO_CASHFLOW_RELATIVE_BRACKET_TOLERANCE {
            return Ok(midpoint);
        }

        let midpoint_value = xnpv_kernel_raw(midpoint, values, dates)?;
        if midpoint_value == 0.0 {
            return Ok(midpoint);
        }
        if lower_value.signum() == midpoint_value.signum() {
            lower = midpoint;
            lower_value = midpoint_value;
        } else {
            upper = midpoint;
        }
    }

    Err(WorksheetErrorCode::Num)
}

ported/cashflow_rate_family::xirr_genera.text:
fn xirr_general_positive_root_excel_like(
    values: &[f64],
    dates: &[i64],
    guess: f64,
) -> Result<f64, WorksheetErrorCode> {
    if !guess.is_finite() || guess <= 0.0 {
        return Err(WorksheetErrorCode::Num);
    }

    let zero = 0.0;
    let zero_value = xnpv_kernel_raw(zero, values, dates)?;
    if zero_value == 0.0 {
        return Ok(zero);
    }

    let mut lower = guess;
    let mut lower_value = xnpv_kernel_raw(lower, values, dates)?;
    if lower_value == 0.0 {
        return Ok(lower);
    }

    let mut upper;

    if zero_value.signum() != lower_value.signum() {
        lower = zero;
        lower_value = zero_value;
        upper = guess;
        let upper_value = xnpv_kernel_raw(upper, values, dates)?;
        if upper_value == 0.0 {
            return Ok(upper);
        }
    } else {
        upper = guess * 2.0;
        if !upper.is_finite() || upper <= MIN_VALID_RATE {
            return Err(WorksheetErrorCode::Num);
        }
        let mut upper_value = xnpv_kernel_raw(upper, values, dates)?;

        let mut expansions = 0usize;
        while lower_value.signum() == upper_value.signum() {
            lower = upper;
            lower_value = upper_value;
            upper *= 2.0;
            if !upper.is_finite() || upper <= MIN_VALID_RATE {
                return Err(WorksheetErrorCode::Num);
            }
            upper_value = xnpv_kernel_raw(upper, values, dates)?;
            expansions += 1;
            if expansions > XIRR_GENERAL_POSITIVE_ROOT_MAX_BRACKET_EXPANSIONS {
                return Err(WorksheetErrorCode::Num);
            }
        }
    }

    for _ in 0..ROOT_MAX_ITERATIONS {
        let midpoint = (lower + upper) / 2.0;
        let bracket_width = upper - lower;
        let brent_tol = XIRR_GENERAL_POSITIVE_ROOT_BRENT_EPS * (1.0 + 2.0 * midpoint.abs());
        if bracket_width <= brent_tol {
            return Ok(midpoint);
        }

        let midpoint_value = xnpv_kernel_raw(midpoint, values, dates)?;
        if midpoint_value == 0.0 {
            return Ok(midpoint);
        }
        if lower_value.signum() == midpoint_value.signum() {
            lower = midpoint;
            lower_value = midpoint_value;
        } else {
            upper = midpoint;
        }
    }

    Err(WorksheetErrorCode::Num)
}

ported/cashflow_rate_family::xirr_kernel.text:
pub(crate) fn xirr_kernel(
    values: &[f64],
    dates: &[i64],
    guess: Option<f64>,
) -> Result<f64, WorksheetErrorCode> {
    validate_xcashflow_inputs(values, dates)?;
    let guess = guess.unwrap_or(0.1);
    if values.len() == 2 && dates.len() == 2 {
        let root = xirr_two_cashflow_root(values, dates)?;
        if root >= 0.0 && guess < 0.0 {
            return Err(WorksheetErrorCode::Num);
        }
        if root >= 0.0 {
            return xirr_two_cashflow_positive_root_excel_like(values, dates, guess);
        }
        return Ok(root);
    }

    if guess > 0.0 {
        if let Ok(root) = xirr_general_positive_root_excel_like(values, dates, guess) {
            return Ok(root);
        }
    }

    bounded_rate_solve(
        guess,
        |rate| xnpv_kernel_raw(rate, values, dates),
        |rate| xnpv_derivative(rate, values, dates),
    )
}

catalogue/lookup::Held::blank.text:
/// The first (`from_end` false) or last blank position, if any.
fn blank(&self, from_end: bool) -> Option<u64> {
    if from_end {
        let mut expected = self.len;
        for (at, _) in self.cells.iter().rev() {
            if at + 1 != expected {
                return Some(expected - 1);
            }
            expected = *at;
        }
        expected.checked_sub(1)
    } else {
        let mut expected = 0;
        for (at, _) in &self.cells {
            if *at != expected {
                return Some(expected);
            }
            expected = at + 1;
        }
        (expected < self.len).then_some(expected)
    }
}

catalogue/lookup::xmatch_linear.text:
/// XMATCH's linear search (search_mode 1 or -1).
fn xmatch_linear(
    site: &Site<'_>,
    services: &mut EvalServices<'_>,
    line: Line<'_>,
    key: Item<'_>,
    mode: Mode,
    from_end: bool,
) -> Step<Option<u64>> {
    if !from_end && matches!(mode, Mode::Exact | Mode::Wildcard) && !matches!(key, Item::Blank) {
        // A walk from the start may stop at the first hit.
        return first_hit(
            site,
            services,
            line,
            &Target::new(key, mode == Mode::Wildcard),
        );
    }
    let held = line.held(site, services)?;
    if let Item::Blank = key {
        // A blank lookup value matches only blank cells, the first or last of them; with none,
        // the next smaller value is the largest other value, and nothing is larger.
        if let Some(at) = held.blank(from_end) {
            return Ok(Some(at));
        }
        if mode != Mode::NextSmaller {
            return Ok(None);
        }
    }
    let target = Target::new(key, mode == Mode::Wildcard);
    let in_search_order = || -> Box<dyn Iterator<Item = &(u64, CalcValue)>> {
        if from_end {
            Box::new(held.cells.iter().rev())
        } else {
            Box::new(held.cells.iter())
        }
    };
    // An equal cell is the result, the first met: no order is needed when there is one.
    for (at, value) in in_search_order() {
        if target.hits(site, item(site, 1, value)?)? {
            return Ok(Some(*at));
        }
    }
    if matches!(mode, Mode::Exact | Mode::Wildcard) {
        return Ok(None);
    }
    let wanted = if mode == Mode::NextSmaller {
        Ordering::Less
    } else {
        Ordering::Greater
    };
    // The candidates of the kind nearest the lookup value, in the order met: the kinds decide
    // first, so two candidates are ordered within their kind only when that kind holds the result
    // (an order calc_func's comparison cannot decide between two texts refuses only then).
    let mut nearest_kind: Vec<(u64, Item<'_>)> = Vec::new();
    for (at, value) in in_search_order() {
        let cell = item(site, 1, value)?;
        if order(site, cell, key)? != wanted {
            continue;
        }
        match nearest_kind.first() {
            Some((_, kept)) if kept.rank() == cell.rank() => nearest_kind.push((*at, cell)),
            Some((_, kept)) if cell.rank().cmp(&kept.rank()) != wanted.reverse() => {}
            _ => {
                nearest_kind.clear();
                nearest_kind.push((*at, cell));
            }
        }
    }
    let mut best: Option<(u64, Item<'_>)> = None;
    for (at, cell) in nearest_kind {
        let nearer = match best {
            None => true,
            // A strictly nearer candidate replaces the best, so ties keep the first met.
            Some((_, kept)) => order(site, cell, kept)? == wanted.reverse(),
        };
        if nearer {
            best = Some((at, cell));
        }
    }
    // Blank cells sort after every other value: they are the next larger value when no other
    // value is larger.
    match best {
        Some((at, _)) => Ok(Some(at)),
        None if mode == Mode::NextLarger => Ok(held.blank(from_end)),
        None => Ok(None),
    }
}

catalogue/lookup::xmatch_binary.text:
/// XMATCH's binary search (search_mode 2 or -2): see the module documentation.
fn xmatch_binary(
    site: &Site<'_>,
    held: &Held,
    key: Item<'_>,
    mode: Mode,
    descending: bool,
) -> Step<Option<u64>> {
    let (mut lo, mut hi) = (0i64, held.len as i64 - 1);
    let (mut exact, mut candidate) = (None, None);
    while lo <= hi {
        let mid = (lo + hi) / 2;
        let cell = match held.value(mid as u64) {
            Some(value) => item(site, 1, value)?,
            None => Item::Blank,
        };
        let go_left = if cell.rank() == key.rank() && equal(site, cell, key)? {
            exact = Some(mid as u64);
            !descending
        } else if order(site, cell, key)? == Ordering::Less {
            if mode == Mode::NextSmaller {
                candidate = Some(mid as u64);
            }
            descending
        } else {
            if mode == Mode::NextLarger {
                candidate = Some(mid as u64);
            }
            !descending
        };
        if go_left {
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    Ok(exact.or(candidate))
}

catalogue/lookup::modes.text:
/// XMATCH's and XLOOKUP's match_mode and search_mode, each read as a number and rounded down.
/// An unknown mode, and wildcards with a binary search, are #VALUE!; regex matching
/// (match_mode 3) is not modelled.
fn modes(
    site: &Site<'_>,
    match_mode: Option<(usize, &CalcValue)>,
    search_mode: Option<(usize, &CalcValue)>,
) -> Step<(Mode, Search)> {
    let read = |argument: Option<(usize, &CalcValue)>, default: f64| -> Step<f64> {
        match argument {
            None => Ok(default),
            Some((_, value)) if value.is_missing() || value.is_empty() => Ok(0.0),
            Some((index, value)) => index_number(site, index, value).map(f64::floor),
        }
    };
    let mode_number = read(match_mode, 0.0)?;
    let search_number = match search_mode {
        Some((_, value)) if value.is_missing() => 1.0,
        _ => read(search_mode, 1.0)?,
    };
    let invalid = || Exit::Error(WorksheetErrorCode::Value);
    let mode = match mode_number {
        0.0 => Mode::Exact,
        -1.0 => Mode::NextSmaller,
        1.0 => Mode::NextLarger,
        2.0 => Mode::Wildcard,
        3.0 => return Err(site.not_modelled(match_mode.map(|(index, _)| index))),
        _ => return Err(invalid()),
    };
    let search = match search_number {
        1.0 => Search::FirstToLast,
        -1.0 => Search::LastToFirst,
        2.0 => Search::Ascending,
        -2.0 => Search::Descending,
        _ => return Err(invalid()),
    };
    if mode == Mode::Wildcard && matches!(search, Search::Ascending | Search::Descending) {
        return Err(invalid());
    }
    Ok((mode, search))
}

catalogue/lookup::xsearch.text:
/// XMATCH's search of `line` for `key`.
fn xsearch(
    site: &Site<'_>,
    services: &mut EvalServices<'_>,
    line: Line<'_>,
    key: Item<'_>,
    mode: Mode,
    search: Search,
) -> Step<Option<u64>> {
    match search {
        Search::FirstToLast => xmatch_linear(site, services, line, key, mode, false),
        Search::LastToFirst => xmatch_linear(site, services, line, key, mode, true),
        Search::Ascending | Search::Descending => {
            let held = line.held(site, services)?;
            xmatch_binary(site, &held, key, mode, search == Search::Descending)
        }
    }
}

catalogue/lookup::xlookup.text:
/// XLOOKUP(lookup_value, lookup_array, return_array, [if_not_found], [match_mode],
/// [search_mode]): XMATCH's search of lookup_array, and the matching row (a vertical lookup
/// array) or column (a horizontal one) of return_array, which must have as many rows or columns:
/// a reference into return_array when it is one, else the array's part. With no match the result
/// is if_not_found as it is, or #N/A when it is omitted. A lookup array of one cell selects the
/// whole of a return array of one row, else of one column; a return array of more rows and columns
/// is #VALUE! for it. A blank or omitted lookup or return array is #VALUE! in its argument's turn,
/// before the modes are read; the shape rules apply after them.
fn xlookup(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    let site = Site::new(XLOOKUP, services);
    Site::finish(xlooked_up(&site, arguments, services))
}

catalogue/lookup::xlooked_up.text:
fn xlooked_up(
    site: &Site<'_>,
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Step<CalcValue> {
    let key = lookup_key(site, &arguments[0], BlankKey::Blank)?;
    let lookup_grid = match shape(&arguments[1], 1) {
        Shape::Error(code) => return Err(Exit::Error(code)),
        Shape::Areas => None,
        Shape::Blank => return Err(Exit::Error(WorksheetErrorCode::Value)),
        Shape::Grid(grid) => Some(grid),
    };
    let return_grid = match shape(&arguments[2], 2) {
        Shape::Error(code) => return Err(Exit::Error(code)),
        Shape::Areas => None,
        Shape::Blank => return Err(Exit::Error(WorksheetErrorCode::Value)),
        Shape::Grid(grid) => Some(grid),
    };
    let (mode, search) = modes(
        site,
        arguments.get(4).map(|value| (4, value)),
        arguments.get(5).map(|value| (5, value)),
    )?;
    let (Some(lookup_grid), Some(return_grid)) = (lookup_grid, return_grid) else {
        return Err(Exit::Error(WorksheetErrorCode::NA));
    };
    let value_error = Exit::Error(WorksheetErrorCode::Value);
    let line = lookup_grid
        .line()
        .ok_or(Exit::Error(WorksheetErrorCode::Value))?;
    let (rows, columns) = (lookup_grid.rows(), lookup_grid.columns());
    // Whether the result is a row of the return array (true) or a column.
    let by_row = if rows == 1 && columns == 1 {
        if return_grid.rows() == 1 {
            true
        } else if return_grid.columns() == 1 {
            false
        } else {
            return Err(value_error);
        }
    } else if columns == 1 {
        if return_grid.rows() != rows {
            return Err(value_error);
        }
        true
    } else {
        if return_grid.columns() != columns {
            return Err(value_error);
        }
        false
    };
    let Some(at) = xsearch(site, services, line, key, mode, search)? else {
        return match arguments.get(3) {
            Some(fallback) if !fallback.is_missing() => Ok(fallback.clone()),
            _ => Err(Exit::Error(WorksheetErrorCode::NA)),
        };
    };
    Ok(part(&arguments[2], return_grid, by_row, at))
}

catalogue/lookup::part.text:
/// Row (`by_row`) or column `at` (0-based) of a return grid: a reference into its area, or the
/// array's part, or the single value.
fn part(original: &CalcValue, grid: Grid<'_>, by_row: bool, at: u64) -> CalcValue {
    match grid {
        Grid::Area { area, .. } => {
            let first = area.first();
            let last = area.last();
            let selected = if by_row {
                let row = first.row() + at as u32;
                span(area, (row, first.column()), (row, last.column()))
            } else {
                let column = first.column() + at as u32;
                span(area, (first.row(), column), (last.row(), column))
            };
            CalcValue::reference(ReferenceLike::area(selected))
        }
        Grid::Array(array) => {
            let shape = array.shape();
            let cells: Vec<CalcValue> = if by_row {
                array
                    .row_slice(at as usize)
                    .expect("a row of the array")
                    .to_vec()
            } else {
                (0..shape.rows)
                    .map(|row| {
                        array
                            .get(row, at as usize)
                            .expect("a cell of the array")
                            .clone()
                    })
                    .collect()
            };
            if cells.len() == 1 {
                return cells.into_iter().next().expect("one cell");
            }
            let shape = if by_row {
                ArrayShape {
                    rows: 1,
                    cols: cells.len(),
                }
            } else {
                ArrayShape {
                    rows: cells.len(),
                    cols: 1,
                }
            };
            CalcValue::array(CalcArray::new(shape, cells).expect("a row or column"))
        }
        Grid::One(_) => original.clone(),
    }
}

catalogue/lookup::xmatch.text:
/// XMATCH(lookup_value, lookup_array, [match_mode], [search_mode]): the 1-based position, by the
/// modes the module documentation describes. A lookup array of more than one row and column is
/// #VALUE!, a reference of several areas #N/A; a single value is a line of one cell. A blank or
/// omitted lookup array is #VALUE! in its argument's turn, before the modes are read.
fn xmatch(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    let site = Site::new(XMATCH, services);
    Site::finish(xmatched(&site, arguments, services))
}

catalogue/lookup::xmatched.text:
fn xmatched(
    site: &Site<'_>,
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Step<CalcValue> {
    let key = lookup_key(site, &arguments[0], BlankKey::Blank)?;
    let grid = match shape(&arguments[1], 1) {
        Shape::Error(code) => return Err(Exit::Error(code)),
        Shape::Areas => None,
        Shape::Blank => return Err(Exit::Error(WorksheetErrorCode::Value)),
        Shape::Grid(grid) => Some(grid),
    };
    let (mode, search) = modes(
        site,
        arguments.get(2).map(|value| (2, value)),
        arguments.get(3).map(|value| (3, value)),
    )?;
    let Some(grid) = grid else {
        return Err(Exit::Error(WorksheetErrorCode::NA));
    };
    let line = grid.line().ok_or(Exit::Error(WorksheetErrorCode::Value))?;
    match xsearch(site, services, line, key, mode, search)? {
        Some(at) => position(site, at),
        None => Err(Exit::Error(WorksheetErrorCode::NA)),
    }
}

