fn z_test_of(site: &Site<'_>, a: &[CalcValue], sv: &mut EvalServices<'_>) -> Step<CalcValue> {
    // Literal text is coerced while binding the first argument; references and
    // arrays are read only after the scalar arguments have been validated.
    let literal_sample = if matches!(a[0].core_ref(), CoreRef::Text(_)) {
        Some(sample(site, a, 0, sv)?)
    } else {
        None
    };
    let x = num(site, a, 1)?;
    let sigma = if given(a, 2) {
        Some(num(site, a, 2)?)
    } else {
        None
    };
    let values = match literal_sample {
        Some(values) => values,
        None => sample(site, a, 0, sv)?,
    };
    out(site, ct::z_test_kernel(&values, x, sigma))
}

ported/confidence_test_family::z_test_ke.text:
pub fn z_test_kernel(
    values: &[f64],
    x: f64,
    sigma: Option<f64>,
) -> Result<f64, WorksheetErrorCode> {
    if !x.is_finite() {
        return Err(WorksheetErrorCode::Value);
    }
    // Excel checks the sample count even when a population sigma is supplied.
    if values.is_empty() {
        return Err(WorksheetErrorCode::NA);
    }
    if values.len() == 1 {
        return Err(WorksheetErrorCode::Div0);
    }
    let mean = values.iter().sum::<f64>() / values.len() as f64;
    let sigma = match sigma {
        Some(value) => value,
        None => stdev_from_values(values, VarianceDivisor::Sample)?,
    };
    if sigma <= 0.0 || !sigma.is_finite() {
        return Err(WorksheetErrorCode::Num);
    }
    // Live Excel 16.0 b20326: Z.TEST(array,x) with omitted sigma is
    // NORMSDIST((x-AVERAGE)/(STDEV.S/SQRT(n))), not 1-NORMSDIST((mean-x)/se)
    // and not STDEV.P. The two NORMSDIST complements are not bit-identical.
    // F1 (dc-8dq): (x - mean) * sqrt(n) / sigma, as Excel's Z.TEST gives Z.TEST({1,5,3},2) (the
    // catalogue oracle's capture); dividing by sigma/sqrt(n) is one ulp away there.
    let z = (x - mean) * (values.len() as f64).sqrt() / sigma;
    crate::ported::normal_log_family::norm_s_dist_kernel(z, true)
}

catalogue/arithmetic::power.text:
fn power(
    arguments: &[CalcValue],
    services: &mut EvalServices<'_>,
) -> Result<CalcValue, FunctionFault> {
    let site = Site::new(POWER, services);
    Site::finish(operands(&site, arguments).and_then(|(x, y)| {
        if x.is_subnormal() {
            site.number(flushed(raise(&site, x, y)?))
        } else {
            power_value(&site, x, y)
        }
    }))
}
